def is_feature_enabled(key, user_id=None, default=False) -> bool:
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            "SELECT enabled FROM feature_flags WHERE key=? AND (scope='all' OR scope=?)",
            (str(key), str(user_id or "all"))
        )
        row = c.fetchone()
        if row is None:
            return bool(default)
        return bool(int(row[0] or 0))
    except Exception:
        return bool(default)
    finally:
        if conn:
            conn.close()

def db_file_health_label() -> str:
    base = os.path.basename(str(DB_FILE or ""))
    if not base:
        return "not_configured"
    return base if str(DB_FILE) == base else f"configured:{base}"

def record_credit_event(conn, user_id, delta, event_type, ref_id="", note=""):
    c = conn.cursor()
    c.execute("SELECT credits FROM users WHERE user_id=?", (str(user_id),))
    row = c.fetchone()
    balance_after = row[0] if row else 0
    c.execute(
        "INSERT INTO credit_events (user_id, delta, balance_after, event_type, ref_id, note, created_at) VALUES (?,?,?,?,?,?,?)",
        (str(user_id), int(delta), balance_after, event_type, str(ref_id), note, now_text())
    )
    usage_type = "trial_granted" if str(event_type) == "trial_grant" else ("xu_credit" if int(delta or 0) > 0 else "xu_debit" if int(delta or 0) < 0 else "")
    if usage_type:
        record_usage_event_conn(
            conn,
            user_id,
            event_type=usage_type,
            tool_name="credits",
            status=str(event_type or ""),
            xu_delta=int(delta or 0),
            detail=f"{event_type}; ref={ref_id}; {note}",
        )

USER_LANGUAGE_LABELS = {
    "vi": "Tiếng Việt",
    "en": "English",
    "zh": "中文",
    "ja": "日本語",
    "ko": "한국어",
    "th": "ไทย",
    "ar": "العربية",
}
PRIMARY_USER_LANGUAGES = ("vi", "en", "zh")
OTHER_USER_LANGUAGES = ("ja", "ko", "th", "ar")

def normalize_user_language(lang: str | None) -> str:
    value = str(lang or "").strip().lower()
    aliases = {
        "vn": "vi",
        "vie": "vi",
        "vietnamese": "vi",
        "english": "en",
        "us": "en",
        "cn": "zh",
        "zh-cn": "zh",
        "chinese": "zh",
        "jp": "ja",
        "japanese": "ja",
        "kr": "ko",
        "korean": "ko",
        "thai": "th",
        "arabic": "ar",
    }
    value = aliases.get(value, value)
    return value if value in USER_LANGUAGE_LABELS else ""

def get_user_language(user_id) -> str:
    uid = str(user_id)
    conn = db_connect()
    try:
        cur = conn.cursor()
        try:
            cur.execute("SELECT user_language FROM users WHERE user_id=?", (uid,))
            row = cur.fetchone()
        except sqlite3.OperationalError:
            row = None
        return normalize_user_language(row[0] if row else "")
    finally:
        conn.close()

def set_user_language(user_id, lang) -> str:
    uid = str(user_id)
    selected = normalize_user_language(lang) or "vi"
    get_user(uid)
    conn = db_connect()
    try:
        conn.execute("UPDATE users SET user_language=? WHERE user_id=?", (selected, uid))
        conn.commit()
    finally:
        conn.close()
    return selected

def has_user_language(user_id) -> bool:
    return bool(get_user_language(user_id))

def user_language_label(lang: str) -> str:
    return USER_LANGUAGE_LABELS.get(normalize_user_language(lang), USER_LANGUAGE_LABELS["vi"])

