PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT = "standard_sorted"
PAYOS_CREATE_SIGNATURE_FIELDS = ("amount", "cancelUrl", "description", "orderCode", "returnUrl")
PAYOS_CREATE_SIGNATURE_VARIANTS = {
    "standard_sorted": PAYOS_CREATE_SIGNATURE_FIELDS,
    "faq_order": ("amount", "orderCode", "description", "returnUrl", "cancelUrl"),
    "payload_order": ("orderCode", "amount", "description", "cancelUrl", "returnUrl"),
}
PAYOS_OFFICIAL_CREATE_SIGNATURE_NOTE = (
    "Official payOS create payment link signature data: "
    "amount,cancelUrl,description,orderCode,returnUrl"
)
PAYOS_CREATE_PAYMENT_ENDPOINT = "https://api-merchant.payos.vn/v2/payment-requests"
PAYOS_DEBUG_SIGNATURE_VARIANTS = ("standard_sorted",)

def normalize_payos_signature_variant(variant: str | None) -> str:
    variant = str(variant or "").strip().lower()
    if variant in PAYOS_CREATE_SIGNATURE_VARIANTS or variant == "sorted_all_payload_keys":
        return variant
    return PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT

def payos_signature_fields_for_variant(payload: dict, variant: str | None = None) -> tuple[str, ...]:
    variant = normalize_payos_signature_variant(variant)
    if variant == "sorted_all_payload_keys":
        return tuple(sorted(key for key in payload.keys() if key != "signature"))
    return PAYOS_CREATE_SIGNATURE_VARIANTS[variant]

def build_payos_signature_data(payload: dict, variant: str | None = None) -> str:
    fields = payos_signature_fields_for_variant(payload, variant)
    missing = [key for key in fields if key not in payload]
    if missing:
        raise KeyError(f"Missing PayOS signature field(s): {', '.join(missing)}")
    return "&".join(f"{key}={payload[key]}" for key in fields)

def payos_payload_type_summary(payload: dict) -> str:
    return (
        f"orderCode type={type(payload.get('orderCode')).__name__}; "
        f"amount type={type(payload.get('amount')).__name__}; "
        f"description length={len(str(payload.get('description') or ''))}; "
        f"cancelUrl={payload.get('cancelUrl')}; "
        f"returnUrl={payload.get('returnUrl')}"
    )

def mask_payos_signature(signature: str) -> str:
    signature = str(signature or "")
    if len(signature) <= 16:
        return "***" if signature else "missing"
    return signature[:8] + "***" + signature[-8:]

def mask_key_fingerprint(value: str) -> str:
    value = str(value or "")
    if not value:
        return "missing"
    if len(value) <= 8:
        return value[:2] + "***" + value[-2:]
    return value[:4] + "***" + value[-4:]

def env_strip_diagnostic(name: str, value: str) -> dict:
    raw = os.environ.get(name, "")
    stripped = str(raw or "").strip()
    return {
        "configured": bool(str(value or "")),
        "raw_len": len(str(raw or "")),
        "stripped_len": len(stripped),
        "stripped_differs": str(raw or "") != stripped,
    }

def payos_header_debug_summary() -> list[str]:
    return [
        f"• x-client-id: <code>{'yes' if PAYOS_CLIENT_ID else 'no'}</code>",
        f"• x-api-key: <code>{'yes' if PAYOS_API_KEY else 'no'}</code>",
        "• Content-Type: <code>application/json</code>",
    ]

def payos_sdk_availability() -> tuple[bool, str]:
    for module_name in ("payos", "payos_sdk"):
        try:
            __import__(module_name)
            return True, module_name
        except Exception:
            continue
    return False, ""

def get_payos_create_signature_variant() -> str:
    # Customer payment creation must always use the PayOS documented order.
    # Debug variants are admin-only and must not override live /naptien.
    return PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT

def sign_payos_payment_request(data: dict, variant: str | None = None) -> tuple[str, str]:
    raw_str = build_payos_signature_data(data, variant or PAYOS_CREATE_SIGNATURE_DEFAULT_VARIANT)
    signature = hmac.new(
        PAYOS_CHECKSUM_KEY.encode("utf-8"),
        raw_str.encode("utf-8"),
        hashlib.sha256
    ).hexdigest()
    return signature, raw_str

def parse_payos_response_safe(res) -> tuple[dict, str]:
    try:
        data = res.json()
        if isinstance(data, dict):
            return data, ""
        return {}, str(data)[:500]
    except Exception:
        return {}, (getattr(res, "text", "") or "")[:500]

def format_payos_create_debug(
    http_status,
    res_data: dict,
    raw_preview: str,
    order_code: int,
    amount: int,
    description: str,
    cancel_url: str,
    return_url: str,
    signature_data: str,
    signature_variant: str = "standard",
    html_mode: bool = False,
) -> str:
    data = res_data if isinstance(res_data, dict) else {}
    payos_code = data.get("code", "")
    payos_desc = data.get("desc", "") or data.get("description", "")
    payos_message = data.get("message", "")
    if isinstance(data.get("data"), dict):
        payos_message = payos_message or data["data"].get("message", "") or data["data"].get("desc", "")
    if html_mode:
        def val(value):
            return f"<code>{html.escape(str(value))}</code>"
        signature_line = f"<code>{html.escape(signature_data)}</code>"
        raw_line = f"\nRaw: {val(raw_preview[:500])}" if raw_preview else ""
    else:
        def val(value):
            return str(value)
        signature_line = str(signature_data)
        raw_line = f"\nRaw: {raw_preview[:500]}" if raw_preview else ""
    return (
        f"HTTP: {val(http_status or 'UNKNOWN')}\n"
        f"Code: {val(payos_code or '')}\n"
        f"Desc: {val(payos_desc or '')}\n"
        f"Message: {val(payos_message or '')}\n"
        f"Order: {val(order_code)}\n"
        f"Amount: {val(amount)}\n"
        f"Description: {val(description)}\n"
        f"Cancel URL: {val(cancel_url)}\n"
        f"Return URL: {val(return_url)}\n"
        f"Signature variant: {val(signature_variant)}\n"
        f"Signature data:\n{signature_line}"
        f"{raw_line}"
    )

async def create_payos_payment_request(payos_body: dict, signature_variant: str | None = None) -> tuple[object, dict, str, str]:
    # Live checkout creation follows payOS official/SDK create-payment signature order:
    # amount, cancelUrl, description, orderCode, returnUrl. Do not URL-encode before signing.
    active_variant = normalize_payos_signature_variant(signature_variant) if signature_variant else get_payos_create_signature_variant()
    signature, raw_str = sign_payos_payment_request(payos_body, active_variant)
    request_body = {**payos_body, "signature": signature}
    headers = {
        "x-client-id": PAYOS_CLIENT_ID,
        "x-api-key": PAYOS_API_KEY,
        "Content-Type": "application/json"
    }
    async with httpx.AsyncClient() as client:
        res = await client.post(
            PAYOS_CREATE_PAYMENT_ENDPOINT,
            headers=headers,
            json=request_body,
            timeout=30.0
        )
    res_data, raw_preview = parse_payos_response_safe(res)
    return res, res_data, raw_preview, raw_str

