async def maybe_auto_grant_birthday_gift(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user:
        return None
    uid = update.effective_user.id
    try:
        status = birthday_gift_status(uid)
        if status.get("state") != "eligible":
            return status
        conn = db_connect()
        try:
            conn.execute("BEGIN IMMEDIATE")
            result = grant_birthday_gift(conn, uid, actor_id="system", admin_override=False)
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()
        if result.get("granted"):
            await context.bot.send_message(chat_id=update.effective_chat.id, text=format_birthday_gift_message(result), parse_mode="HTML")
        return status
    except Exception as e:
        logger.warning(f"Birthday auto check failed: {e}")
        return {"state": "error", "error": str(e)[:160]}

def promo_policy_by_code(code: str) -> dict:
    norm = normalize_promo_code(code)
    for item in PROMO_POLICY_CODES:
        if item["code"] == norm:
            return dict(item)
    return {}

def promo_public_label(promo: dict) -> str:
    promo_type = promo.get("promo_type") or "fixed_bonus_xu"
    value = int(promo.get("value") or promo.get("bonus_xu") or 0)
    if promo_type in {"percent_bonus", "tier_up"}:
        return f"+{value}% Xu dịch vụ"
    if promo_type == "fixed_bonus_xu":
        return f"+{value} Xu dịch vụ"
    if promo_type == "gift_xu":
        return f"quà +{value} Xu dịch vụ"
    if promo_type == "service_discount_future":
        return "ưu đãi dịch vụ tương lai"
    return f"+{value} Xu dịch vụ"

def is_gift_promo(promo: dict) -> bool:
    return str((promo or {}).get("promo_type") or "").lower() == "gift_xu"

def is_beta_gift_code(code: str) -> bool:
    return normalize_promo_code(code).startswith("BETA")

def gift_requires_assignment(promo: dict) -> bool:
    if not is_gift_promo(promo):
        return False
    if is_beta_gift_code(promo.get("code") or ""):
        return True
    value = promo.get("requires_assignment")
    return int(value or 0) == 1

def promo_min_amount(promo: dict) -> int:
    return int(promo.get("min_amount_vnd") or promo.get("min_amount") or 0)

def promo_usage_limit(promo: dict) -> int:
    return int(promo.get("usage_limit") or promo.get("max_uses") or 0)

def promo_usage_count(promo: dict) -> int:
    return max(int(promo.get("usage_count") or 0), int(promo.get("used_count") or 0))

def vn_now():
    return datetime.now(VN_TZ)

def vn_now_text() -> str:
    return vn_now().strftime("%Y-%m-%d %H:%M:%S")

def promo_period_type(code: str) -> str:
    code = normalize_promo_code(code)
    if code in {PROMO_FIRST_TOPUP_CODE, PROMO_SECOND_TOPUP_CODE}:
        return "lifetime"
    if code == PROMO_DAILY_CODE:
        return "daily"
    if code == PROMO_WEEKLY_CODE:
        return "weekly"
    if code == PROMO_MONTHLY_CODE:
        return "monthly"
    return "lifetime"

def promo_period_key(code: str, dt=None) -> str:
    dt = dt or vn_now()
    if getattr(dt, "tzinfo", None) is None:
        dt = dt.replace(tzinfo=VN_TZ)
    else:
        dt = dt.astimezone(VN_TZ)
    ptype = promo_period_type(code)
    if ptype == "daily":
        return f"daily:{dt.strftime('%Y-%m-%d')}"
    if ptype == "weekly":
        iso_year, iso_week, _ = dt.isocalendar()
        return f"weekly:{iso_year}-W{iso_week:02d}"
    if ptype == "monthly":
        return f"monthly:{dt.strftime('%Y-%m')}"
    return "lifetime"

def next_promo_reset_at(code: str, dt=None):
    dt = dt or vn_now()
    if getattr(dt, "tzinfo", None) is None:
        dt = dt.replace(tzinfo=VN_TZ)
    else:
        dt = dt.astimezone(VN_TZ)
    ptype = promo_period_type(code)
    if ptype == "daily":
        target = (dt + timedelta(days=1)).date()
        return datetime(target.year, target.month, target.day, 0, 0, 0, tzinfo=VN_TZ)
    if ptype == "weekly":
        days_until_monday = (7 - dt.weekday()) % 7
        if days_until_monday == 0:
            days_until_monday = 7
        target = (dt + timedelta(days=days_until_monday)).date()
        return datetime(target.year, target.month, target.day, 0, 0, 0, tzinfo=VN_TZ)
    if ptype == "monthly":
        if dt.month == 12:
            return datetime(dt.year + 1, 1, 1, 0, 0, 0, tzinfo=VN_TZ)
        return datetime(dt.year, dt.month + 1, 1, 0, 0, 0, tzinfo=VN_TZ)
    return dt + timedelta(hours=PROMO_DEFAULT_EXPIRY_HOURS)

def promo_pending_expires_at(code: str) -> str:
    default_expire = vn_now() + timedelta(hours=PROMO_DEFAULT_EXPIRY_HOURS)
    if promo_period_type(code) in {"daily", "weekly", "monthly"}:
        default_expire = min(default_expire, next_promo_reset_at(code))
    return default_expire.strftime("%Y-%m-%d %H:%M:%S")

def promo_period_used(conn, user_id, code: str, period_key: str = "") -> bool:
    c = conn.cursor()
    c.execute(
        """SELECT 1 FROM promo_usage_periods
        WHERE user_id=? AND code=? AND period_key=? AND status='applied'
        LIMIT 1""",
        (str(user_id), normalize_promo_code(code), period_key or promo_period_key(code)),
    )
    return c.fetchone() is not None

def get_promo_code(conn, code: str):
    c = conn.cursor()
    c.execute(
        """SELECT code, bonus_xu, discount_percent, max_uses, used_count, min_amount, status, note
        FROM promotion_codes WHERE code=?""",
        (normalize_promo_code(code),),
    )
    return c.fetchone()

def get_promo_code_dict(conn, code: str) -> dict:
    c = conn.cursor()
    c.execute(
        """SELECT code, bonus_xu, discount_percent, max_uses, used_count, min_amount, status, note,
                  name, promo_type, value, min_amount_vnd, max_bonus_xu, usage_limit, usage_count,
                  per_user_limit, starts_at, ends_at, created_at, updated_at, requires_assignment, owner_user_id
        FROM promotion_codes WHERE code=?""",
        (normalize_promo_code(code),),
    )
    row = c.fetchone()
    if not row:
        return {}
    keys = [
        "code", "bonus_xu", "discount_percent", "max_uses", "used_count", "min_amount", "status", "note",
        "name", "promo_type", "value", "min_amount_vnd", "max_bonus_xu", "usage_limit", "usage_count",
        "per_user_limit", "starts_at", "ends_at", "created_at", "updated_at", "requires_assignment", "owner_user_id",
    ]
    promo = dict(zip(keys, row))
    if not promo.get("promo_type"):
        promo["promo_type"] = "percent_bonus" if int(promo.get("discount_percent") or 0) > 0 else "fixed_bonus_xu"
    if not int(promo.get("value") or 0):
        promo["value"] = int(promo.get("discount_percent") or promo.get("bonus_xu") or 0)
    if not int(promo.get("min_amount_vnd") or 0):
        promo["min_amount_vnd"] = int(promo.get("min_amount") or 0)
    if not int(promo.get("usage_limit") or 0):
        promo["usage_limit"] = int(promo.get("max_uses") or 0)
    if not int(promo.get("usage_count") or 0):
        promo["usage_count"] = int(promo.get("used_count") or 0)
    promo["per_user_limit"] = max(1, int(promo.get("per_user_limit") or 1))
    return promo

def seed_promotion_policy(conn=None) -> dict:
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    c = conn.cursor()
    now = now_text()
    seeded = {}
    for item in PROMO_POLICY_CODES:
        code = normalize_promo_code(item["code"])
        promo_type = item["promo_type"]
        value = int(item["value"])
        usage_limit = int(item["usage_limit"])
        min_amount_vnd = int(item["min_amount_vnd"])
        max_bonus_xu = int(item["max_bonus_xu"])
        per_user_limit = int(item["per_user_limit"])
        bonus_xu = value if promo_type == "fixed_bonus_xu" else 0
        discount_percent = value if promo_type == "percent_bonus" else 0
        c.execute(
            """INSERT INTO promotion_codes
            (code, bonus_xu, discount_percent, max_uses, used_count, min_amount, status, note, created_at, updated_at,
             name, promo_type, value, min_amount_vnd, max_bonus_xu, usage_limit, usage_count, per_user_limit, created_by)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(code) DO UPDATE SET
                bonus_xu=excluded.bonus_xu,
                discount_percent=excluded.discount_percent,
                max_uses=excluded.max_uses,
                min_amount=excluded.min_amount,
                status='active',
                note=excluded.note,
                updated_at=excluded.updated_at,
                name=excluded.name,
                promo_type=excluded.promo_type,
                value=excluded.value,
                min_amount_vnd=excluded.min_amount_vnd,
                max_bonus_xu=excluded.max_bonus_xu,
                usage_limit=excluded.usage_limit,
                per_user_limit=excluded.per_user_limit""",
            (
                code, bonus_xu, discount_percent, usage_limit, 0, min_amount_vnd, "active", item["note"], now, now,
                item["name"], promo_type, value, min_amount_vnd, max_bonus_xu, usage_limit, 0, per_user_limit, ADMIN_ID,
            ),
        )
        seeded[code] = item
    for code in PROMO_LEGACY_DISABLE_CODES:
        c.execute(
            "UPDATE promotion_codes SET status='disabled', updated_at=? WHERE code=?",
            (now, normalize_promo_code(code)),
        )
    if own_conn:
        conn.commit()
        conn.close()
    return seeded

def seed_beta_promotions(conn=None) -> dict:
    return seed_promotion_policy(conn)

