def operator_mission_inbox_data(owner_id, limit=10):
    rows = list_operator_missions(owner_id, limit=limit)
    queued = [serialize_operator_mission(row) for row in rows]
    next_pack = None
    next_row = None
    for row in rows:
        if row[4] >= 1 and row[5] == "queued":
            next_row = row
            break
    if next_row:
        next_pack = operator_mission_prompt_pack_data(owner_id, mission_id=next_row[0], claim=False)
    return {
        "ok": True,
        "missions": queued,
        "next_prompt_pack": next_pack,
        "commands": {
            "add": "/mission_add title=... platform=tiktok priority=8 objective=...",
            "list": "/missions",
            "claim": "/mission_claim worker=claude",
            "run": "/mission_run id=<MISSION_ID> execute=1",
            "work_orders": "/mission_workorders id=<MISSION_ID>",
            "api_claim": "/api/operator/missions/claim",
            "api_work_orders": "/api/operator/missions/<MISSION_ID>/work-orders",
        },
        "rule": "Mission inbox nhận lệnh cấp cao từ admin. Claude/n8n claim mission rồi tự gọi endpoint operator, nhưng publish vẫn phải qua gate duyệt.",
    }

def extract_operator_job_ids(payload, limit=20):
    job_ids = []

    def add_job_id(value):
        try:
            job_id = int(value or 0)
        except (TypeError, ValueError):
            job_id = 0
        if job_id > 0 and job_id not in job_ids:
            job_ids.append(job_id)

    def walk(value):
        if len(job_ids) >= limit:
            return
        if isinstance(value, dict):
            for key in ("job_id", "row_job_id", "first_job_id", "focus_job_id"):
                if key in value:
                    add_job_id(value.get(key))
            job_payload = value.get("job")
            if isinstance(job_payload, dict):
                add_job_id(job_payload.get("id"))
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)

    walk(payload or {})
    return job_ids[:limit]

def operator_mission_work_orders_data(owner_id, mission_id=0, result_payload=None, limit=8, include_prompt=True):
    base_url = (PUBLIC_BASE_URL or "https://<RAILWAY_DOMAIN>").rstrip("/")
    mission = None
    payload = result_payload or {}
    if mission_id:
        row = get_operator_mission(owner_id, mission_id)
        mission = serialize_operator_mission(row)
        if not payload and mission:
            saved_result = mission.get("result") or {}
            execution = saved_result.get("execution") or {}
            payload = execution.get("data") or saved_result

    job_ids = extract_operator_job_ids(payload, limit=limit)
    work_orders = []
    for job_id in job_ids:
        job = get_production_job(job_id, owner_id)
        if not job:
            continue
        readiness = production_readiness_data(owner_id, job_id)
        acceptance = operator_output_acceptance_data(owner_id, job_id=job_id)
        next_task = next_worker_task(owner_id, job_id=job_id)
        next_task_payload = serialize_operator_task(next_task) if next_task else None
        prompt_pack = operator_task_prompt_pack_data(owner_id, task_id=int(next_task[0])) if include_prompt and next_task else None
        tasks = [serialize_operator_task(get_production_task(owner_id, row[0])) for row in list_production_tasks(owner_id, job_id=job_id, limit=40)]
        serialized_job = serialize_production_job(job)
        first_task_id = int(next_task[0]) if next_task else 0
        work_orders.append({
            "job_id": job_id,
            "job": serialized_job,
            "state": {
                "readiness": (readiness or {}).get("level", "UNKNOWN"),
                "next_action": (readiness or {}).get("next_action", ""),
                "accepted": acceptance.get("accepted"),
                "blocking": acceptance.get("blocking", [])[:8],
            },
            "next_task": next_task_payload,
            "tasks": [task for task in tasks if task],
            "prompt_pack": prompt_pack,
            "worker_urls": {
                "job_context": f"{base_url}/api/operator/jobs/{job_id}/context",
                "worker_pack": f"{base_url}/api/operator/jobs/{job_id}/worker-pack" + (f"?task_id={first_task_id}" if first_task_id else ""),
                "pipeline_pack": f"{base_url}/api/operator/jobs/{job_id}/pipeline-pack",
                "distribution_pack": f"{base_url}/api/operator/jobs/{job_id}/distribution-pack",
                "review_video": f"{base_url}/api/operator/jobs/{job_id}/review-video",
                "output_acceptance": f"{base_url}/api/operator/output-acceptance?job_id={job_id}" + (f"&task_id={first_task_id}" if first_task_id else ""),
                "claim_task": f"{base_url}/api/operator/tasks/claim?job_id={job_id}&include_context=1&include_prompt=1",
                "task_prompt": f"{base_url}/api/operator/tasks/{first_task_id}/prompt-pack" if first_task_id else f"{base_url}/api/operator/tasks/<TASK_ID>/prompt-pack",
                "task_complete": f"{base_url}/api/operator/tasks/{first_task_id}/complete" if first_task_id else f"{base_url}/api/operator/tasks/<TASK_ID>/complete",
                "task_upload": f"{base_url}/api/operator/tasks/{first_task_id}/upload" if first_task_id else f"{base_url}/api/operator/tasks/<TASK_ID>/upload",
            },
            "telegram": {
                "worker_pack": f"/worker_pack job={job_id}" + (f" task={first_task_id}" if first_task_id else ""),
                "task_prompt": f"/task_prompt id={first_task_id}" if first_task_id else "/tasks",
                "tasks": f"/tasks job={job_id}",
                "job_context": f"/job_context job={job_id}",
                "review_video": f"/review_video job={job_id} send=1",
                "output_acceptance": f"/output_acceptance job={job_id}" + (f" task={first_task_id}" if first_task_id else ""),
                "approve_publish": f"/approve_publish job={job_id} queue=1 mode=manual",
            },
            "worker_brief": (
                f"Thực hiện job #{job_id}: đọc worker_pack/prompt_pack, tạo output thật cho next_task, "
                "upload hoặc complete task, sau đó dừng ở review/publish gate."
            ),
        })
    return {
        "ok": True,
        "mission": mission,
        "job_ids": job_ids,
        "work_orders": work_orders,
        "count": len(work_orders),
        "include_prompt": bool(include_prompt),
        "rule": "Work-order là gói giao việc cho Claude/n8n/tool worker: tạo file/video thật, trả output qua upload/complete, không tự publish khi chưa duyệt.",
    }

def select_toolchain_for_task(task_type="", tool=""):
    task_type = (task_type or "").strip().lower()
    tool = (tool or "").strip().lower()
    stage_alias = {
        "proof_asset": "brain_and_script",
        "visual_scene": "video_generation",
        "voice": "voice",
        "edit": "editing",
        "publish": "publishing",
        "review": "editing",
    }
    wanted_stage = stage_alias.get(task_type, task_type)
    for chain in operator_toolchain_data().get("chains", []):
        stage = (chain.get("stage") or "").lower()
        names = [((chain.get("primary") or {}).get("name") or "").lower()]
        names.extend(((fb.get("name") or "").lower()) for fb in (chain.get("fallbacks") or []))
        if stage == wanted_stage or (tool and any(tool in name for name in names)):
            return chain
    return None

def operator_worker_intake_data(owner_id, job_id=0, task_id=0, tool="", claim=False, include_prompt=True, include_context=True):
    try:
        job_id = int(job_id or 0)
    except (TypeError, ValueError):
        job_id = 0
    try:
        task_id = int(task_id or 0)
    except (TypeError, ValueError):
        task_id = 0
    tool = (tool or "").strip().lower()
    base_url = (PUBLIC_BASE_URL or "https://<RAILWAY_DOMAIN>").rstrip("/")
    task = get_production_task(owner_id, task_id) if task_id else None
    if not task:
        task = next_worker_task(owner_id, job_id=job_id or None, tool=tool)
    if not task:
        return {
            "ok": True,
            "mode": "claim" if claim else "peek",
            "task": None,
            "message": "no queued task",
            "next_run": operator_next_run_data(owner_id),
            "mission_inbox": operator_mission_inbox_data(owner_id, limit=5),
            "film_blueprint_url": f"{base_url}/api/operator/film-blueprint",
            "rule": "Không có task queued/waiting. Hãy launch mission/video hoặc xử lý gate trong next_run.",
        }
    did_claim = False
    if claim and (task[8] or "queued").lower() in {"queued", "waiting"}:
        update_production_task(owner_id, task[0], status="working", note=f"worker_intake_claim tool={tool or task[4] or '-'}")
        task = get_production_task(owner_id, task[0])
        did_claim = True
    tid, row_job_id, manifest_id, task_type, task_tool, scene_no, title, prompt, status, output_url, note, updated_at = task
    job = get_production_job(row_job_id, owner_id)
    prompt_pack = operator_task_prompt_pack_data(owner_id, task_id=tid) if include_prompt else None
    worker_pack = operator_worker_pack_data(owner_id, job_id=row_job_id, task_id=tid, tool=tool) if include_context else None
    video_brief = operator_video_brief_data(owner_id, job_id=row_job_id, task_id=tid, tool=tool) if include_context else None
    task_contract = operator_task_contract(tid, task_type, row_job_id)
    toolchain = select_toolchain_for_task(task_type, tool or task_tool)
    film_blueprint = ai_film_series_blueprint_data()
    work_orders = operator_mission_work_orders_data(
        owner_id,
        result_payload={"job_id": row_job_id},
        limit=1,
        include_prompt=include_prompt,
    )
    return {
        "ok": True,
        "mode": "claim" if claim else "peek",
        "claimed": did_claim,
        "job_id": int(row_job_id),
        "task_id": int(tid),
        "job": serialize_production_job(job),
        "task": serialize_operator_task(task),
        "prompt_pack": prompt_pack,
        "prompt_text": (prompt_pack or {}).get("prompt_text", ""),
        "worker_pack": worker_pack,
        "video_brief": video_brief,
        "work_order": ((work_orders.get("work_orders") or [None])[0]),
        "toolchain": {
            "selected": toolchain,
            "policy": operator_toolchain_data().get("policy"),
            "failure_protocol": operator_toolchain_data().get("failure_protocol"),
        },
        "film_blueprint": {
            "url": f"{base_url}/api/operator/film-blueprint",
            "mission": film_blueprint.get("mission"),
            "series_structure": film_blueprint.get("series_structure"),
            "character_bible_contract": film_blueprint.get("character_bible_contract"),
            "storyboard_json_contract": film_blueprint.get("storyboard_json_contract"),
            "template_library": film_blueprint.get("template_library"),
            "affiliate_comment_manager": film_blueprint.get("affiliate_comment_manager"),
            "viral_remix_modes": film_blueprint.get("viral_remix_modes"),
        },
        "submit": {
            "complete_url": f"{base_url}{task_contract.get('complete_url')}",
            "upload_url": f"{base_url}{task_contract.get('upload_url')}",
            "acceptance_url": f"{base_url}{task_contract.get('acceptance_url')}",
            "complete_payload": task_contract.get("complete_payload"),
            "upload_form": task_contract.get("upload_form"),
        },
        "next": {
            "peek": f"{base_url}/api/operator/worker-intake?job_id={int(row_job_id)}&claim=0",
            "claim": f"{base_url}/api/operator/worker-intake?job_id={int(row_job_id)}&claim=1&include_prompt=1",
            "task_prompt": f"{base_url}/api/operator/tasks/{int(tid)}/prompt-pack",
            "job_context": f"{base_url}/api/operator/jobs/{int(row_job_id)}/context",
            "review": f"{base_url}/api/operator/jobs/{int(row_job_id)}/review-video",
        },
        "rule": "Worker intake gom đủ task/prompt/toolchain/film blueprint. claim=0 chỉ xem; claim=1 mới chuyển task sang working. Không tự publish ngoài review/approve gate.",
    }

async def run_operator_mission_data(owner_id, mission_id=0, worker="claude", execute=False, safe_mode=True):
    row = get_operator_mission(owner_id, mission_id) if int(mission_id or 0) else claim_operator_mission(owner_id, worker=worker)
    if not row:
        return {"ok": False, "reason": "mission_not_found_or_empty_queue"}
    mission = serialize_operator_mission(row)
    if mission["status"] == "queued":
        claimed = claim_operator_mission(owner_id, worker=worker)
        if claimed:
            mission = serialize_operator_mission(claimed)
    plan_data = operator_command_plan_data(owner_id, mission["objective"])
    result = {
        "executed": False,
        "message": "execute=false",
    }
    final_status = mission["status"] if mission["status"] in {"working", "queued"} else mission["status"]
    if execute:
        if not plan_data.get("execute_allowed"):
            result = {
                "executed": False,
                "blocked_by_policy": True,
                "message": "Mission intent chưa được whitelist để execute tự động; cần admin/Claude chỉnh prompt hoặc dùng lệnh cụ thể.",
            }
            final_status = "blocked"
        else:
            result = await execute_operator_command_plan(owner_id, plan_data["plan"], safe_mode=safe_mode)
            if result.get("blocked_by_safe_mode"):
                final_status = "blocked"
            elif result.get("executed"):
                final_status = "done"
            else:
                final_status = "working"
        work_orders = operator_mission_work_orders_data(
            owner_id,
            mission_id=mission["id"],
            result_payload=result,
            limit=8,
            include_prompt=True,
        )
        complete_operator_mission(
            owner_id,
            mission["id"],
            status=final_status,
            result={
                "worker": worker,
                "safe_mode": bool(safe_mode),
                "plan": plan_data.get("plan"),
                "preview": plan_data.get("preview"),
                "execution": result,
                "work_orders": {
                    "job_ids": work_orders.get("job_ids") or [],
                    "count": work_orders.get("count") or 0,
                    "urls": [
                        {
                            "job_id": item.get("job_id"),
                            "worker_pack": (item.get("worker_urls") or {}).get("worker_pack"),
                            "task_prompt": (item.get("worker_urls") or {}).get("task_prompt"),
                            "task_complete": (item.get("worker_urls") or {}).get("task_complete"),
                            "task_upload": (item.get("worker_urls") or {}).get("task_upload"),
                        }
                        for item in (work_orders.get("work_orders") or [])
                    ],
                },
            },
            note=result.get("message") or result.get("reason") or "mission_run",
        )
        mission = serialize_operator_mission(get_operator_mission(owner_id, mission["id"]))
    else:
        work_orders = operator_mission_work_orders_data(owner_id, mission_id=mission["id"], limit=8, include_prompt=True)
    return {
        "ok": True,
        "execute": bool(execute),
        "safe_mode": bool(safe_mode),
        "mission": mission,
        "plan": plan_data,
        "result": result,
        "work_orders": work_orders,
        "next": {
            "mission_inbox": "/api/operator/missions",
            "mission_work_orders": f"/api/operator/missions/{mission['id']}/work-orders",
            "run_cycle": "/api/operator/run-cycle",
            "review_gate": "/api/operator/jobs/<JOB_ID>/review-video",
            "publish_gate": "/api/operator/publisher/run",
        },
        "rule": "Mission runner chỉ execute các intent whitelist qua operator executor. Safe mode chặn publish tự động; review/publish vẫn là gate riêng.",
    }

def list_production_jobs(owner_id, limit=20):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT pj.id, pj.stage, pj.status, pj.platform, pj.topic, sc.channel_name, al.product_name, pj.updated_at
        FROM production_jobs pj
        LEFT JOIN social_channels sc ON sc.id = pj.channel_id
        LEFT JOIN affiliate_links al ON al.id = pj.affiliate_id
        WHERE pj.owner_id=?
        ORDER BY pj.id DESC
        LIMIT ?""",
        (str(owner_id), limit)
    )
    rows = c.fetchall()
    conn.close()
    return rows

def operator_dashboard_data(owner_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT COUNT(*) FROM social_channels WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_channels = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM affiliate_links WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_affiliates = c.fetchone()[0]
    c.execute(
        """SELECT status, COUNT(*) FROM content_calendar
        WHERE owner_id=? GROUP BY status""",
        (str(owner_id),)
    )
    calendar_counts = dict(c.fetchall())
    c.execute(
        """SELECT stage, status, COUNT(*) FROM production_jobs
        WHERE owner_id=? GROUP BY stage, status ORDER BY stage, status""",
        (str(owner_id),)
    )
    pipeline_counts = c.fetchall()
    c.execute(
        """SELECT pj.id, pj.stage, pj.status, pj.platform, pj.topic, sc.channel_name, al.product_name, pj.updated_at
        FROM production_jobs pj
        LEFT JOIN social_channels sc ON sc.id = pj.channel_id
        LEFT JOIN affiliate_links al ON al.id = pj.affiliate_id
        WHERE pj.owner_id=? AND pj.status IN ('queued','working','waiting','blocked','ready')
        ORDER BY
            CASE pj.status
                WHEN 'blocked' THEN 0
                WHEN 'waiting' THEN 1
                WHEN 'working' THEN 2
                WHEN 'queued' THEN 3
                ELSE 4
            END,
            pj.updated_at ASC
        LIMIT 10""",
        (str(owner_id),)
    )
    active_jobs = c.fetchall()
    c.execute(
        """SELECT cc.id, cc.post_date, cc.platform, sc.channel_name, cc.topic, cc.status, cc.campaign_id, cc.affiliate_id
        FROM content_calendar cc
        LEFT JOIN social_channels sc ON sc.id = cc.channel_id
        WHERE cc.owner_id=? AND cc.status IN ('planned','in_production')
        ORDER BY cc.post_date ASC, cc.id DESC
        LIMIT 10""",
        (str(owner_id),)
    )
    upcoming_slots = c.fetchall()
    conn.close()
    return active_channels, active_affiliates, calendar_counts, pipeline_counts, active_jobs, upcoming_slots

def operator_daily_data(owner_id, days=1):
    since = (datetime.now() - timedelta(days=max(1, int(days)))).strftime("%Y-%m-%d %H:%M:%S")
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT status, COUNT(*) FROM production_jobs
        WHERE owner_id=? AND created_at>=?
        GROUP BY status ORDER BY status""",
        (str(owner_id), since)
    )
    job_status_counts = c.fetchall()
    c.execute(
        """SELECT stage, COUNT(*) FROM production_jobs
        WHERE owner_id=? AND updated_at>=?
        GROUP BY stage ORDER BY stage""",
        (str(owner_id), since)
    )
    job_stage_counts = c.fetchall()
    c.execute(
        """SELECT status, COUNT(*) FROM publish_queue
        WHERE owner_id=? AND updated_at>=?
        GROUP BY status ORDER BY status""",
        (str(owner_id), since)
    )
    queue_status_counts = c.fetchall()
    c.execute(
        """SELECT event_type, COALESCE(SUM(value),0), COALESCE(SUM(amount),0), COUNT(*)
        FROM performance_events
        WHERE owner_id=? AND created_at>=?
        GROUP BY event_type ORDER BY event_type""",
        (str(owner_id), since)
    )
    performance_counts = c.fetchall()
    c.execute(
        """SELECT pj.id, pj.stage, pj.status, pj.platform, pj.topic, sc.channel_name, al.product_name, pj.updated_at
        FROM production_jobs pj
        LEFT JOIN social_channels sc ON sc.id = pj.channel_id
        LEFT JOIN affiliate_links al ON al.id = pj.affiliate_id
        WHERE pj.owner_id=? AND pj.updated_at>=?
        ORDER BY pj.updated_at DESC, pj.id DESC
        LIMIT 8""",
        (str(owner_id), since)
    )
    recent_jobs = c.fetchall()
    c.execute(
        """SELECT pq.id, pq.job_id, pq.platform, sc.channel_name, pq.mode, pq.status, pq.scheduled_at, pj.topic
        FROM publish_queue pq
        LEFT JOIN social_channels sc ON sc.id = pq.channel_id
        LEFT JOIN production_jobs pj ON pj.id = pq.job_id
        WHERE pq.owner_id=? AND pq.status IN ('queued','scheduled','publishing','blocked')
        ORDER BY pq.updated_at DESC, pq.id DESC
        LIMIT 8""",
        (str(owner_id),)
    )
    open_queue = c.fetchall()
    conn.close()
    return since, job_status_counts, job_stage_counts, queue_status_counts, performance_counts, recent_jobs, open_queue

def operator_status_data(owner_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT COUNT(*) FROM social_channels WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_channels = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM affiliate_links WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_affiliates = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM campaigns WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_campaigns = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM production_jobs WHERE owner_id=? AND status IN ('queued','working','waiting','blocked','ready')", (str(owner_id),))
    open_jobs = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM production_tasks WHERE owner_id=? AND status IN ('queued','waiting','working','blocked')", (str(owner_id),))
    open_tasks = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM publish_queue WHERE owner_id=? AND status IN ('queued','scheduled','publishing','blocked')", (str(owner_id),))
    open_publish = c.fetchone()[0]
    c.execute(
        """SELECT id, platform, channel_name, account_label, status, publish_mode, token_env, page_id
        FROM social_channels WHERE owner_id=? AND status='active' ORDER BY id DESC LIMIT 20""",
        (str(owner_id),)
    )
    channel_rows = c.fetchall()
    c.execute(
        """SELECT pj.id, pj.stage, pj.status, pj.platform, pj.topic, sc.channel_name, al.product_name, pj.updated_at
        FROM production_jobs pj
        LEFT JOIN social_channels sc ON sc.id=pj.channel_id
        LEFT JOIN affiliate_links al ON al.id=pj.affiliate_id
        WHERE pj.owner_id=? AND pj.status='blocked'
        ORDER BY pj.updated_at DESC LIMIT 8""",
        (str(owner_id),)
    )
    blocked_jobs = c.fetchall()
    conn.close()
    channel_readiness = []
    for row in channel_rows:
        readiness, reason = channel_publish_readiness(row)
        channel_readiness.append((row, readiness, reason))
    checks = [
        ("channels", active_channels > 0, f"{active_channels} kênh active", "/operator_bootstrap hoặc /channel_add platform=tiktok name=..."),
        ("affiliates", active_affiliates > 0, f"{active_affiliates} affiliate active", "/operator_bootstrap hoặc /affiliate_seed"),
        ("campaigns", active_campaigns > 0, f"{active_campaigns} campaign active", "/operator_bootstrap hoặc /campaign_new name=... niche=..."),
        ("operator_api", bool(OPERATOR_API_TOKEN), "OPERATOR_API_TOKEN đã bật" if OPERATOR_API_TOKEN else "OPERATOR_API_TOKEN chưa set", "/operator_api"),
        ("publish_ready", any(r in {"manual_ready", "api_ready"} for _, r, _ in channel_readiness), "Có kênh sẵn sàng đăng" if channel_readiness else "Chưa có kênh", "/publish_readiness"),
    ]
    ready_to_scale = all(ok for key, ok, _, _ in checks[:3])
    return {
        "counts": {
            "active_channels": active_channels,
            "active_affiliates": active_affiliates,
            "active_campaigns": active_campaigns,
            "open_jobs": open_jobs,
            "open_tasks": open_tasks,
            "open_publish": open_publish,
        },
        "checks": checks,
        "ready_to_scale": ready_to_scale,
        "channel_readiness": channel_readiness,
        "blocked_jobs": blocked_jobs,
    }

def publisher_status_data(owner_id):
    channel_rows = list_social_publish_readiness(owner_id)
    channels = []
    counts = {
        "manual_ready": 0,
        "api_ready": 0,
        "manual_required": 0,
        "missing_token_env": 0,
        "missing_secret": 0,
        "missing_page_id": 0,
        "blocked": 0,
    }
    for row in channel_rows:
        cid, platform, channel_name, account_label, status, publish_mode, token_env, page_id = row
        readiness, reason = channel_publish_readiness(row)
        counts[readiness] = counts.get(readiness, 0) + 1
        channels.append({
            "id": cid,
            "platform": platform,
            "channel_name": channel_name,
            "account_label": account_label,
            "status": status,
            "publish_mode": publish_mode or "manual",
            "token_env": token_env,
            "page_id": page_id,
            "readiness": readiness,
            "reason": reason,
            "can_manual_publish": readiness in {"manual_ready", "api_ready", "manual_required"},
            "can_api_publish": readiness == "api_ready",
        })

    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT pq.status, COALESCE(pq.platform,''), COALESCE(pq.mode,''), COUNT(*)
        FROM publish_queue pq
        WHERE pq.owner_id=?
        GROUP BY pq.status, pq.platform, pq.mode
        ORDER BY pq.status, pq.platform, pq.mode""",
        (str(owner_id),)
    )
    queue_counts = [
        {"status": status, "platform": platform, "mode": mode, "count": count}
        for status, platform, mode, count in c.fetchall()
    ]
    c.execute(
        """SELECT pq.id, pq.job_id, pq.platform, pq.mode, pq.status, pq.scheduled_at,
                  sc.channel_name, sc.account_label, pj.topic, pj.asset_url
        FROM publish_queue pq
        LEFT JOIN social_channels sc ON sc.id=pq.channel_id
        LEFT JOIN production_jobs pj ON pj.id=pq.job_id
        WHERE pq.owner_id=? AND pq.status IN ('queued','scheduled','publishing','blocked')
        ORDER BY
            CASE pq.status WHEN 'queued' THEN 0 WHEN 'scheduled' THEN 1 WHEN 'publishing' THEN 2 WHEN 'blocked' THEN 3 ELSE 4 END,
            pq.id ASC
        LIMIT 20""",
        (str(owner_id),)
    )
    open_queue = [
        {
            "queue_id": qid,
            "job_id": job_id,
            "platform": platform,
            "mode": mode,
            "status": status,
            "scheduled_at": scheduled_at,
            "channel_name": channel_name,
            "account_label": account_label,
            "topic": topic,
            "has_asset": bool(asset_url),
            "handoff_url": f"/api/operator/publish/{qid}/handoff",
            "complete_url": f"/api/operator/publish/{qid}/complete",
        }
        for qid, job_id, platform, mode, status, scheduled_at, channel_name, account_label, topic, asset_url in c.fetchall()
    ]
    conn.close()

    blockers = []
    if not channel_rows:
        blockers.append({"key": "no_channels", "detail": "Chưa có kênh đăng.", "next": "/operator_bootstrap hoặc /channel_add platform=tiktok name=... mode=manual"})
    for channel in channels:
        if channel["readiness"] in {"missing_token_env", "missing_secret", "missing_page_id", "blocked"}:
            blockers.append({
                "key": f"channel_{channel['id']}",
                "detail": f"{channel['platform']} / {channel['channel_name']}: {channel['reason']}",
                "next": f"/channel_publish_set id={channel['id']} mode=manual hoặc mode=api token_env=...",
            })
    can_publish_any = any(ch["can_manual_publish"] for ch in channels)
    can_api_publish = any(ch["can_api_publish"] for ch in channels)
    queued_count = sum(row["count"] for row in queue_counts if row["status"] in {"queued", "scheduled"})
    return {
        "ready": can_publish_any,
        "api_ready": can_api_publish,
        "counts": counts,
        "queue_counts": queue_counts,
        "open_queue": open_queue,
        "channels": channels,
        "blockers": blockers,
        "next": {
            "telegram_queue": "/publish_queue",
            "telegram_handoff": "/publisher_handoff queue=<QUEUE_ID>",
            "api_next": "/api/operator/publish/next",
            "api_handoff": "/api/operator/publish/<QUEUE_ID>/handoff",
            "api_complete": "/api/operator/publish/<QUEUE_ID>/complete",
        },
        "rule": "Manual-ready được phép đăng thủ công. API-ready mới cho publisher worker tự đăng qua API chính thức; OnlyFans giữ manual trừ khi có công cụ được phép theo ToS.",
        "queued_count": queued_count,
    }

def operator_audit_data(owner_id):
    status = operator_status_data(owner_id)
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT COUNT(*) FROM affiliate_links WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_affiliates = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM social_channels WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_channels = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM campaigns WHERE owner_id=? AND status='active'", (str(owner_id),))
    active_campaigns = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM production_jobs WHERE owner_id=?", (str(owner_id),))
    total_jobs = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM production_tasks WHERE owner_id=?", (str(owner_id),))
    total_tasks = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM publish_queue WHERE owner_id=?", (str(owner_id),))
    total_publish_queue = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM performance_events WHERE owner_id=?", (str(owner_id),))
    total_performance = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM trend_candidates WHERE owner_id=?", (str(owner_id),))
    total_trends = c.fetchone()[0]
    conn.close()

    channel_rows = list_social_publish_readiness(owner_id)
    manual_ready = 0
    api_ready = 0
    channel_issues = []
    for row in channel_rows:
        readiness, reason = channel_publish_readiness(row)
        if readiness == "manual_ready":
            manual_ready += 1
        elif readiness == "api_ready":
            api_ready += 1
        elif readiness != "manual_required":
            channel_issues.append({"channel_id": row[0], "platform": row[1], "readiness": readiness, "reason": reason})

    api_ok = bool(OPERATOR_API_TOKEN and PUBLIC_BASE_URL)
    ai_ok = bool(gemini_client or openai_client)
    payos_ok = bool(PAYOS_CLIENT_ID and PAYOS_API_KEY and PAYOS_CHECKSUM_KEY)
    content_ok = active_affiliates > 0 and active_channels > 0 and active_campaigns > 0
    production_ok = total_jobs > 0 or total_tasks > 0
    publish_ok = manual_ready > 0 or api_ready > 0
    tracking_ok = total_performance > 0

    checks = [
        ("telegram_brain", True, "Telegram bot có /brain, /operator_director, /operator_execute.", "/brain đầu não nên làm gì tiếp theo"),
        ("operator_api", api_ok, "OPERATOR_API_TOKEN và PUBLIC_BASE_URL đã sẵn sàng." if api_ok else "Thiếu OPERATOR_API_TOKEN hoặc PUBLIC_BASE_URL cho n8n/Claude.", "/operator_api"),
        ("ai_provider", ai_ok, "Có Gemini/OpenAI để tạo brief/prompt." if ai_ok else "Thiếu GEMINI_API_KEY hoặc OPENAI_API_KEY; bot dùng fallback template.", "Set GEMINI_API_KEY hoặc OPENAI_API_KEY trên Railway"),
        ("payos", payos_ok, "PayOS env đủ 3 khóa." if payos_ok else "Thiếu PAYOS_CLIENT_ID/PAYOS_API_KEY/PAYOS_CHECKSUM_KEY.", "Kiểm tra biến PayOS trên Railway"),
        ("affiliate_catalog", active_affiliates > 0, f"{active_affiliates} affiliate active.", "/operator_bootstrap hoặc /affiliate_seed"),
        ("channels", active_channels > 0, f"{active_channels} kênh active.", "/operator_bootstrap hoặc /channel_add platform=tiktok name=... mode=manual"),
        ("campaigns", active_campaigns > 0, f"{active_campaigns} campaign active.", "/operator_bootstrap hoặc /campaign_new name=... niche=... platforms=tiktok"),
        ("publish_readiness", publish_ok, f"manual_ready={manual_ready}, api_ready={api_ready}.", "/publish_readiness"),
        ("production_pipeline", production_ok, f"jobs={total_jobs}, tasks={total_tasks}.", "/operator_execute"),
        ("performance_tracking", tracking_ok, f"performance_events={total_performance}.", "/performance_add job=<ID> type=view value=..."),
    ]
    ready_count = sum(1 for _, ok, _, _ in checks if ok)
    score = int(ready_count / len(checks) * 100)
    blockers = [{"key": key, "detail": detail, "next": next_cmd} for key, ok, detail, next_cmd in checks if not ok]
    if score >= 85 and api_ok and content_ok and publish_ok:
        level = "READY_FOR_OPERATOR"
    elif score >= 60 and content_ok:
        level = "PARTIAL_READY"
    else:
        level = "SETUP_REQUIRED"
    return {
        "level": level,
        "score": score,
        "checks": checks,
        "blockers": blockers,
        "channel_issues": channel_issues,
        "counts": {
            **status["counts"],
            "total_jobs": total_jobs,
            "total_tasks": total_tasks,
            "total_publish_queue": total_publish_queue,
            "total_performance": total_performance,
            "total_trends": total_trends,
            "manual_ready_channels": manual_ready,
            "api_ready_channels": api_ready,
        },
        "next_command": blockers[0]["next"] if blockers else "/operator_director",
    }

