def performance_report_data(owner_id, limit=10):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT event_type, COALESCE(SUM(value),0), COALESCE(SUM(amount),0), COUNT(*)
        FROM performance_events WHERE owner_id=? GROUP BY event_type ORDER BY event_type""",
        (str(owner_id),)
    )
    event_totals = c.fetchall()
    c.execute(
        """SELECT pe.platform, sc.channel_name, COALESCE(SUM(pe.value),0), COALESCE(SUM(pe.amount),0), COUNT(*)
        FROM performance_events pe
        LEFT JOIN social_channels sc ON sc.id = pe.channel_id
        WHERE pe.owner_id=?
        GROUP BY pe.platform, sc.channel_name
        ORDER BY COALESCE(SUM(pe.amount),0) DESC, COALESCE(SUM(pe.value),0) DESC
        LIMIT ?""",
        (str(owner_id), limit)
    )
    channel_totals = c.fetchall()
    c.execute(
        """SELECT pe.job_id, pe.event_type, pe.value, pe.amount, pe.platform, pj.topic, pe.note, pe.created_at
        FROM performance_events pe
        LEFT JOIN production_jobs pj ON pj.id = pe.job_id
        WHERE pe.owner_id=?
        ORDER BY pe.id DESC
        LIMIT ?""",
        (str(owner_id), limit)
    )
    recent_events = c.fetchall()
    conn.close()
    return event_totals, channel_totals, recent_events

def affiliate_performance_report_data(owner_id, days=30, limit=15):
    since = (datetime.now() - timedelta(days=max(1, int(days)))).strftime("%Y-%m-%d %H:%M:%S")
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT al.id, al.network, al.product_name, al.niche, al.url, al.product_score,
                  COUNT(DISTINCT pj.id) AS jobs,
                  SUM(CASE WHEN pe.event_type='publish' THEN pe.value ELSE 0 END) AS publishes,
                  SUM(CASE WHEN pe.event_type='view' THEN pe.value ELSE 0 END) AS views,
                  SUM(CASE WHEN pe.event_type='click' THEN pe.value ELSE 0 END) AS clicks,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.value ELSE 0 END) AS conversions,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.amount ELSE 0 END) AS revenue,
                  SUM(CASE WHEN pe.event_type='cost' THEN pe.amount ELSE 0 END) AS cost,
                  COUNT(pe.id) AS events
        FROM affiliate_links al
        LEFT JOIN production_jobs pj ON pj.affiliate_id=al.id AND pj.owner_id=al.owner_id
        LEFT JOIN performance_events pe ON pe.affiliate_id=al.id AND pe.owner_id=al.owner_id AND pe.created_at>=?
        WHERE al.owner_id=? AND COALESCE(al.status,'active')='active'
        GROUP BY al.id, al.network, al.product_name, al.niche, al.url, al.product_score
        ORDER BY revenue DESC, clicks DESC, views DESC, jobs DESC, al.product_score DESC
        LIMIT ?""",
        (since, str(owner_id), limit)
    )
    affiliate_rows = c.fetchall()
    c.execute(
        """SELECT al.id, al.network, al.product_name, pj.id, pj.platform, pj.topic, pj.status, pj.publish_url,
                  SUM(CASE WHEN pe.event_type='view' THEN pe.value ELSE 0 END) AS views,
                  SUM(CASE WHEN pe.event_type='click' THEN pe.value ELSE 0 END) AS clicks,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.amount ELSE 0 END) AS revenue,
                  MAX(COALESCE(pe.created_at, pj.updated_at, pj.created_at)) AS last_seen
        FROM production_jobs pj
        LEFT JOIN affiliate_links al ON al.id=pj.affiliate_id
        LEFT JOIN performance_events pe ON pe.job_id=pj.id AND pe.owner_id=pj.owner_id AND pe.created_at>=?
        WHERE pj.owner_id=? AND COALESCE(pj.affiliate_id,0)>0
        GROUP BY al.id, al.network, al.product_name, pj.id, pj.platform, pj.topic, pj.status, pj.publish_url
        ORDER BY revenue DESC, clicks DESC, views DESC, last_seen DESC
        LIMIT ?""",
        (since, str(owner_id), limit)
    )
    job_rows = c.fetchall()
    conn.close()
    return since, affiliate_rows, job_rows

def growth_optimizer_data(owner_id, days=14, limit=8):
    since = (datetime.now() - timedelta(days=max(1, int(days)))).strftime("%Y-%m-%d %H:%M:%S")
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT pe.job_id, pj.topic, pe.platform, sc.channel_name, al.product_name,
                  SUM(CASE WHEN pe.event_type='view' THEN pe.value ELSE 0 END) AS views,
                  SUM(CASE WHEN pe.event_type='click' THEN pe.value ELSE 0 END) AS clicks,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.value ELSE 0 END) AS conversions,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.amount ELSE 0 END) AS revenue,
                  SUM(CASE WHEN pe.event_type='cost' THEN pe.amount ELSE 0 END) AS cost,
                  COUNT(*) AS events
        FROM performance_events pe
        LEFT JOIN production_jobs pj ON pj.id = pe.job_id
        LEFT JOIN social_channels sc ON sc.id = pe.channel_id
        LEFT JOIN affiliate_links al ON al.id = pe.affiliate_id
        WHERE pe.owner_id=? AND pe.created_at>=?
        GROUP BY pe.job_id, pj.topic, pe.platform, sc.channel_name, al.product_name
        ORDER BY revenue DESC, clicks DESC, views DESC
        LIMIT ?""",
        (str(owner_id), since, limit)
    )
    job_rows = c.fetchall()
    c.execute(
        """SELECT pe.platform, sc.channel_name,
                  SUM(CASE WHEN pe.event_type='view' THEN pe.value ELSE 0 END) AS views,
                  SUM(CASE WHEN pe.event_type='click' THEN pe.value ELSE 0 END) AS clicks,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.value ELSE 0 END) AS conversions,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.amount ELSE 0 END) AS revenue,
                  COUNT(*) AS events
        FROM performance_events pe
        LEFT JOIN social_channels sc ON sc.id = pe.channel_id
        WHERE pe.owner_id=? AND pe.created_at>=?
        GROUP BY pe.platform, sc.channel_name
        ORDER BY revenue DESC, clicks DESC, views DESC
        LIMIT ?""",
        (str(owner_id), since, limit)
    )
    channel_rows = c.fetchall()
    c.execute(
        """SELECT pe.variant_id, cv.variant_label, cv.hook,
                  SUM(CASE WHEN pe.event_type='view' THEN pe.value ELSE 0 END) AS views,
                  SUM(CASE WHEN pe.event_type='click' THEN pe.value ELSE 0 END) AS clicks,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.value ELSE 0 END) AS conversions,
                  SUM(CASE WHEN pe.event_type IN ('order','lead','revenue') THEN pe.amount ELSE 0 END) AS revenue
        FROM performance_events pe
        LEFT JOIN creative_variants cv ON cv.id = pe.variant_id
        WHERE pe.owner_id=? AND pe.created_at>=? AND COALESCE(pe.variant_id,0)>0
        GROUP BY pe.variant_id, cv.variant_label, cv.hook
        ORDER BY revenue DESC, clicks DESC, views DESC
        LIMIT ?""",
        (str(owner_id), since, limit)
    )
    variant_rows = c.fetchall()
    conn.close()
    return since, job_rows, channel_rows, variant_rows

def growth_score(views=0, clicks=0, conversions=0, revenue=0, cost=0):
    views = int(views or 0)
    clicks = int(clicks or 0)
    conversions = int(conversions or 0)
    revenue = int(revenue or 0)
    cost = int(cost or 0)
    ctr = (clicks / views * 100) if views else 0
    cvr = (conversions / clicks * 100) if clicks else 0
    roi = ((revenue - cost) / cost * 100) if cost else (100 if revenue > 0 else 0)
    score = min(100, int((ctr * 3) + (cvr * 5) + min(revenue / 10000, 40) + max(min(roi / 10, 20), 0)))
    return score, ctr, cvr, roi

def normalize_tracking_source(source, fallback="manual"):
    value = re.sub(r"[^a-zA-Z0-9_.:-]+", "_", str(source or fallback or "manual").strip().lower())
    value = re.sub(r"_+", "_", value).strip("_")
    return (value or fallback or "manual")[:80]

def format_tracking_note(source="", note=""):
    source = normalize_tracking_source(source, "manual")
    note = str(note or "").strip()
    return f"src:{source}" + (f"|{note}" if note else "")

def extract_job_id_from_tracking_source(source):
    match = re.search(r"(?:^|[_:-])job[_:-]?(\d+)(?:$|[_:-])", str(source or ""), re.IGNORECASE)
    return int(match.group(1)) if match else 0

def performance_source_from_note(note):
    note = str(note or "").strip()
    if not note:
        return "unknown"
    match = re.search(r"(?:^|\|\s*)src:([^|]+)", note, re.IGNORECASE)
    if match:
        return match.group(1).strip()[:80] or "unknown"
    first = note.split("|", 1)[0].strip()
    if ":" in first:
        key, value = first.split(":", 1)
        key = key.strip().lower()
        value = value.strip()
        if key in {"api", "affiliate_postback", "redirect_affiliate", "tiktok_affiliate", "manual", "n8n"}:
            return key if key != "api" or not value else value[:80]
    return first[:80] or "unknown"

def tracking_report_data(owner_id, days=30, limit=15):
    since = (datetime.now() - timedelta(days=max(1, int(days or 30)))).strftime("%Y-%m-%d %H:%M:%S")
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT pe.affiliate_id, al.network, al.product_name, al.url,
                  pe.job_id, pj.topic, pe.platform, pe.event_type,
                  COALESCE(pe.value,0), COALESCE(pe.amount,0), COALESCE(pe.note,''), pe.created_at
        FROM performance_events pe
        LEFT JOIN affiliate_links al ON al.id=pe.affiliate_id
        LEFT JOIN production_jobs pj ON pj.id=pe.job_id
        WHERE pe.owner_id=? AND pe.created_at>=?
        ORDER BY pe.id DESC""",
        (str(owner_id), since)
    )
    rows = c.fetchall()
    conn.close()

    by_affiliate = {}
    by_source = {}
    by_job = {}

    def blank():
        return {"views": 0, "clicks": 0, "conversions": 0, "revenue": 0, "cost": 0, "events": 0}

    for aid, network, product, url, job_id, topic, platform, event_type, value, amount, note, created_at in rows:
        value = int(value or 0)
        amount = int(amount or 0)
        event_type = (event_type or "").lower()
        source = performance_source_from_note(note)
        aff_key = int(aid or 0)
        if aff_key not in by_affiliate:
            by_affiliate[aff_key] = {
                **blank(),
                "affiliate_id": aff_key,
                "network": network or "",
                "product": product or "",
                "url": url or "",
                "sources": set(),
            }
        source_key = (aff_key, source)
        if source_key not in by_source:
            by_source[source_key] = {
                **blank(),
                "affiliate_id": aff_key,
                "network": network or "",
                "product": product or "",
                "source": source,
            }
        job_key = int(job_id or 0)
        if job_key not in by_job:
            by_job[job_key] = {
                **blank(),
                "job_id": job_key,
                "affiliate_id": aff_key,
                "product": product or "",
                "topic": topic or "",
                "platform": platform or "",
            }
        for bucket in (by_affiliate[aff_key], by_source[source_key], by_job[job_key]):
            bucket["events"] += 1
            if event_type == "view":
                bucket["views"] += value
            elif event_type == "click":
                bucket["clicks"] += value
            elif event_type in {"order", "lead", "revenue"}:
                bucket["conversions"] += value
                bucket["revenue"] += amount
            elif event_type == "cost":
                bucket["cost"] += amount
        by_affiliate[aff_key]["sources"].add(source)

    def finalize(items):
        output = []
        for item in items:
            views = item["views"]
            clicks = item["clicks"]
            conversions = item["conversions"]
            revenue = item["revenue"]
            cost = item["cost"]
            score, ctr, cvr, roi = growth_score(views, clicks, conversions, revenue, cost)
            row = {**item, "score": score, "ctr": round(ctr, 2), "cvr": round(cvr, 2), "roi": round(roi, 1)}
            if isinstance(row.get("sources"), set):
                row["sources"] = sorted(row["sources"])
            output.append(row)
        output.sort(key=lambda x: (x["revenue"], x["conversions"], x["clicks"], x["views"], x["score"]), reverse=True)
        return output[:limit]

    return {
        "since": since,
        "days": days,
        "affiliates": finalize(by_affiliate.values()),
        "sources": finalize(by_source.values()),
        "jobs": finalize(by_job.values()),
    }

def scale_plan_action(item, min_clicks=20, min_views=200):
    views = int(item.get("views") or 0)
    clicks = int(item.get("clicks") or 0)
    conversions = int(item.get("conversions") or 0)
    revenue = int(item.get("revenue") or 0)
    cost = int(item.get("cost") or 0)
    score = int(item.get("score") or 0)
    if cost > 0 and revenue < cost and (views >= min_views or clicks >= min_clicks):
        return "PAUSE_CHECK", "Có chi phí nhưng doanh thu chưa bù chi phí; tạm dừng scale và kiểm tra offer/targeting."
    if revenue > 0 or conversions > 0 or score >= 45:
        return "SCALE", "Đã có tín hiệu doanh thu/chuyển đổi hoặc score đủ mạnh để tạo thêm biến thể."
    if views >= min_views and clicks == 0:
        return "FIX_CTA", "Có view nhưng chưa có click; cần sửa hook, caption, CTA hoặc vị trí link."
    if clicks >= min_clicks and conversions == 0:
        return "FIX_OFFER", "Có click nhưng chưa có đơn/lead; cần đổi offer, landing, sản phẩm liên quan hoặc góc nội dung."
    return "TEST_MORE", "Dữ liệu còn mỏng; tiếp tục test thêm creative/source trước khi scale."

def scale_plan_command(item, action, platform="tiktok"):
    aid = int(item.get("affiliate_id") or 0)
    job_id = int(item.get("job_id") or 0)
    platform = (item.get("platform") or platform or "tiktok").lower()
    if action == "SCALE" and aid:
        return f"/affiliate_scale aff={aid} platform={platform} channel=all limit=3 build=1 duration=45"
    if action == "FIX_CTA" and job_id:
        return f"/creative_test job={job_id} n=5"
    if action == "FIX_OFFER" and aid:
        return f"/affiliate_related aff={aid} limit=12"
    if action == "PAUSE_CHECK" and aid:
        return f"/tracking_report days=30 limit=20 và kiểm tra cost/revenue aff={aid}"
    if aid:
        return f"/affiliate_ideas aff={aid} platform={platform} n=5 topic=remix"
    return "/tracking_report days=30"

def scale_plan_data(owner_id, days=30, limit=10, platform="tiktok"):
    report = tracking_report_data(owner_id, days=days, limit=max(limit, 20))
    candidates = []
    for scope, rows in (("source", report["sources"]), ("job", report["jobs"]), ("affiliate", report["affiliates"])):
        for item in rows:
            if not item.get("affiliate_id") and not item.get("job_id"):
                continue
            action, reason = scale_plan_action(item)
            command = scale_plan_command(item, action, platform=platform)
            candidates.append({
                "scope": scope,
                "action": action,
                "reason": reason,
                "command": command,
                "affiliate_id": int(item.get("affiliate_id") or 0),
                "job_id": int(item.get("job_id") or 0),
                "source": item.get("source", ""),
                "product": item.get("product", ""),
                "topic": item.get("topic", ""),
                "platform": item.get("platform", platform),
                "score": int(item.get("score") or 0),
                "views": int(item.get("views") or 0),
                "clicks": int(item.get("clicks") or 0),
                "conversions": int(item.get("conversions") or 0),
                "revenue": int(item.get("revenue") or 0),
                "cost": int(item.get("cost") or 0),
                "ctr": item.get("ctr", 0),
                "cvr": item.get("cvr", 0),
                "roi": item.get("roi", 0),
            })
    action_rank = {"SCALE": 5, "FIX_OFFER": 4, "FIX_CTA": 3, "TEST_MORE": 2, "PAUSE_CHECK": 1}
    candidates.sort(
        key=lambda x: (
            action_rank.get(x["action"], 0),
            x["revenue"],
            x["conversions"],
            x["clicks"],
            x["score"],
        ),
        reverse=True,
    )
    return {
        "since": report["since"],
        "days": days,
        "platform": platform,
        "plans": candidates[:limit],
        "summary": {
            "scale": sum(1 for item in candidates if item["action"] == "SCALE"),
            "fix": sum(1 for item in candidates if item["action"] in {"FIX_CTA", "FIX_OFFER"}),
            "test": sum(1 for item in candidates if item["action"] == "TEST_MORE"),
            "pause": sum(1 for item in candidates if item["action"] == "PAUSE_CHECK"),
        },
    }

def payment_money_summary_data(owner_id, days=30):
    since = (datetime.now() - timedelta(days=max(1, int(days or 30)))).strftime("%Y-%m-%d %H:%M:%S")
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM payos_orders WHERE status=?", (PAYOS_STATUS_PAID,))
    payos_paid_count, payos_paid_amount = c.fetchone()
    c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM payos_orders WHERE status=? AND created_at>=?", (PAYOS_STATUS_PAID, since))
    payos_period_count, payos_period_amount = c.fetchone()
    c.execute("SELECT status, COUNT(*), COALESCE(SUM(amount),0) FROM payos_orders WHERE created_at>=? GROUP BY status", (since,))
    payos_by_status = [
        {"status": status, "count": int(count or 0), "amount": int(amount or 0)}
        for status, count, amount in c.fetchall()
    ]
    c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM pending_deposits WHERE status='pending'")
    pending_manual_count, pending_manual_amount = c.fetchone()
    c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM pending_deposits WHERE status='approved' AND submitted_at>=?", (since,))
    approved_manual_count, approved_manual_amount = c.fetchone()
    c.execute("SELECT COUNT(*), COALESCE(SUM(delta),0) FROM credit_events WHERE created_at>=? AND delta>0", (since,))
    credit_in_count, credit_in_sum = c.fetchone()
    c.execute("SELECT COUNT(*), COALESCE(SUM(cost),0) FROM transactions WHERE created_at>=?", (since,))
    service_tx_count, service_xu_spent = c.fetchone()
    c.execute("SELECT order_code, user_id, amount, xu, status, created_at FROM payos_orders ORDER BY created_at DESC LIMIT 8")
    recent_payos = c.fetchall()
    conn.close()
    return {
        "since": since,
        "payment_in": {
            "payos_total": {"count": int(payos_paid_count or 0), "amount": int(payos_paid_amount or 0)},
            "payos_period": {"count": int(payos_period_count or 0), "amount": int(payos_period_amount or 0)},
            "payos_by_status": payos_by_status,
            "manual_pending": {"count": int(pending_manual_count or 0), "amount": int(pending_manual_amount or 0)},
            "manual_approved_period": {"count": int(approved_manual_count or 0), "amount": int(approved_manual_amount or 0)},
            "credit_in_period": {"events": int(credit_in_count or 0), "xu": int(credit_in_sum or 0)},
            "service_xu_spent_period": {"transactions": int(service_tx_count or 0), "xu": int(service_xu_spent or 0)},
        },
        "bank_fallback": {
            "bank_name": MANUAL_BANK_NAME,
            "bank_code": MANUAL_BANK_CODE,
            "account": MANUAL_BANK_ACCOUNT,
            "owner": MANUAL_BANK_OWNER,
            "telegram": "/thucong 10k hoặc /pending rồi /duyet <user_id> <xu>",
        },
        "payos_config": {
            "configured": bool(PAYOS_CLIENT_ID and PAYOS_API_KEY and PAYOS_CHECKSUM_KEY),
            "client_id": bool(PAYOS_CLIENT_ID),
            "api_key": bool(PAYOS_API_KEY),
            "checksum_key": bool(PAYOS_CHECKSUM_KEY),
            "check_command": "/checkpayos <ORDER_CODE>",
        },
        "recent_payos": [
            {
                "order_code": order_code,
                "user_id": user_id,
                "amount": int(amount or 0),
                "xu": int(xu or 0),
                "status": status,
                "created_at": created_at,
            }
            for order_code, user_id, amount, xu, status, created_at in recent_payos
        ],
    }

def operator_money_pack_data(owner_id, days=30, platform="tiktok", limit=10):
    days = max(1, min(int(days or 30), 180))
    limit = max(3, min(int(limit or 10), 50))
    platform = (platform or "tiktok").lower()
    payment = payment_money_summary_data(owner_id, days=days)
    event_totals, channel_totals, recent_events = performance_report_data(owner_id, limit=limit)
    since, affiliate_rows, job_rows = affiliate_performance_report_data(owner_id, days=days, limit=limit)
    tracking = tracking_report_data(owner_id, days=days, limit=limit)
    scale = scale_plan_data(owner_id, days=days, limit=limit, platform=platform)
    decisions_since, decisions, _decision_jobs = affiliate_decision_data(owner_id, days=days, limit=limit, platform=platform)
    affiliate_revenue = sum(int(row[11] or 0) for row in affiliate_rows)
    affiliate_cost = sum(int(row[12] or 0) for row in affiliate_rows)
    affiliate_clicks = sum(int(row[9] or 0) for row in affiliate_rows)
    affiliate_views = sum(int(row[8] or 0) for row in affiliate_rows)
    affiliate_conversions = sum(int(row[10] or 0) for row in affiliate_rows)
    payos_amount = int((payment.get("payment_in") or {}).get("payos_period", {}).get("amount") or 0)
    manual_amount = int((payment.get("payment_in") or {}).get("manual_approved_period", {}).get("amount") or 0)
    top_affiliates = []
    for (
        aid, network, product, niche, url, product_score, jobs, publishes, views,
        clicks, conversions, revenue, cost, events
    ) in affiliate_rows[:limit]:
        score, ctr, cvr, roi = growth_score(views, clicks, conversions, revenue, cost)
        top_affiliates.append({
            "id": aid,
            "network": network,
            "product": product,
            "niche": niche,
            "url": url,
            "score": score,
            "views": int(views or 0),
            "clicks": int(clicks or 0),
            "conversions": int(conversions or 0),
            "revenue": int(revenue or 0),
            "cost": int(cost or 0),
            "ctr": round(ctr, 2),
            "cvr": round(cvr, 2),
            "roi": round(roi, 1),
            "next": f"/affiliate_scale aff={aid} platform={platform} channel=all limit=3 build=1 duration=45",
        })
    return {
        "ok": True,
        "generated_at": now_text(),
        "days": days,
        "since": since,
        "platform": platform,
        "summary": {
            "affiliate_revenue": affiliate_revenue,
            "affiliate_cost": affiliate_cost,
            "affiliate_profit_estimate": affiliate_revenue - affiliate_cost,
            "affiliate_views": affiliate_views,
            "affiliate_clicks": affiliate_clicks,
            "affiliate_conversions": affiliate_conversions,
            "bot_payment_revenue": payos_amount + manual_amount,
            "payos_period_amount": payos_amount,
            "manual_approved_amount": manual_amount,
        },
        "payment": payment,
        "performance_events": [
            {"type": event_type, "value": int(value_sum or 0), "amount": int(amount_sum or 0), "count": int(count or 0)}
            for event_type, value_sum, amount_sum, count in event_totals
        ],
        "channel_money": [
            {"platform": row_platform, "channel": channel_name, "value": int(value_sum or 0), "amount": int(amount_sum or 0), "count": int(count or 0)}
            for row_platform, channel_name, value_sum, amount_sum, count in channel_totals
        ],
        "top_affiliates": top_affiliates,
        "tracking": {
            "top_sources": tracking.get("sources", [])[:limit],
            "top_jobs": tracking.get("jobs", [])[:limit],
        },
        "scale": scale,
        "affiliate_decisions": decisions[:limit],
        "recent_events": [
            {
                "job_id": job_id,
                "event_type": event_type,
                "value": int(value or 0),
                "amount": int(amount or 0),
                "platform": row_platform,
                "topic": topic,
                "source": performance_source_from_note(note),
                "created_at": created_at,
            }
            for job_id, event_type, value, amount, row_platform, topic, note, created_at in recent_events[:limit]
        ],
        "commands": {
            "telegram": {
                "money_pack": f"/money_pack days={days} platform={platform}",
                "tracking_report": f"/tracking_report days={days} limit={limit}",
                "affiliate_report": f"/affiliate_report days={days} limit={limit}",
                "scale_plan": f"/scale_plan days={days} platform={platform} limit={limit}",
                "scale_execute": f"/scale_execute days={days} platform={platform} limit=3 per=3 build=1",
                "pending_manual": "/pending",
                "payos_check": "/checkpayos <ORDER_CODE>",
            },
            "api": {
                "money_pack": f"/api/operator/money-pack?days={days}&platform={platform}&limit={limit}",
                "tracking_report": f"/api/operator/tracking-report?days={days}&limit={limit}",
                "affiliate_report": f"/api/operator/affiliate-report?days={days}&limit={limit}",
                "scale_plan": f"/api/operator/scale-plan?days={days}&platform={platform}&limit={limit}",
                "performance": "/api/operator/performance",
            },
        },
        "rule": "Money pack gom doanh thu affiliate, nguồn tracking, tiền nạp PayOS/thủ công và quyết định scale. Chỉ scale khi có tín hiệu thật; tiền affiliate ngoài nền tảng cần nhập bằng performance/postback để đo đúng.",
    }

def affiliate_campaign_cockpit_data(owner_id, days=30, platform="tiktok", limit=10, affiliate_id=0):
    days = max(1, min(int(days or 30), 180))
    limit = max(3, min(int(limit or 10), 50))
    platform = (platform or "tiktok").lower()
    affiliate_id = safe_int(affiliate_id, 0)
    money = operator_money_pack_data(owner_id, days=days, platform=platform, limit=limit)
    tracking = tracking_report_data(owner_id, days=days, limit=max(limit, 20))
    scale = scale_plan_data(owner_id, days=days, limit=limit, platform=platform)
    _since, decisions, _jobs = affiliate_decision_data(owner_id, days=days, limit=limit, platform=platform)
    queue_rows = list_publish_queue(owner_id, limit=limit)
    open_queue = []
    for row in queue_rows:
        item = serialize_publish_queue_item(row)
        if not item:
            continue
        status = (item.get("status") or "").lower()
        if status in {"queued", "scheduled", "publishing", "blocked"}:
            open_queue.append(item)
    focus = get_affiliate_link(affiliate_id, owner_id) if affiliate_id else None
    focus_payload = {}
    if focus:
        (
            aid, network, product_name, niche, url, commission_note, status,
            price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
        ) = focus
        related = list_related_affiliate_links(owner_id, affiliate_id=aid, niche=niche or product_name, limit=8)
        focus_payload = {
            "id": aid,
            "network": network,
            "product_name": product_name,
            "niche": niche,
            "url": url,
            "status": status,
            "tracking_urls": {
                "caption": affiliate_tracking_url(aid, 0, f"{platform}_caption"),
                "comment": affiliate_tracking_url(aid, 0, f"{platform}_comment"),
                "status": affiliate_tracking_url(aid, 0, f"{platform}_status"),
            },
            "related_links": [
                {
                    "id": row[0],
                    "network": row[1],
                    "product_name": row[2],
                    "niche": row[3],
                    "url": row[4],
                    "score": score,
                    "reasons": reasons,
                }
                for score, reasons, row in related[:8]
            ],
        }
    winners = []
    for item in (tracking.get("affiliates") or [])[:limit]:
        if affiliate_id and int(item.get("affiliate_id") or 0) != affiliate_id:
            continue
        action, reason = scale_plan_action(item)
        winners.append({
            **item,
            "action": action,
            "reason": reason,
            "command": scale_plan_command(item, action, platform=platform),
        })
    if not winners:
        for item in (money.get("top_affiliates") or [])[:limit]:
            if affiliate_id and int(item.get("id") or 0) != affiliate_id:
                continue
            winners.append({
                "affiliate_id": item.get("id"),
                "product": item.get("product"),
                "network": item.get("network"),
                "views": item.get("views", 0),
                "clicks": item.get("clicks", 0),
                "conversions": item.get("conversions", 0),
                "revenue": item.get("revenue", 0),
                "cost": item.get("cost", 0),
                "score": item.get("score", 0),
                "action": "TEST_MORE",
                "reason": "Chưa đủ performance source chi tiết; dùng top_affiliates để tiếp tục tạo biến thể.",
                "command": item.get("next"),
            })
    content_actions = []
    for item in winners[:limit]:
        aid = int(item.get("affiliate_id") or item.get("id") or 0)
        product = item.get("product") or item.get("product_name") or "affiliate"
        content_actions.append({
            "affiliate_id": aid,
            "product": product,
            "action": item.get("action") or "TEST_MORE",
            "commands": {
                "match": f"/affiliate_match niche={product} platform={platform}",
                "ideas": f"/affiliate_ideas aff={aid} platform={platform} n=5 topic=trend" if aid else "/affiliate_ideas aff=<AFF_ID>",
                "make_video": f"/affiliate_scale aff={aid} platform={platform} channel=all limit=3 build=1 duration=45" if aid else "/operator_launch topic=<TOPIC> build=1",
                "viral_remix": f"/viral_remix topic={product} platform={platform} aff={aid}" if aid else f"/viral_remix topic={product} platform={platform}",
                "postback": f"/postback_setup aff={aid} platform={platform}" if aid else "/postback_setup",
            },
        })
    bottlenecks = []
    summary = money.get("summary") or {}
    if not (tracking.get("affiliates") or []):
        bottlenecks.append({"key": "missing_tracking", "detail": "Chưa có view/click/order/revenue theo affiliate/source.", "next": "/performance_add job=<JOB_ID> type=view value=<VIEWS> note=src_caption"})
    if open_queue:
        bottlenecks.append({"key": "open_publish_queue", "detail": f"Còn {len(open_queue)} queue cần đăng/đánh dấu published.", "next": "/publish_queue"})
    if int(summary.get("affiliate_clicks") or 0) > 0 and int(summary.get("affiliate_conversions") or 0) == 0:
        bottlenecks.append({"key": "click_no_order", "detail": "Có click nhưng chưa có lead/order/revenue; cần đổi offer hoặc related links.", "next": "/affiliate_related aff=<AFF_ID> limit=12"})
    if int(summary.get("affiliate_views") or 0) > 0 and int(summary.get("affiliate_clicks") or 0) == 0:
        bottlenecks.append({"key": "view_no_click", "detail": "Có view nhưng chưa có click; cần sửa CTA/caption/comment.", "next": "/creative_test job=<JOB_ID> n=5"})
    if not bottlenecks:
        bottlenecks.append({"key": "ready_to_scale_or_test", "detail": "Không có blocker lớn; ưu tiên SCALE link thắng hoặc TEST thêm creative.", "next": "/scale_plan"})
    return {
        "ok": True,
        "generated_at": now_text(),
        "days": days,
        "platform": platform,
        "focus_affiliate": focus_payload,
        "summary": summary,
        "winners": winners[:limit],
        "scale_plans": (scale.get("plans") or [])[:limit],
        "affiliate_decisions": decisions[:limit],
        "open_publish_queue": open_queue[:limit],
        "top_sources": (tracking.get("sources") or [])[:limit],
        "top_jobs": (tracking.get("jobs") or [])[:limit],
        "content_actions": content_actions[:limit],
        "bottlenecks": bottlenecks,
        "tracking_checklist": [
            {"event": "published", "command": "/publish_queue_set id=<QUEUE_ID> status=published url=https://..."},
            {"event": "view", "command": "/performance_add job=<JOB_ID> type=view value=<VIEWS> note=src_<caption|comment|status|bio>"},
            {"event": "click", "command": "/performance_add job=<JOB_ID> aff=<AFF_ID> type=click value=<CLICKS> note=src_caption"},
            {"event": "lead/order/revenue", "command": "/performance_add job=<JOB_ID> aff=<AFF_ID> type=revenue value=1 amount=<VND> note=<network>_order"},
            {"event": "cost", "command": "/performance_add job=<JOB_ID> type=cost value=1 amount=<VND> note=ads_or_tool_cost"},
        ],
        "commands": {
            "telegram": {
                "cockpit": f"/affiliate_cockpit days={days} platform={platform} limit={limit}" + (f" aff={affiliate_id}" if affiliate_id else ""),
                "money_pack": f"/money_pack days={days} platform={platform} limit={limit}",
                "tracking_report": f"/tracking_report days={days} limit={limit}",
                "scale_plan": f"/scale_plan days={days} platform={platform} limit={limit}",
                "scale_execute": f"/scale_execute days={days} platform={platform} limit=3 per=3 build=1",
                "publish_queue": "/publish_queue",
            },
            "api": {
                "cockpit": f"/api/operator/affiliate-cockpit?days={days}&platform={platform}&limit={limit}" + (f"&affiliate_id={affiliate_id}" if affiliate_id else ""),
                "money_pack": f"/api/operator/money-pack?days={days}&platform={platform}&limit={limit}",
                "tracking_report": f"/api/operator/tracking-report?days={days}&limit={limit}",
                "scale_plan": f"/api/operator/scale-plan?days={days}&platform={platform}&limit={limit}",
                "performance": "/api/operator/performance",
            },
        },
        "rule": "Affiliate cockpit là bảng điều hành link/video/source: tạo content, publish, comment, ghi metric, rồi scale dựa trên dữ liệu thật.",
    }

