class AgentGemini:
    @staticmethod
    def chat(prompt: str, text: str, uid, is_json: bool = False) -> str:
        if not gemini_client and not openai_client:
            return "❌ Chưa cấu hình AI Provider."

        if gemini_client:
            if uid not in user_memory:
                user_memory[uid] = []
            user_memory[uid].append(types.Content(role="user", parts=[types.Part(text=text)]))
            if len(user_memory[uid]) > 10:
                user_memory[uid] = user_memory[uid][-10:]
            cfg = {
                "system_instruction": prompt,
                "response_mime_type": "application/json" if is_json else "text/plain"
            }
            if is_json:
                cfg["response_schema"] = AgentRouter
            try:
                res = gemini_client.models.generate_content(
                    model="gemini-2.0-flash",
                    config=types.GenerateContentConfig(**cfg),
                    contents=user_memory[uid] if not is_json else text
                )
                if not is_json:
                    user_memory[uid].append(
                        types.Content(role="model", parts=[types.Part(text=res.text)])
                    )
                return res.text
            except Exception as e:
                logger.error(f"Gemini error: {e} — Thử fallback OpenAI...")

        if openai_client:
            try:
                messages = [{"role": "system", "content": prompt}]
                if uid in user_memory:
                    for m in user_memory[uid][-6:]:
                        role = "user" if m.role == "user" else "assistant"
                        messages.append({"role": role, "content": m.parts[0].text})
                messages.append({"role": "user", "content": text})

                res = openai_client.chat.completions.create(
                    model="gpt-4o-mini",
                    messages=messages,
                    response_format={"type": "json_object"} if is_json else {"type": "text"},
                    max_tokens=1000
                )
                return res.choices[0].message.content
            except Exception as e:
                logger.error(f"OpenAI error: {e}")
                return "❌ AI đang tạm hết quota hoặc quá tải.\nBot chưa trừ Xu. Vui lòng thử lại sau."

        return "❌ AI đang tạm hết quota hoặc quá tải.\nBot chưa trừ Xu. Vui lòng thử lại sau."

class AgentDeepgram:
    REQUEST_PARAMS = {
        "model": "nova-2",
        "smart_format": "true",
        "detect_language": "true",
        "punctuate": "true",
        "filler_words": "false",
        "utterances": "false",
    }

    @staticmethod
    def _result_summary(data: dict) -> tuple[str, str]:
        try:
            metadata = data.get("metadata", {}) if isinstance(data, dict) else {}
            results = data.get("results", {}) if isinstance(data, dict) else {}
            channels = results.get("channels") or []
            duration = metadata.get("duration") or metadata.get("audio_duration") or "-"
            detected_language = "-"
            if channels:
                detected_language = str((channels[0].get("detected_language") or channels[0].get("language") or "-"))
            return str(duration), detected_language or "-"
        except Exception:
            return "-", "-"

    @staticmethod
    def _result_stats(data: dict, transcript: str = "") -> dict:
        try:
            metadata = data.get("metadata", {}) if isinstance(data, dict) else {}
            results = data.get("results", {}) if isinstance(data, dict) else {}
            channels = results.get("channels") or []
            alt = {}
            if channels:
                alternatives = channels[0].get("alternatives") or []
                alt = alternatives[0] if alternatives else {}
            words = alt.get("words") or []
            confidence = alt.get("confidence")
            return {
                "duration": metadata.get("duration") or metadata.get("audio_duration") or "-",
                "detected_language": (channels[0].get("detected_language") or channels[0].get("language") or "-") if channels else "-",
                "confidence": "-" if confidence is None else str(confidence),
                "response_keys": ",".join(list(data.keys())[:8]) if isinstance(data, dict) else "-",
                "alternatives_count": len((channels[0].get("alternatives") or [])) if channels else 0,
                "words_count": len(words),
                "transcript_length": len(transcript or ""),
            }
        except Exception as e:
            return {
                "duration": "-",
                "detected_language": "-",
                "confidence": "-",
                "response_keys": "-",
                "alternatives_count": 0,
                "words_count": 0,
                "transcript_length": len(transcript or ""),
                "error": str(e)[:120],
            }

    @staticmethod
    def _extract_transcript(data: dict) -> str:
        try:
            alt = (
                data.get("results", {})
                .get("channels", [{}])[0]
                .get("alternatives", [{}])[0]
            )
            transcript = (alt.get("transcript") or "").strip()
            if transcript:
                return transcript
            words = alt.get("words") or []
            word_text = " ".join((item.get("punctuated_word") or item.get("word") or "").strip() for item in words).strip()
            if word_text:
                return word_text
            paragraphs = (
                alt.get("paragraphs", {})
                .get("paragraphs", [])
            )
            paragraph_text = " ".join((item.get("text") or "").strip() for item in paragraphs).strip()
            return paragraph_text
        except Exception:
            return ""

    @staticmethod
    def _debug_payload(data: dict, body_preview: str = "") -> str:
        try:
            metadata = data.get("metadata", {}) if isinstance(data, dict) else {}
            results = data.get("results", {}) if isinstance(data, dict) else {}
            keys = ",".join(list(data.keys())[:8]) if isinstance(data, dict) else "-"
            channels = results.get("channels") or []
            detected_language = ""
            if channels:
                detected_language = str((channels[0].get("detected_language") or channels[0].get("language") or ""))
            stats = AgentDeepgram._result_stats(data, AgentDeepgram._extract_transcript(data))
            return (
                f"response_keys={keys}; duration={stats.get('duration') or metadata.get('duration') or '-'}; "
                f"lang={detected_language or stats.get('detected_language') or '-'}; "
                f"confidence={stats.get('confidence') or '-'}; "
                f"error={data.get('error') or data.get('message') or '-'}; "
                f"body={body_preview[:500]}"
            )
        except Exception as e:
            return f"debug_parse_failed={str(e)[:120]}; body={body_preview[:500]}"

    @staticmethod
    async def diagnostic(file_bytes: bytes, content_type: str = "application/octet-stream") -> dict:
        if not DEEPGRAM_API_KEY:
            return {"status": "MISSING", "http_status": 0, "error": "DEEPGRAM_API_KEY missing"}
        try:
            async with httpx.AsyncClient() as client:
                res = await client.post(
                    "https://api.deepgram.com/v1/listen",
                    params=AgentDeepgram.REQUEST_PARAMS,
                    headers={
                        "Authorization": f"Token {DEEPGRAM_API_KEY}",
                        "Content-Type": content_type or "application/octet-stream",
                    },
                    content=file_bytes,
                    timeout=60.0,
                )
            body_preview = sanitize_log_text(res.text or "")[:500]
            data = {}
            if "json" in str(res.headers.get("content-type", "")).lower():
                try:
                    data = res.json()
                except Exception:
                    data = {}
            transcript = AgentDeepgram._extract_transcript(data) if data else ""
            stats = AgentDeepgram._result_stats(data, transcript)
            status = "PASS" if res.status_code == 200 and transcript else ("EMPTY_TRANSCRIPT" if res.status_code == 200 else "FAIL")
            return {
                "status": status,
                "http_status": int(res.status_code or 0),
                "content_type": str(res.headers.get("content-type", "") or ""),
                "body_preview": body_preview[:300],
                "transcript": transcript,
                "stats": stats,
                "error": str((data or {}).get("error") or (data or {}).get("message") or "")[:240],
            }
        except Exception as e:
            return {"status": "FAIL", "http_status": 0, "error": str(e)[:240], "stats": {}, "body_preview": ""}

    @staticmethod
    async def transcribe(file_bytes: bytes, context: ContextTypes.DEFAULT_TYPE, content_type: str = "application/octet-stream") -> str:
        if not DEEPGRAM_API_KEY:
            return "❌ Chưa cấu hình DEEPGRAM_API_KEY."
        try:
            async with httpx.AsyncClient() as client:
                res = await client.post(
                    "https://api.deepgram.com/v1/listen",
                    params=AgentDeepgram.REQUEST_PARAMS,
                    headers={
                        "Authorization": f"Token {DEEPGRAM_API_KEY}",
                        "Content-Type": content_type or "application/octet-stream",
                    },
                    content=file_bytes,
                    timeout=60.0
                )
            body_preview = sanitize_log_text(res.text or "")[:500]
            if res.status_code == 200:
                try:
                    data = res.json()
                except Exception:
                    data = {}
                transcript = AgentDeepgram._extract_transcript(data)
                if not transcript:
                    debug = AgentDeepgram._debug_payload(data, body_preview)
                    stats = AgentDeepgram._result_stats(data, transcript)
                    duration = stats.get("duration") or "-"
                    detected_language = stats.get("detected_language") or "-"
                    record_api_debug("deepgram", "stt", "EMPTY_TRANSCRIPT", res.status_code, debug[:500])
                    await alert_admin(context, "Deepgram empty transcript", debug[:300])
                    return (
                        "❌ Deepgram không nhận được lời nói rõ trong file.\n"
                        f"• Duration: {duration}s\n"
                        f"• Detected language: {detected_language}\n"
                        "• Gợi ý: gửi voice/audio 10-20 giây, nói rõ, ít nhạc nền/ồn."
                    )
                record_api_debug("deepgram", "stt", "PASS", res.status_code, f"chars={len(transcript)}")
                return transcript
            error_preview = body_preview[:300]
            record_api_debug("deepgram", "stt", "FAIL", res.status_code, error_preview)
            await alert_admin(context, "Deepgram", f"HTTP {res.status_code}: {error_preview[:220]}")
            return f"❌ Deepgram HTTP {res.status_code}: {error_preview}"
        except Exception as e:
            record_api_debug("deepgram", "stt", "FAIL", 0, str(e)[:300])
            return f"❌ Lỗi: {str(e)}"

def detect_image_format(data: bytes) -> str:
    data = data or b""
    if data.startswith(b"\x89PNG"):
        return "png"
    if data.startswith(b"\xff\xd8"):
        return "jpeg"
    if data.startswith(b"RIFF") and b"WEBP" in data[:16]:
        return "webp"
    return ""

def normalize_image_png_bytes(data: bytes) -> tuple[bool, bytes, str]:
    if not data:
        return False, b"", "empty_response"
    image_format = detect_image_format(data)
    if not image_format:
        return False, b"", "invalid_image_magic"
    if Image is None:
        if image_format == "png":
            return True, data, "png"
        return False, b"", f"PIL_unavailable_for_{image_format}"
    try:
        with Image.open(io.BytesIO(data)) as img:
            if img.mode not in {"RGB", "RGBA"}:
                img = img.convert("RGBA")
            out = io.BytesIO()
            img.save(out, format="PNG")
            return True, out.getvalue(), image_format
    except Exception as e:
        return False, b"", f"image_decode_failed: {str(e)[:180]}"

def normalize_provider_image_response(res, provider_name: str) -> tuple[bool, bytes, str]:
    status_code = int(getattr(res, "status_code", 0) or 0)
    content_type = str(getattr(res, "headers", {}).get("content-type", "") or "").lower()
    if status_code != 200:
        preview = ""
        try:
            preview = sanitize_log_text(str(getattr(res, "text", "") or ""))[:500]
        except Exception:
            preview = ""
        return False, b"", f"{provider_name} HTTP {status_code}; content_type={content_type or '-'}; body={preview}"
    if "json" in content_type or content_type.startswith("text/"):
        preview = ""
        try:
            preview = sanitize_log_text(str(getattr(res, "text", "") or ""))[:500]
        except Exception:
            preview = ""
        return False, b"", f"{provider_name} HTTP {status_code}; content_type={content_type or 'text/json'}; body={preview}"
    ok, png_bytes, detail = normalize_image_png_bytes(bytes(getattr(res, "content", b"") or b""))
    if not ok:
        return False, b"", f"{provider_name} HTTP {status_code}; content_type={content_type or '-'}; invalid_image={detail}"
    return True, png_bytes, f"{provider_name} {detail}->png"

def format_image_provider_status(provider_name: str, status: str, detail: str = "") -> str:
    status = str(status or "MISSING").upper()
    if status != "FAIL":
        return status
    detail = sanitize_log_text(str(detail or "")).strip()
    pattern = rf"{re.escape(provider_name)}\s+HTTP\s+(\d+);\s*content_type=([^;]+);\s*(?:body|invalid_image)=(.*)"
    match = re.search(pattern, detail, flags=re.IGNORECASE | re.DOTALL)
    if match:
        code = match.group(1)
        content_type = (match.group(2) or "-").strip()
        body = re.sub(r"\s+", " ", (match.group(3) or "").strip())[:300]
        return f"FAIL HTTP {code} {content_type} — {body or '-'}"
    compact_detail = re.sub(r"\s+", " ", detail)[:300]
    return f"FAIL — {compact_detail or '-'}"

def image_provider_detail_parts(provider_name: str, status: str, detail: str = "") -> dict:
    detail = sanitize_log_text(str(detail or "")).strip()
    result = {"status": str(status or "MISSING").upper(), "http": "-", "content_type": "-", "detail": "-"}
    if result["status"] == "PASS":
        result["detail"] = detail or "PNG hợp lệ"
        return result
    if result["status"] == "MISSING":
        result["detail"] = "Chưa cấu hình API key."
        return result
    pattern = rf"{re.escape(provider_name)}\s+HTTP\s+(\d+);\s*content_type=([^;]+);\s*(?:body|invalid_image)=(.*)"
    match = re.search(pattern, detail, flags=re.IGNORECASE | re.DOTALL)
    if match:
        result["http"] = match.group(1)
        result["content_type"] = (match.group(2) or "-").strip()
        result["detail"] = re.sub(r"\s+", " ", (match.group(3) or "").strip())[:300] or "-"
    else:
        result["detail"] = re.sub(r"\s+", " ", detail)[:300] or "-"
    return result

def image_provider_block(provider_name: str, info: dict) -> list[str]:
    parts = image_provider_detail_parts(provider_name, info.get("status"), info.get("detail"))
    return [
        f"• {provider_name}: <code>{html.escape(parts['status'])}</code>",
        f"  HTTP: <code>{html.escape(str(parts['http']))}</code>",
        f"  Content-Type: <code>{html.escape(str(parts['content_type']))}</code>",
        f"  Detail: <code>{html.escape(str(parts['detail'])[:300])}</code>",
    ]

def inspect_image_bytes(img_bytes: bytes) -> dict:
    result = {"size": len(img_bytes or b""), "pil_ok": False, "format": "-", "mode": "-", "dimensions": "-", "error": ""}
    if Image is None:
        result["error"] = "PIL unavailable"
        return result
    try:
        with Image.open(io.BytesIO(img_bytes or b"")) as img:
            result.update({
                "pil_ok": True,
                "format": str(img.format or "-"),
                "mode": str(img.mode or "-"),
                "dimensions": f"{img.width}x{img.height}",
            })
    except Exception as e:
        result["error"] = str(e)[:180]
    return result

async def run_image_provider_tests(img_bytes: bytes) -> dict:
    result = {
        "removebg": {"status": "MISSING", "detail": "", "http": 0},
        "cutout": {"status": "MISSING", "detail": "", "http": 0},
        "output_bytes": b"",
        "output_provider": "",
    }
    if REMOVEBG_API_KEY:
        try:
            async with httpx.AsyncClient(timeout=45.0) as client:
                res = await client.post(
                    "https://api.remove.bg/v1.0/removebg",
                    headers={"X-Api-Key": REMOVEBG_API_KEY},
                    files={"image_file": ("tool-test.png", img_bytes, "image/png")},
                    data={"size": "auto"},
                )
            image_ok, png_bytes, image_detail = normalize_provider_image_response(res, "RemoveBG")
            status = "PASS" if image_ok else "FAIL"
            result["removebg"] = {"status": status, "detail": image_detail, "http": int(getattr(res, "status_code", 0) or 0)}
            record_api_debug("removebg", "remove_bg", status, getattr(res, "status_code", 0), image_detail)
            if image_ok:
                result["output_bytes"] = png_bytes
                result["output_provider"] = "RemoveBG"
        except Exception as e:
            detail = str(e)[:300]
            result["removebg"] = {"status": "FAIL", "detail": detail, "http": 0}
            record_api_debug("removebg", "remove_bg", "FAIL", 0, detail)
    if not result["output_bytes"] and CUTOUT_API_KEY:
        try:
            async with httpx.AsyncClient(timeout=45.0) as client:
                res = await client.post(
                    "https://www.cutout.pro/api/v1/matting2?mattingType=2&crop=true",
                    headers={"APIKEY": CUTOUT_API_KEY},
                    files={"file": ("tool-test.png", img_bytes, "image/png")},
                )
            image_ok, png_bytes, image_detail = normalize_provider_image_response(res, "Cutout")
            status = "PASS" if image_ok else "FAIL"
            result["cutout"] = {"status": status, "detail": image_detail, "http": int(getattr(res, "status_code", 0) or 0)}
            record_api_debug("cutout", "remove_bg", status, getattr(res, "status_code", 0), image_detail)
            if image_ok:
                result["output_bytes"] = png_bytes
                result["output_provider"] = "Cutout"
        except Exception as e:
            detail = str(e)[:300]
            result["cutout"] = {"status": "FAIL", "detail": detail, "http": 0}
            record_api_debug("cutout", "remove_bg", "FAIL", 0, detail)
    return result

def telegram_png_document(data: bytes, filename: str = "no_bg.png") -> io.BytesIO:
    out = io.BytesIO(data)
    out.name = filename
    return out

class AgentVoice:
    @staticmethod
    async def render(text: str, user_id, context: ContextTypes.DEFAULT_TYPE, chat_id: int, cost: int) -> bool:
        out = f"v_{user_id}.mp3"
        msg = await context.bot.send_message(
            chat_id=chat_id,
            text="⏳ <i>[Giọng Nói] Đang tổng hợp...</i>",
            parse_mode="HTML"
        )
        used_fish = False
        try:
            if FISH_AUDIO_KEY:
                async with httpx.AsyncClient() as client:
                    res = await client.post(
                        "https://api.fish.audio/v1/tts",
                        headers={
                            "Authorization": f"Bearer {FISH_AUDIO_KEY}",
                            "Content-Type": "application/json"
                        },
                        json={
                            "text": text,
                            "reference_id": "7f0955e88846433e9ecb241357608bf8",
                            "format": "mp3"
                        },
                        timeout=30.0
                    )
                if res.status_code == 200:
                    with open(out, "wb") as f:
                        f.write(res.content)
                    used_fish = True
                    with open(out, "rb") as f:
                        await context.bot.send_audio(
                            chat_id=chat_id, audio=f,
                            caption=f"🎙️ Gói Cao Cấp — Tổng hợp thành công! (-{cost} Xu)"
                        )
                    await msg.delete()
                    return True
                else:
                    logger.warning(f"Fish Audio lỗi {res.status_code} — fallback Edge TTS")

            if not edge_tts:
                raise RuntimeError(f"edge-tts package missing: {EDGE_TTS_IMPORT_ERROR or 'import failed'}")
            communicate = edge_tts.Communicate(text, "vi-VN-NamMinhNeural")
            await communicate.save(out)
            if os.path.exists(out) and os.path.getsize(out) > 0:
                with open(out, "rb") as f:
                    await context.bot.send_audio(
                        chat_id=chat_id, audio=f,
                        caption=f"🔊 Gói Tiết Kiệm — Tổng hợp giọng nói thành công! (-{VOICE_FREE_COST} Xu)"
                    )
                await msg.delete()
                return False
            await msg.edit_text("❌ Cả hai gói đều gặp lỗi.")

        except Exception as e:
            logger.error(f"Voice error: {e}")
            await msg.edit_text("❌ Lỗi Voice.")
        finally:
            if os.path.exists(out):
                os.remove(out)
        return used_fish

class AgentDownloader:
    MAX_TELEGRAM_DOWNLOAD_BYTES = 48 * 1024 * 1024
    BLOCKED_EXTERNAL_PROMO_MARKERS = [
        "t.me/a_tools",
        "telegram.me/a_tools",
        "join our channel",
        "must join our channel",
        "view channel",
        "a_tools x",
        "a-tools x",
    ]

    @staticmethod
    def _is_admin_target(user_id=None, chat_id=None):
        return str(user_id or chat_id or "") == ADMIN_ID

    @staticmethod
    def _refund_line(cost: int) -> str:
        return f"✅ Đã hoàn lại <b>{cost}</b> Xu.\n" if int(cost or 0) > 0 else ""

    @staticmethod
    def _is_suspicious_downloader_result(data, media_url: str = ""):
        blob = f"{media_url}\n{json.dumps(data, ensure_ascii=False)[:2000]}".lower()
        return any(marker in blob for marker in AgentDownloader.BLOCKED_EXTERNAL_PROMO_MARKERS)

    @staticmethod
    def _uses_public_cobalt(api_base: str) -> bool:
        return (api_base or "").rstrip("/").lower() == "https://api.cobalt.tools"

    @staticmethod
    async def _hide_suspicious_downloader_result(msg, user_id, cost, data, media_url="", chat_id=None):
        if user_id and cost > 0:
            refund_charged_credit(user_id, cost, "download_refund", "", "Downloader trả quảng cáo/join channel ngoài", True)
        is_admin = AgentDownloader._is_admin_target(user_id, chat_id)
        admin_detail = ""
        admin_note = ""
        if is_admin:
            detail = json.dumps(
                {"media_url": media_url, "response": data},
                ensure_ascii=False,
            )[:1200]
            admin_detail = f"\n\n⚠️ Admin debug:\n<pre>{html_pre(detail, 1200)}</pre>"
            admin_note = "\nAdmin nên self-host Cobalt riêng và set <code>COBALT_API_URL</code> để tải ổn định."
        await msg.edit_text(
            "❌ Dịch vụ tải video trả về nguồn không hợp lệ nên bot đã chặn để không hiện quảng cáo/kênh lạ.\n"
            + AgentDownloader._refund_line(cost)
            + ("Bạn có thể gửi file video trực tiếp để bot xử lý tiếp." if not is_admin else admin_note)
            + admin_detail,
            parse_mode="HTML"
        )

    @staticmethod
    async def _send_media_url_or_file(context: ContextTypes.DEFAULT_TYPE, chat_id: int, media_url: str, caption: str, filename: str = ""):
        try:
            await context.bot.send_video(
                chat_id=chat_id,
                video=media_url,
                caption=caption,
                parse_mode="HTML"
            )
            return True, "sent_by_url"
        except Exception as e:
            logger.warning(f"Telegram send_video by URL failed, will download locally: {e}")

        suffix = os.path.splitext((filename or "").split("?")[0])[1] or ".mp4"
        tmp_path = ""
        try:
            total = 0
            with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as tmp:
                tmp_path = tmp.name
            async with httpx.AsyncClient(follow_redirects=True, timeout=120.0) as client:
                async with client.stream("GET", media_url, headers={"User-Agent": "TOAN-AAS-Bot/1.0"}) as res:
                    if res.status_code >= 400:
                        return False, f"media_http_{res.status_code}"
                    content_length = int(res.headers.get("content-length") or 0)
                    if content_length > AgentDownloader.MAX_TELEGRAM_DOWNLOAD_BYTES:
                        return False, f"media_too_large_{content_length}"
                    with open(tmp_path, "wb") as f:
                        async for chunk in res.aiter_bytes(1024 * 256):
                            if not chunk:
                                continue
                            total += len(chunk)
                            if total > AgentDownloader.MAX_TELEGRAM_DOWNLOAD_BYTES:
                                return False, f"media_too_large_{total}"
                            f.write(chunk)
            if not total:
                return False, "media_empty"
            with open(tmp_path, "rb") as f:
                try:
                    await context.bot.send_video(
                        chat_id=chat_id,
                        video=f,
                        caption=caption,
                        parse_mode="HTML"
                    )
                except Exception:
                    f.seek(0)
                    await context.bot.send_document(
                        chat_id=chat_id,
                        document=f,
                        filename=filename or "toan-daas-video.mp4",
                        caption=caption,
                        parse_mode="HTML"
                    )
            return True, "sent_by_local_file"
        except Exception as e:
            logger.error(f"Downloader local media send failed: {e}")
            return False, str(e)
        finally:
            if tmp_path and os.path.exists(tmp_path):
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass

    @staticmethod
    async def download(url: str, context: ContextTypes.DEFAULT_TYPE, chat_id: int, cost: int, user_id=None):
        msg = await context.bot.send_message(
            chat_id=chat_id,
            text="⏳ <i>Đang bóc tách video...</i>",
            parse_mode="HTML"
        )
        try:
            api_base = (COBALT_API_URL or "").rstrip("/")
            is_admin = AgentDownloader._is_admin_target(user_id, chat_id)
            if not api_base:
                if user_id and cost > 0:
                    refund_charged_credit(user_id, cost, "download_refund", "", "Cobalt self-host missing", True)
                admin_hint = (
                    "\n\n⚠️ Admin: self-host Cobalt trên Railway/VPS rồi set <code>COBALT_API_URL</code>."
                    if is_admin else
                    ""
                )
                await msg.edit_text(
                    "❌ Tải video qua link đang tạm khóa vì chưa cấu hình Cobalt self-host.\n"
                    + AgentDownloader._refund_line(cost)
                    + "Bạn có thể gửi file video trực tiếp để bot xử lý tiếp."
                    + admin_hint,
                    parse_mode="HTML"
                )
                return
            if AgentDownloader._uses_public_cobalt(api_base):
                if user_id and cost > 0:
                    refund_charged_credit(user_id, cost, "download_refund", "", "Public Cobalt bị tắt để tránh quảng cáo/join channel ngoài", True)
                admin_hint = (
                    "\n\n⚠️ Admin: public <code>api.cobalt.tools</code> thường trả bot protection hoặc kênh quảng cáo. "
                    "Hãy self-host Cobalt trên Railway rồi set <code>COBALT_API_URL</code>."
                    if is_admin else
                    ""
                )
                await msg.edit_text(
                    "❌ Tải video qua link đang tạm khóa để tránh hiện quảng cáo/kênh lạ cho khách.\n"
                    + AgentDownloader._refund_line(cost)
                    + "Bạn có thể gửi file video trực tiếp để bot xử lý tiếp."
                    + admin_hint,
                    parse_mode="HTML"
                )
                return
            headers = {"Accept": "application/json", "Content-Type": "application/json"}
            if COBALT_API_KEY:
                headers["Authorization"] = f"Api-Key {COBALT_API_KEY}"
            payload = {
                "url": url,
                "downloadMode": "auto",
                "videoQuality": "1080",
                "filenameStyle": "basic",
                "localProcessing": "disabled",
            }
            async with httpx.AsyncClient() as client:
                res = await client.post(
                    api_base + "/",
                    headers=headers,
                    json=payload,
                    timeout=30.0
                )
            try:
                data = res.json()
            except Exception:
                data = {"status": "error", "error": {"code": f"http_{res.status_code}", "context": {"body": res.text[:300]}}}

            status = data.get("status")
            media_url = data.get("url", "")
            filename = data.get("filename", "")
            if status == "picker":
                picker = data.get("picker") or []
                video_item = next((item for item in picker if item.get("type") == "video" and item.get("url")), None)
                media_url = (video_item or (picker[0] if picker else {})).get("url", "")
                filename = (video_item or (picker[0] if picker else {})).get("filename", filename)
            if AgentDownloader._is_suspicious_downloader_result(data, media_url):
                await AgentDownloader._hide_suspicious_downloader_result(msg, user_id, cost, data, media_url, chat_id)
                return
            if res.status_code == 200 and status in {"tunnel", "redirect", "stream", "success", "picker"} and media_url:
                caption = f"🎬 Đã làm sạch! (-{cost} Xu)" + (f"\n<code>{html.escape(filename)}</code>" if filename else "")
                sent, send_reason = await AgentDownloader._send_media_url_or_file(
                    context, chat_id, media_url, caption, filename
                )
                if sent:
                    await msg.delete()
                else:
                    if user_id and cost > 0:
                        refund_charged_credit(user_id, cost, "download_refund", "", f"Không gửi được media: {send_reason}", True)
                    kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔗 Mở link tải video", url=media_url)]])
                    await msg.edit_text(
                        "⚠️ Đã lấy được link video nhưng Telegram không nhận được file trực tiếp.\n"
                        + AgentDownloader._refund_line(cost)
                        + "Bạn có thể mở link bên dưới để tải thủ công hoặc gửi file video trực tiếp.",
                        parse_mode="HTML",
                        reply_markup=kb
                    )
            else:
                if user_id and cost > 0:
                    refund_charged_credit(user_id, cost, "download_refund", "", "Cobalt không trả media_url", True)
                err = data.get("error") if isinstance(data, dict) else {}
                err_code = err.get("code") if isinstance(err, dict) else ""
                is_admin = AgentDownloader._is_admin_target(user_id, chat_id)
                admin_hint = ""
                if is_admin:
                    admin_hint = (
                        "\n\n⚠️ Admin: public <code>api.cobalt.tools</code> có bot protection. "
                        "Nên self-host Cobalt trên Railway rồi set <code>COBALT_API_URL</code>"
                        + (" và <code>COBALT_API_KEY</code>." if not COBALT_API_KEY else ".")
                    )
                    if err_code:
                        admin_hint += f"\nMã lỗi: <code>{html.escape(err_code)}</code>"
                await msg.edit_text(
                    "❌ Link không hỗ trợ, video riêng tư/cần đăng nhập, hoặc dịch vụ tải đang bảo trì.\n"
                    + AgentDownloader._refund_line(cost)
                    + ("Bạn có thể gửi file video trực tiếp để bot xử lý tiếp." if not is_admin else "")
                    + admin_hint,
                    parse_mode="HTML"
                )
        except Exception as e:
            logger.error(f"Downloader error: {e}")
            if user_id and cost > 0:
                refund_charged_credit(user_id, cost, "download_refund", "", "Exception trong downloader", True)
            is_admin = AgentDownloader._is_admin_target(user_id, chat_id)
            admin_hint = (
                "\n\n⚠️ Admin: kiểm tra <code>COBALT_API_URL</code>, <code>COBALT_API_KEY</code> hoặc self-host Cobalt."
                if is_admin else
                "\n\nBạn có thể gửi file video trực tiếp để bot xử lý tiếp."
            )
            await msg.edit_text(
                "❌ Lỗi luồng tải video.\n"
                + AgentDownloader._refund_line(cost)
                + admin_hint,
                parse_mode="HTML"
            )

