def shopaikey_sanitize_error(value: str) -> str:
    safe = sanitize_log_text(str(value or ""))
    safe = re.sub(r"apiKey=([^&\s]+)", "apiKey=***", safe, flags=re.IGNORECASE)
    safe = re.sub(r"Bearer\s+[^\s\"']+", "Bearer ***", safe, flags=re.IGNORECASE)
    return safe[:500]

