async def cmd_data_delete(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    user_id = user.id if user else 0
    text = (
        "🗑 <b>Yêu cầu xóa dữ liệu</b>\n\n"
        "Bạn có thể yêu cầu admin kiểm tra/xóa dữ liệu phù hợp liên quan đến tài khoản Telegram của bạn.\n\n"
        f"ID Telegram của bạn: <code>{html.escape(str(user_id))}</code>\n\n"
        f"Vui lòng nhắn admin/hỗ trợ: {support_link_html()}\n\n"
        "Lưu ý: Một số dữ liệu giao dịch, log nạp Xu dịch vụ hoặc dữ liệu cần thiết cho đối soát/chống gian lận "
        "có thể cần được lưu theo yêu cầu vận hành/kế toán/an toàn hệ thống."
    )
    await update.message.reply_text(text, parse_mode="HTML")
    if ADMIN_ID:
        try:
            username, full_name, contact_url = telegram_user_contact_text(user)
            await context.bot.send_message(
                chat_id=int(ADMIN_ID),
                text=(
                    "🗑 <b>DATA DELETE REQUEST</b>\n\n"
                    f"• User ID: <code>{html.escape(str(user_id))}</code>\n"
                    f"• Username: @{html.escape(username)}\n"
                    f"• Name: {html.escape(full_name or '-')}\n"
                    f"• Contact: {html.escape(contact_url or '-')}"
                ),
                parse_mode="HTML",
            )
        except Exception as e:
            logger.warning(f"Could not notify admin about data delete request: {e}")

async def cmd_mydata(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    uid = user.id if user else 0
    username = user.username if user else ""
    credits, total_spent, is_vip = get_user(uid, username or "Unknown")
    conn = db_connect()
    try:
        row = conn.execute("SELECT join_date FROM users WHERE user_id=?", (str(uid),)).fetchone()
        trial = conn.execute("SELECT granted_xu, granted_at FROM trial_grants WHERE user_id=?", (str(uid),)).fetchone()
    finally:
        conn.close()
    pending = get_user_pending_promo(uid)
    pending_code = (pending.get("promo") or {}).get("code") or "-"
    lines = [
        "🔎 <b>Dữ liệu tài khoản của tôi</b>",
        "",
        f"• ID Telegram: <code>{html.escape(str(uid))}</code>",
        f"• Username: <code>{html.escape('@' + username if username else '-')}</code>",
        f"• Số dư Xu dịch vụ: <b>{int(credits)} Xu</b>",
        f"• Tổng Xu dịch vụ đã dùng/nạp: <b>{int(total_spent or 0)} Xu</b>",
        f"• VIP/Admin: <code>{'yes' if is_vip or is_admin_user(uid) else 'no'}</code>",
        f"• Ngày tham gia: <code>{html.escape(str(row[0] if row else '-'))}</code>",
        f"• Trial: <code>{html.escape(str(trial[0]) + ' Xu lúc ' + str(trial[1]) if trial else 'chưa ghi nhận')}</code>",
        f"• Promo đang chờ: <code>{html.escape(str(pending_code))}</code>",
        "",
        "Lệnh này không gửi bill, file, audio, video hoặc dữ liệu nhạy cảm.",
        "Yêu cầu hỗ trợ/xóa dữ liệu phù hợp: <code>/data_delete</code>",
    ]
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def on_telegram_error(update: object, context: ContextTypes.DEFAULT_TYPE):
    error = context.error
    error_name = type(error).__name__ if error else "UnknownError"
    error_text = sanitize_log_text(str(error or ""))[:1200]
    message_text = ""
    if isinstance(update, Update) and update.effective_message:
        message_text = str(getattr(update.effective_message, "text", "") or "").strip()
    callback_data = ""
    if isinstance(update, Update) and update.callback_query:
        callback_data = str(update.callback_query.data or "").strip()
    image_to_pdf_safe_error = (
        message_text.startswith("/image_to_pdf")
        or ('unsupported start tag "yêu"' in error_text.lower())
    )
    audio_timeout_safe_error = (
        is_audio_timeout_error(error)
        and (
            message_text.startswith(("/translate_voice", "/translate_audio", "/transcribe"))
            or callback_data.startswith("tr_")
        )
    )
    if error:
        logger.error(
            "Telegram handler error\n%s",
            sanitize_log_text("".join(traceback.format_exception(type(error), error, error.__traceback__)))[:4000],
        )
    else:
        logger.error("Telegram handler error | type=%s", error_name)

    try:
        if isinstance(update, Update) and update.effective_chat:
            text = (
                TRANSLATE_AUDIO_TIMEOUT_TEXT if audio_timeout_safe_error else
                "❌ Không tạo được PDF từ ảnh này. Bot chưa trừ Xu. Vui lòng thử lại sau."
                if image_to_pdf_safe_error else
                "❌ Có lỗi khi xử lý lệnh. Bot chưa trừ Xu. Vui lòng thử lại sau."
            )
            if (
                not image_to_pdf_safe_error
                and not audio_timeout_safe_error
                and update.effective_user
                and is_admin_or_owner(update.effective_user.id)
                and ADMIN_DEBUG_PUBLIC_ERRORS
            ):
                text += f"\n\n<code>{html.escape(error_name)}: {html.escape(error_text[:800])}</code>"
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=text,
                parse_mode=None if (image_to_pdf_safe_error or audio_timeout_safe_error) else "HTML",
            )
    except Exception:
        logger.exception("Failed to notify user about Telegram handler error")

    try:
        if ADMIN_ID and ADMIN_DEBUG_PUBLIC_ERRORS and not image_to_pdf_safe_error and not audio_timeout_safe_error:
            await context.bot.send_message(
                chat_id=int(ADMIN_ID),
                text=(
                    "🚨 <b>BOT COMMAND DEBUG ERROR</b>\n\n"
                    f"<code>{html.escape(error_name)}: {html.escape(error_text)}</code>"
                ),
                parse_mode="HTML",
            )
    except Exception:
        pass

async def safe_edit_query_message(query, text: str, reply_markup=None, parse_mode: str | None = "HTML"):
    try:
        return await query.edit_message_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
    except Exception as e:
        if "message is not modified" in str(e).lower():
            return None
        if any(fragment in str(e).lower() for fragment in (
            "there is no text in the message to edit",
            "query is too old",
            "message to edit not found",
            "message can't be edited",
            "message is not editable",
        )):
            logger.warning("safe_edit_query_message fallback | %s", sanitize_log_text(str(e))[:240])
            message = getattr(query, "message", None)
            if message:
                try:
                    await message.reply_text("Có lỗi nhỏ khi cập nhật màn hình. Bot đã gửi lại bước tiếp theo bên dưới.")
                    return await message.reply_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
                except Exception as send_error:
                    logger.warning("safe_edit_query_message fallback failed | %s", sanitize_log_text(str(send_error))[:240])
                    return None
        raise

def is_soft_telegram_edit_error(error: Exception) -> bool:
    text = str(error or "").lower()
    return any(fragment in text for fragment in (
        "there is no text in the message to edit",
        "message is not modified",
        "query is too old",
        "message to edit not found",
        "message can't be edited",
        "message is not editable",
    ))

async def safe_edit_or_send(query, text: str, reply_markup=None, parse_mode: str | None = "HTML"):
    """Edit callback message when possible; otherwise send a fresh message."""
    if not query:
        return None
    message = getattr(query, "message", None)
    try:
        return await query.edit_message_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
    except Exception as e:
        if "message is not modified" in str(e).lower():
            return None
        if not is_soft_telegram_edit_error(e):
            raise
        logger.warning("safe_edit_or_send fallback | %s", sanitize_log_text(str(e))[:240])
        try:
            if message:
                await message.reply_text(
                    "Có lỗi nhỏ khi cập nhật màn hình. Bot đã gửi lại bước tiếp theo bên dưới."
                    if parse_mode == "HTML" else
                    "Có lỗi nhỏ khi cập nhật màn hình. Bot đã gửi lại bước tiếp theo bên dưới."
                )
                return await message.reply_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
        except Exception as send_error:
            logger.warning("safe_edit_or_send reply fallback failed | %s", sanitize_log_text(str(send_error))[:240])
        try:
            bot = getattr(query, "bot", None)
            chat_id = getattr(message, "chat_id", None) if message else None
            if bot and chat_id:
                return await bot.send_message(chat_id=chat_id, text=text, parse_mode=parse_mode, reply_markup=reply_markup)
        except Exception as send_error:
            logger.warning("safe_edit_or_send bot fallback failed | %s", sanitize_log_text(str(send_error))[:240])
        return None

async def handle_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    action = (query.data.split("|", 1)[1] if "|" in query.data else "main").strip()
    user_is_admin = is_admin_user(query.from_user.id)
    lang = get_user_language(query.from_user.id) or "vi"
    clear_media_creator_pending_states(query.from_user.id)
    admin_only = {"affiliate", "operator", "admin", "system"}
    public_hints = {
        "hint_naptien", "hint_profile", "hint_terms", "hint_film", "hint_ai_prompt",
        "hint_note", "hint_search_note", "hint_remind", "hint_doc_tools", "hint_pricing",
        "hint_image_tools", "hint_image_to_video_pack", "hint_media_factory",
    }
    if action in admin_only and not user_is_admin:
        return await query.answer("Khu vực này chỉ dành cho Admin.", show_alert=True)
    if action.startswith("hint_") and not user_is_admin and action not in public_hints:
        return await query.answer("Lệnh nội bộ chỉ dành cho Admin.", show_alert=True)
    if action == "hint_pricing":
        return await send_pricing_lines(query.message, pricing_main_lines_i18n(lang), pricing_main_keyboard(lang))
    if action == "main_guide":
        return await safe_edit_query_message(
            query,
            help_text_for_user_i18n(query.from_user.id),
            reply_markup=localized_main_menu_keyboard(user_is_admin, lang),
        )
    if action == "create_media":
        return await safe_edit_query_message(
            query,
            create_media_open_text(query.from_user.id),
            reply_markup=create_media_menu_keyboard(lang),
        )
    if action == "support":
        return await safe_edit_query_message(
            query,
            support_contact_text(),
            reply_markup=support_contact_keyboard(lang=lang),
        )
    if action.startswith("translate_set_"):
        target = normalize_translate_target(action.replace("translate_set_", "", 1))
        if not target:
            return await query.answer("Ngôn ngữ chưa hỗ trợ.", show_alert=True)
        set_user_translate_mode(
            query.from_user.id,
            target,
            username=query.from_user.username or query.from_user.first_name or "",
            note=f"User enabled translate mode from menu target={target}",
        )
        if normalize_user_language(lang) == "vi":
            text = (
                f"✅ Đã bật dịch tự động sang <b>{html.escape(translate_target_label(target))}</b>.\n\n"
                "Từ bây giờ, tin nhắn văn bản thường sẽ được dịch thay vì chat AI.\n"
                "Tắt bằng <code>/translate_mode_off</code> hoặc nút bên dưới."
            )
        else:
            text = (
                f"✅ Auto-translate is ON to <b>{html.escape(translate_target_label(target))}</b>.\n\n"
                "Normal text messages will be translated instead of going to AI chat.\n"
                "Disable with <code>/translate_mode_off</code> or the button below."
            )
        return await safe_edit_query_message(query, text, reply_markup=translate_language_keyboard(False, lang))
    if action == "translate_off":
        set_user_translate_mode(
            query.from_user.id,
            "",
            username=query.from_user.username or query.from_user.first_name or "",
            note="User disabled translate mode from menu",
        )
        text = (
            "✅ Đã tắt dịch tự động. Tin nhắn thường sẽ quay về AI chat."
            if normalize_user_language(lang) == "vi"
            else "✅ Auto-translate is OFF. Normal text now goes back to AI chat."
        )
        return await safe_edit_query_message(query, text, reply_markup=translate_language_keyboard(False, lang))
    text, keyboard = localized_menu_content(action, user_is_admin, lang, query.from_user.id)
    await safe_edit_query_message(query, text, reply_markup=keyboard)

async def handle_language_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    data = (query.data or "").strip()
    uid = query.from_user.id
    if data == "lang_more":
        return await safe_edit_query_message(
            query,
            other_language_choice_text(),
            reply_markup=other_language_choice_keyboard(),
        )
    if data == "back_lang":
        return await safe_edit_query_message(
            query,
            language_choice_text(),
            reply_markup=language_choice_keyboard(),
        )
    if data.startswith("lang|"):
        lang = normalize_user_language(data.split("|", 1)[1])
        if not lang:
            return await query.answer("Language is not supported.", show_alert=True)
        selected = set_user_language(uid, lang)
        username = query.from_user.username or query.from_user.first_name or ""
        record_usage_event(
            uid,
            username=username,
            event_type="language_changed",
            tool_name="core",
            command="/language",
            status=selected,
            detail=f"user_language={selected}",
        )
        return await safe_edit_query_message(
            query,
            localized_start_menu_text(uid, selected),
            reply_markup=localized_main_menu_keyboard(is_admin_user(uid), selected),
        )

async def handle_translation_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    data = (query.data or "").strip()
    uid = query.from_user.id
    if data == "tr_transcribe":
        if not has_recent_audio_input(update):
            return await query.message.reply_text("⚠️ Gửi voice/audio/video ngắn rồi gõ /transcribe trong vòng 2 phút.")
        return await cmd_transcribe(update, context)
    if data.startswith("tr_pick|"):
        source_type = data.split("|", 1)[1]
        if source_type == "voice" and not has_recent_audio_input(update):
            return await query.message.reply_text("⚠️ Gửi voice/audio/video ngắn rồi gõ /translate_voice trong vòng 2 phút.")
        return await show_translation_picker(update, source_type, edit=True)
    if data.startswith("tr_more|"):
        source_type = data.split("|", 1)[1]
        return await show_translation_picker(update, source_type, edit=True, more=True)
    if not data.startswith("tr_target|"):
        return await query.answer("Không nhận diện được lựa chọn dịch.", show_alert=True)
    parts = data.split("|")
    if len(parts) != 3:
        return await query.answer("Lựa chọn dịch không hợp lệ.", show_alert=True)
    _prefix, source_type, target = parts
    target = normalize_translate_target(target)
    if not target:
        return await query.answer("Ngôn ngữ chưa hỗ trợ.", show_alert=True)
    if source_type == "voice":
        if not has_recent_audio_input(update):
            return await query.message.reply_text("⚠️ Audio đã hết hạn. Gửi lại voice/audio/video ngắn rồi chọn dịch trong vòng 2 phút.")
        save_translation_request(uid, "voice")
        return await run_translate_voice_to_target(update, context, target)
    if source_type == "file":
        req = get_translation_request(uid, "file")
        info = (req.get("source_ref") or {}) if req else get_last_user_file(uid)
        if not info:
            return await query.message.reply_text("⚠️ Gửi file txt/docx/pdf rồi reply hoặc gõ /translate_file trong vòng 10 phút.")
        return await run_translate_file_to_target(update, context, target, info=info)
    if source_type == "text":
        req = get_translation_request(uid, "text")
        source_text = (req.get("source_text") or "").strip() if req else ""
        if not source_text:
            return await query.message.reply_text("⚠️ Gửi nội dung cần dịch, ví dụ: /translate xin chào")
        return await run_translate_text_to_target(update, context, source_text, target)
    return await query.answer("Nguồn dịch chưa hỗ trợ.", show_alert=True)

