async def cmd_shopaikey_video_from_image_public(update: Update, context: ContextTypes.DEFAULT_TYPE):
    return await cmd_shopaikey_video_public(update, context, from_image=True)

async def handle_shopaikey_public_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    parts = (query.data or "").split("|")
    uid = query.from_user.id
    lang = user_ui_lang(uid)
    if len(parts) != 3:
        return await safe_edit_or_send(query, ui_text(lang, "common.invalid_request"))
    _, action, token = parts
    if action == "cancel":
        pending_cancel = pop_shopaikey_pending_confirmation(token, uid) or {}
        cancel_tier = normalize_image_tier(pending_cancel.get("image_tier") or "")
        cancel_reason = "user_cancelled_confirmation"
        cancel_job_type = str(pending_cancel.get("job_type") or "").lower()
        if cancel_job_type == "image":
            cancel_reason += f"; tier={cancel_tier}"
        if cancel_job_type == "video":
            cancel_tier = normalize_video_tier(pending_cancel.get("video_tier") or "")
            cancel_reason += f"; tier={cancel_tier}"
            record_shopaikey_billing_event(uid, 0, "video_cancelled", 0, 0, 0, cancel_reason)
        record_shopaikey_billing_event(uid, 0, "cancel", 0, 0, 0, cancel_reason)
        return await safe_edit_or_send(query, ui_text(lang, "common.cancelled_not_charged"))
    pending = pop_shopaikey_pending_confirmation(token, uid)
    if not pending:
        return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    job_type = str(pending.get("job_type") or "").lower()
    prompt = str(pending.get("prompt") or "").strip()
    base_cost = int(pending.get("base_cost") or 0)
    image_tier = normalize_image_tier(pending.get("image_tier") or SHOPAIKEY_IMAGE_DEFAULT_TIER)
    video_tier = normalize_video_tier(pending.get("video_tier") or SHOPAIKEY_VIDEO_DEFAULT_TIER)
    tier_label = localized_image_tier_label(image_tier, lang) if job_type == "image" else localized_video_tier_label(video_tier, lang)
    pending_model = str(pending.get("model") or "").strip()
    source_job_id = str(pending.get("source_job_id") or "").strip()
    workflow_id = str(pending.get("workflow_id") or "").strip()
    trend_output_id = int(pending.get("trend_output_id") or 0)
    scene_index = int(pending.get("scene_index") or 0)
    enabled, message = shopaikey_public_generation_guard(job_type)
    if not enabled:
        return await safe_edit_or_send(query, ui_text(lang, "media.public_off"))
    if shopaikey_active_job_for_user(uid, job_type):
        if job_type == "video":
            return await safe_edit_or_send(query, ui_text(lang, "video.active_job"))
        return await safe_edit_or_send(query, ui_text(lang, "media.job_lock"))
    if job_type == "video" and source_job_id and not shopaikey_paid_image_source_available(uid, source_job_id):
        return await safe_edit_or_send(query, ui_text(lang, "video.source_invalid"))
    balance_before, _, _ = get_user(uid)
    charge = spend_fixed_credit_info(
        uid,
        base_cost,
        f"shopaikey_{job_type}",
        f"ShopAIKey {job_type}: {shopaikey_safe_prompt_preview(prompt)}",
        True,
    )
    if not charge.get("ok"):
        credits_now, _, _ = get_user(uid)
        if job_type == "image":
            record_shopaikey_billing_event(uid, 0, "insufficient_balance", 0, int(credits_now or 0), int(credits_now or 0), f"shopaikey_image; tier={image_tier}; required={int(charge.get('final_cost') or base_cost)}")
        if job_type == "video":
            record_shopaikey_billing_event(uid, 0, "video_insufficient_balance", 0, int(credits_now or 0), int(credits_now or 0), f"shopaikey_video; tier={video_tier}; required={int(charge.get('final_cost') or base_cost)}")
        return await edit_insufficient_credits(query, int(credits_now or 0), int(charge.get("final_cost") or base_cost), uid)
    deducted = int(charge.get("final_cost") or 0)
    balance_after, _, _ = get_user(uid)
    model = (pending_model or SHOPAIKEY_IMAGE_MODEL or "nano-banana") if job_type == "image" else (SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast")
    job_id = create_shopaikey_job(
        uid,
        query.message.chat_id,
        job_type,
        model=model,
        prompt=prompt,
        status="IN_PROGRESS" if job_type == "image" else "QUEUED",
        admin_only=False,
        xu_cost_planned=base_cost,
        source_job_id=source_job_id,
    )
    confirmed_at = now_text()
    update_shopaikey_job(
        job_id=job_id,
        xu_deducted=deducted,
        billing_status="deducted" if deducted > 0 else "admin_free",
        confirm_required=1 if SHOPAIKEY_REQUIRE_CONFIRM_BEFORE_DEDUCT else 0,
        confirmed_at=confirmed_at,
    )
    tier_reason = f"; tier={image_tier}; label={tier_label}" if job_type == "image" else f"; tier={video_tier}; label={tier_label}"
    record_shopaikey_billing_event(uid, job_id, "confirm" if job_type == "image" else "video_confirmed", 0, int(balance_before or 0), int(balance_before or 0), f"confirmed_at={confirmed_at}; job_type={job_type}{tier_reason}")
    record_shopaikey_billing_event(uid, job_id, "deduct" if job_type == "image" else "video_deducted", deducted, int(balance_before or 0), int(balance_after or 0), f"shopaikey_{job_type}{tier_reason}")
    if job_type == "image":
        await safe_edit_or_send(query, ui_text(lang, "image.waiting"))
        result = await shopaikey_image_generate(prompt, model)
        status = str(result.get("status") or "FAIL")
        image_url = str(result.get("image_url") or "")
        output_sent = False
        if status == "PASS" and image_url:
            if workflow_id or trend_output_id:
                update_trend_workflow_generated_image(
                    output_id=trend_output_id,
                    workflow_id=workflow_id,
                    scene_index=scene_index,
                    user_id=uid,
                    image_url=image_url,
                    job_id=job_id,
                )
                save_latest_workflow_image(
                    uid,
                    image_url,
                    prompt=prompt,
                    workflow_id=workflow_id,
                    scene_index=scene_index,
                    source="workflow_image_generation",
                    job_id=job_id,
                )
            success_markup = trend_workflow_image_success_keyboard(job_id, scene_index, lang) if (workflow_id or trend_output_id) else public_image_success_keyboard(job_id, image_tier, lang)
            success_caption = ui_text(lang, "image.success", label=html.escape(tier_label), job_id=int(job_id or 0), deducted=int(deducted or 0))
            try:
                await context.bot.send_photo(
                    chat_id=query.message.chat_id,
                    photo=image_url,
                    caption=success_caption,
                    reply_markup=success_markup,
                )
                output_sent = True
            except Exception:
                await context.bot.send_message(
                    chat_id=query.message.chat_id,
                    text=ui_text(lang, "image.success_link", url=html.escape(image_url, quote=True)),
                    parse_mode="HTML",
                    disable_web_page_preview=False,
                )
                output_sent = True
        if status != "PASS":
            provider_error_text = result.get("detail") or result.get("provider_error_code") or result.get("error_class") or status
            record_provider_error(
                "shopaikey",
                "image",
                classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, provider_error_text),
                provider_error_text,
            )
            deducted_amount = int(deducted or 0)
            record_shopaikey_billing_event(uid, job_id, "provider_fail", 0, int(balance_after or 0), int(balance_after or 0), f"shopaikey_image; tier={image_tier}; error={provider_error_text}")
            refunded = refund_shopaikey_job_if_needed(uid, job_id, "", provider_error_text) if deducted_amount > 0 else False
            balance_after_failure, _, _ = get_user(uid)
            refund_status = "refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "not_charged")
            update_shopaikey_job(
                job_id=job_id,
                status="FAILED",
                error_class=result.get("error_class") or status,
                provider_error_code=result.get("provider_error_code") or "",
                provider_message=provider_error_text,
                attempts=1,
                finished_at=now_text(),
                refund_status=refund_status,
                refund_amount=deducted_amount if refunded else 0,
                refund_reason=provider_error_text,
                billing_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "failed_not_charged"),
            )
            if deducted_amount > 0 and not refunded:
                refund_error = "auto_refund_failed"
                record_shopaikey_billing_event(
                    uid,
                    job_id,
                    "refund_failed",
                    deducted_amount,
                    int(balance_after or 0),
                    int(balance_after_failure or 0),
                    f"shopaikey_image; tier={image_tier}; provider_error={provider_error_text}; refund_error={refund_error}",
                )
                await alert_public_image_refund_failure(
                    context,
                    uid,
                    job_id,
                    image_tier,
                    deducted_amount,
                    int(balance_before or 0),
                    int(balance_after_failure or 0),
                    provider_error_text,
                    refund_error,
                )
            return await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=public_image_provider_fail_message(deducted_amount, refunded, lang),
            )
        update_shopaikey_job(job_id=job_id, status="SUCCESS", result_url=image_url, result_sent=1 if output_sent else 0, model=result.get("model") or model, attempts=1, finished_at=now_text())
        credits_after_success, _, _ = get_user(uid)
        record_shopaikey_billing_event(uid, job_id, "success", 0, int(credits_after_success or 0), int(credits_after_success or 0), f"shopaikey_image_success; tier={image_tier}")
        credits_after, _, _ = get_user(uid)
        return await context.bot.send_message(chat_id=query.message.chat_id, text=ui_text(lang, "account.balance_left", credits=int(credits_after or 0)))
    if job_type == "video":
        await safe_edit_or_send(query, ui_text(lang, "video.waiting"))
        result = await shopaikey_video_create_smoke_test(model, prompt)
        status = str(result.get("status") or "FAIL")
        task_id = str(result.get("task_id") or "")
        attempts = result.get("attempts") or []
        if status == "PASS_SUBMITTED" and task_id:
            update_shopaikey_job(
                job_id=job_id,
                task_id=task_id,
                status="IN_PROGRESS",
                model=result.get("selected_model") or result.get("model") or model,
                attempts=len(attempts),
            )
            record_shopaikey_billing_event(uid, job_id, "video_provider_submitted", deducted, int(balance_after or 0), int(balance_after or 0), f"task_id={task_id}; tier={video_tier}; provider_status={result.get('provider_status') or '-'}")
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=ui_text(lang, "video.queue_submitted", task_id=html.escape(task_id), auto_poll="ON" if SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED else "OFF"),
            )
            if SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED:
                asyncio.create_task(auto_poll_shopaikey_video_job(context.bot, job_id, query.message.chat_id, uid, task_id))
            return
        provider_error_text = result.get("message") or result.get("detail") or result.get("provider_error_code") or status
        record_provider_error(
            "shopaikey",
            "video",
            classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, provider_error_text),
            provider_error_text,
        )
        deducted_amount = int(deducted or 0)
        record_shopaikey_billing_event(uid, job_id, "video_provider_fail", 0, int(balance_after or 0), int(balance_after or 0), f"shopaikey_video; tier={video_tier}; error={provider_error_text}")
        refunded = refund_shopaikey_job_if_needed(uid, job_id, "", provider_error_text) if deducted_amount > 0 else False
        balance_after_failure, _, _ = get_user(uid)
        if deducted_amount > 0 and refunded:
            record_shopaikey_billing_event(uid, job_id, "video_refunded", deducted_amount, int(balance_after or 0), int(balance_after_failure or 0), f"shopaikey_video; tier={video_tier}; error={provider_error_text}")
        elif deducted_amount > 0:
            refund_error = "auto_refund_failed"
            record_shopaikey_billing_event(uid, job_id, "video_refund_failed", deducted_amount, int(balance_after or 0), int(balance_after_failure or 0), f"shopaikey_video; tier={video_tier}; provider_error={provider_error_text}; refund_error={refund_error}")
            await alert_public_video_refund_failure(
                context,
                uid,
                job_id,
                video_tier,
                deducted_amount,
                int(balance_before or 0),
                int(balance_after_failure or 0),
                provider_error_text,
                refund_error,
            )
        update_shopaikey_job(
            job_id=job_id,
            status="FAILED",
            error_class=result.get("error_class") or status,
            provider_error_code=result.get("provider_error_code") or "",
            provider_message=provider_error_text,
            attempts=len(attempts),
            finished_at=now_text(),
            refund_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "not_charged"),
            refund_amount=deducted_amount if refunded else 0,
            refund_reason=provider_error_text,
            billing_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "failed_not_charged"),
        )
        return await context.bot.send_message(
            chat_id=query.message.chat_id,
            text=public_video_provider_fail_message(deducted_amount, refunded, lang),
        )
    return await safe_edit_or_send(query, ui_text(lang, "common.invalid_request"))

class TranslationProviderError(RuntimeError):
    def __init__(self, statuses: dict, errors: dict):
        self.statuses = statuses or {}
        self.errors = errors or {}
        super().__init__("; ".join(f"{k}={v}" for k, v in self.errors.items()) or "No translation provider configured")

def provider_error_summary(error) -> str:
    return f"{type(error).__name__}: {sanitize_log_text(str(error))[:500]}"

def is_quota_error_text(text: str) -> bool:
    value = (text or "").lower()
    return any(marker in value for marker in ("resource_exhausted", "quota", "429", "rate limit", "rate_limit"))

def provider_line_status(status: str, detail: str = "") -> str:
    status = str(status or "MISSING").upper()
    detail = (detail or "").strip()
    return status + (f" — {detail[:180]}" if detail else "")

async def translate_with_deepl(text: str, target_lang: str = "vi") -> str:
    if not DEEPL_API_KEY:
        raise RuntimeError("DEEPL_API_KEY missing")
    endpoint = (DEEPL_API_URL or "https://api-free.deepl.com/v2/translate").strip()
    target = normalize_translate_target(target_lang)
    target_code = TRANSLATE_LANGUAGE_OPTIONS.get(target, TRANSLATE_LANGUAGE_OPTIONS["vi"])["deepl"]
    async with httpx.AsyncClient(timeout=30.0) as client:
        res = await client.post(
            endpoint,
            headers={
                "Authorization": f"DeepL-Auth-Key {DEEPL_API_KEY}",
                "Content-Type": "application/json",
            },
            json={
                "text": [text],
                "target_lang": target_code,
            },
        )
    if res.status_code != 200:
        raise RuntimeError(f"DeepL HTTP {res.status_code}: {sanitize_log_text(res.text)[:300]}")
    data = res.json()
    translated = ((data.get("translations") or [{}])[0].get("text") or "").strip()
    if not translated:
        raise RuntimeError("DeepL empty_response")
    return translated

async def translate_with_gemini(text: str, target_lang: str = "vi") -> str:
    if not gemini_client:
        raise RuntimeError("Gemini missing")
    label = translate_target_label(target_lang)
    prompt = (
        f"Translate the following content to natural {label}. "
        "Chỉ trả bản dịch, không giải thích thêm."
    )
    def run_gemini():
        return gemini_client.models.generate_content(
            model="gemini-2.0-flash",
            config=types.GenerateContentConfig(system_instruction=prompt),
            contents=text,
        )
    res = await asyncio.to_thread(run_gemini)
    translated = (getattr(res, "text", "") or "").strip()
    if not translated:
        raise RuntimeError("Gemini empty_response")
    return translated

async def translate_with_openai(text: str, target_lang: str = "vi") -> str:
    if not openai_client:
        raise RuntimeError("OpenAI missing")
    label = translate_target_label(target_lang)
    def run_openai():
        return openai_client.chat.completions.create(
            model=OPENAI_TEXT_MODEL,
            messages=[
                {"role": "system", "content": f"Translate the following text to natural {label}. Return only the translation."},
                {"role": "user", "content": text},
            ],
            max_tokens=800,
        )
    res = await asyncio.to_thread(run_openai)
    translated = (res.choices[0].message.content or "").strip()
    if not translated:
        raise RuntimeError("OpenAI empty_response")
    return translated

async def translate_to_language(text: str, target_lang: str = "vi") -> dict:
    target = normalize_translate_target(target_lang) or "vi"
    statuses = {"deepl": "MISSING", "gemini": "MISSING", "openai": "MISSING"}
    errors = {}
    if DEEPL_API_KEY:
        try:
            return {"provider": "deepl", "text": await translate_with_deepl(text, target), "target": target, "statuses": {**statuses, "deepl": "PASS"}, "errors": errors}
        except Exception as e:
            statuses["deepl"] = "FAIL"
            errors["deepl"] = provider_error_summary(e)
    if gemini_client:
        try:
            return {"provider": "gemini", "text": await translate_with_gemini(text, target), "target": target, "statuses": {**statuses, "gemini": "PASS"}, "errors": errors}
        except Exception as e:
            statuses["gemini"] = "FAIL"
            errors["gemini"] = provider_error_summary(e)
    if openai_client:
        try:
            return {"provider": "openai", "text": await translate_with_openai(text, target), "target": target, "statuses": {**statuses, "openai": "PASS"}, "errors": errors}
        except Exception as e:
            statuses["openai"] = "FAIL"
            errors["openai"] = provider_error_summary(e)
    raise TranslationProviderError(statuses, errors)

async def translate_to_vietnamese(text: str) -> dict:
    return await translate_to_language(text, "vi")

async def cmd_tool_test_translate(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    source_text = "こんにちは、今日は新しい動画を紹介します。"
    deepl_status = "MISSING"
    gemini_status = "MISSING"
    openai_status = "MISSING"
    results = {}
    errors = {}
    if DEEPL_API_KEY:
        try:
            results["deepl"] = await translate_with_deepl(source_text)
            deepl_status = "PASS"
        except Exception as e:
            deepl_status = "FAIL"
            errors["deepl"] = provider_error_summary(e)
    if gemini_client:
        try:
            results["gemini"] = await translate_with_gemini(source_text)
            gemini_status = "PASS"
        except Exception as e:
            gemini_status = "FAIL"
            errors["gemini"] = provider_error_summary(e)
    if openai_client:
        try:
            results["openai"] = await translate_with_openai(source_text)
            openai_status = "PASS"
        except Exception as e:
            openai_status = "FAIL"
            errors["openai"] = provider_error_summary(e)
            logger.warning("OpenAI translation smoke test failed | %s", errors["openai"])
    provider = next((name for name in ("deepl", "gemini", "openai") if results.get(name)), "")
    best_result = results.get(provider, "")
    if provider:
        overall = "PASS" if provider == "deepl" else "PASS_WITH_FALLBACK"
        detail = f"provider={provider}; cost_level=low; result={best_result[:200]}"
    else:
        overall = "FAIL" if any(v == "FAIL" for v in [deepl_status, gemini_status, openai_status]) else "MISSING"
        detail = "; ".join(f"{k}={v}" for k, v in errors.items()) or "No translation provider configured"
    save_tool_test_result("translation", overall, detail, update.effective_user.id)
    save_tool_test_result("translation:deepl", deepl_status, errors.get("deepl") or ("ok" if deepl_status == "PASS" else ""), update.effective_user.id)
    save_tool_test_result("translation:gemini", gemini_status, errors.get("gemini") or ("ok" if gemini_status == "PASS" else ""), update.effective_user.id)
    save_tool_test_result("translation:openai", openai_status, errors.get("openai") or ("ok" if openai_status == "PASS" else ""), update.effective_user.id)
    gemini_note = "quota exhausted, fallback used" if gemini_status == "FAIL" and is_quota_error_text(errors.get("gemini", "")) and provider == "openai" else errors.get("gemini", "")
    await update.message.reply_text(
        "🌐 <b>Translation Smoke Test</b>\n\n"
        f"• DeepL: <code>{html.escape(provider_line_status(deepl_status, errors.get('deepl', '')))}</code>\n"
        f"• Gemini: <code>{html.escape(provider_line_status(gemini_status, gemini_note))}</code>\n"
        f"• OpenAI: <code>{html.escape(provider_line_status(openai_status, errors.get('openai', '')))}</code>\n"
        f"• Overall: <code>{html.escape(overall)}</code>\n"
        f"• Provider used: <code>{html.escape(provider or '-')}</code>\n"
        f"• Best result: <code>{html.escape(best_result[:500] or '-')}</code>"
        + (f"\n• Error: <code>{html.escape(detail[:240])}</code>" if overall == "FAIL" else ""),
        parse_mode="HTML",
    )

async def run_translate_text_to_target(update: Update, context: ContextTypes.DEFAULT_TYPE, source_text: str, target: str):
    uid = update.effective_user.id
    text = str(source_text or "").strip()[:1800]
    if not text:
        return await reply_translation_surface(
            update,
            "⚠️ Gửi nội dung cần dịch, ví dụ:\n/translate en xin chào\n\nBot chưa trừ Xu."
        )
    try:
        result = await translate_to_language(text, target)
        save_tool_test_result("translation", "PASS", f"provider={result.get('provider')}; translate success target={target}", uid)
        return await reply_translation_surface(
            update,
            "🌐 <b>BẢN DỊCH TOAN AAS</b>\n\n"
            f"• Đích: <b>{html.escape(translate_target_label(target))}</b>\n\n"
            f"{html.escape(result.get('text') or '')}",
            parse_mode="HTML",
        )
    except Exception as e:
        error_text = str(e)[:900]
        save_tool_test_result("translation", "FAIL", error_text[:500], uid)
        if is_admin_user(uid):
            return await reply_translation_surface(
                update,
                "❌ Dịch văn bản đang lỗi tạm thời hoặc hết quota provider.\n"
                "Không có Xu nào bị trừ cho lần thử này.\n\n"
                f"• Error: <code>{html.escape(error_text[:240])}</code>",
                parse_mode="HTML",
            )
        return await reply_translation_surface(
            update,
            "❌ Dịch văn bản đang lỗi tạm thời hoặc quá tải.\nBot chưa trừ Xu. Vui lòng thử lại sau."
        )

async def cmd_translate_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    args = context.args or []
    raw_first = str(args[0]).strip() if args else ""
    target = normalize_translate_target(raw_first)
    if target and len(args) >= 2:
        return await run_translate_text_to_target(update, context, " ".join(args[1:]).strip(), target)
    text = " ".join(args).strip()
    if not text:
        return await show_translation_picker(update, "text")
    save_translation_request(update.effective_user.id, "text", source_text=text[:1800])
    return await show_translation_picker(update, "text")

async def cmd_translate(update: Update, context: ContextTypes.DEFAULT_TYPE):
    args = context.args or []
    if not args:
        return await show_translation_picker(update, "text")
    target = normalize_translate_target(args[0])
    if target:
        if len(args) < 2:
            return await update.message.reply_text("⚠️ Thiếu nội dung cần dịch. Ví dụ: /translate en xin chào")
        return await run_translate_text_to_target(update, context, " ".join(args[1:]).strip(), target)
    source_text = " ".join(args).strip()
    save_translation_request(update.effective_user.id, "text", source_text=source_text[:1800])
    return await show_translation_picker(update, "text")

async def cmd_translate_alias(update: Update, context: ContextTypes.DEFAULT_TYPE, target: str):
    context.args = [target] + list(context.args or [])
    return await cmd_translate(update, context)

