async def cmd_promo_debug(update: Update, context: ContextTypes.DEFAULT_TYPE):
    log_command_received("promo_debug", update)
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    if not context.args:
        return await update.message.reply_text("⚠️ Cú pháp: <code>/promo_debug USER_ID</code>", parse_mode="HTML")
    target_id = str(context.args[0]).strip()
    conn = db_connect()
    try:
        pending = get_user_pending_promo(target_id, conn)
        topup_count = user_successful_topup_count(conn, target_id)
        rows = []
        for code in [PROMO_FIRST_TOPUP_CODE, PROMO_SECOND_TOPUP_CODE, PROMO_DAILY_CODE, PROMO_WEEKLY_CODE, PROMO_MONTHLY_CODE]:
            ptype = promo_period_type(code)
            pkey = promo_period_key(code)
            used = promo_period_used(conn, target_id, code, pkey)
            if ptype == "lifetime":
                used = used or count_user_promo_usage(conn, target_id, code) > 0
                reset = "-"
            else:
                reset = next_promo_reset_at(code).strftime("%Y-%m-%d %H:%M:%S")
            rows.append((code, ptype, pkey, used, reset))
    finally:
        conn.commit()
        conn.close()

    pending_line = "không có"
    if pending.get("promo"):
        pending_line = f"{pending['promo']['code']} đến {pending.get('expires_at') or '-'}"
    elif pending.get("code"):
        pending_line = f"{pending.get('code')} ({pending.get('status') or 'invalid'})"

    lines = [
        "🎁 <b>Promo Debug</b>",
        "",
        f"User: <code>{html.escape(target_id)}</code>",
        f"Topup count: <b>{topup_count}</b>",
        f"Pending: <code>{html.escape(pending_line)}</code>",
        "",
    ]
    for code, ptype, pkey, used, reset in rows:
        if ptype == "lifetime":
            state = "used" if used else "available"
            lines.append(f"• <code>{code}</code>: <b>{state}</b> | <code>{pkey}</code>")
        else:
            state = "used current period" if used else "available current period"
            lines.append(f"• <code>{code}</code>: <b>{state}</b> | <code>{pkey}</code> | reset <code>{reset}</code>")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_promo_list(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    conn = db_connect()
    c = conn.cursor()
    try:
        c.execute(
            """SELECT code, status, promo_type, value, bonus_xu, min_amount_vnd, min_amount,
                      usage_count, used_count, usage_limit, max_uses, per_user_limit, max_bonus_xu, note
            FROM promotion_codes
            ORDER BY CASE status WHEN 'active' THEN 0 ELSE 1 END, updated_at DESC, created_at DESC
            LIMIT 20"""
        )
        rows = c.fetchall()
    finally:
        conn.close()
    if not rows:
        return await update.message.reply_text("Chưa có mã khuyến mãi.")
    lines = ["🎁 <b>Promo Codes</b>"]
    for code, status, promo_type, value, bonus_xu, min_amount_vnd, min_amount, usage_count, used_count, usage_limit, max_uses, per_user, max_bonus, note in rows:
        promo = {"promo_type": promo_type, "value": value, "bonus_xu": bonus_xu}
        usage = promo_usage_count({"usage_count": usage_count, "used_count": used_count})
        limit = promo_usage_limit({"usage_limit": usage_limit, "max_uses": max_uses})
        min_vnd = int(min_amount_vnd or min_amount or 0)
        lines.extend([
            "",
            f"<code>{html.escape(str(code))}</code> — <b>{html.escape(str(status or '-'))}</b>",
            f"Type: <b>{html.escape(promo_public_label(promo))}</b>",
            f"Usage: <b>{usage}/{limit if limit else '∞'}</b>",
            f"Per user: <b>{int(per_user or 1)}</b>",
            f"Min: <b>{min_vnd:,}đ</b>",
            f"Max bonus: <b>{int(max_bonus or 0):,} Xu</b>",
            f"Note: {html.escape(str(note or '-'))}",
        ])
    await update.message.reply_text("\n".join(lines[:90]), parse_mode="HTML")

