    if normalize_user_language(lang) == "zh":
        title = "🎞 <b>基于此 concept 的视频 prompt</b>"
        note = ui_text(lang, "video.public_off_prompt_only") if not SHOPAIKEY_PUBLIC_VIDEO_ENABLED else "Public video 已开启时仍需走档位/确认/退款 guard。"
