async def send_pricing_lines(message, lines: list[str], reply_markup: InlineKeyboardMarkup | None = None, limit: int = 3600):
    chunk: list[str] = []
    current_len = 0
    for line in lines:
        line = str(line)
        add_len = len(line) + 1
        if chunk and current_len + add_len > limit:
            await message.reply_text("\n".join(chunk), parse_mode="HTML")
            chunk = []
            current_len = 0
        chunk.append(line)
        current_len += add_len
    if chunk:
        await message.reply_text("\n".join(chunk), parse_mode="HTML", reply_markup=reply_markup)

def chunk_pricing_lines(lines: list[str], limit: int = 3600) -> list[str]:
    chunks: list[str] = []
    chunk: list[str] = []
    current_len = 0
    for line in lines:
        line = str(line)
        add_len = len(line) + 1
        if chunk and current_len + add_len > limit:
            chunks.append("\n".join(chunk))
            chunk = []
            current_len = 0
        chunk.append(line)
        current_len += add_len
    if chunk:
        chunks.append("\n".join(chunk))
    return chunks

async def edit_or_send_pricing_lines(query, lines: list[str], reply_markup: InlineKeyboardMarkup | None = None, limit: int = 3600):
    chunks = chunk_pricing_lines(lines, limit=limit)
    if not chunks:
        return
    if len(chunks) == 1:
        return await safe_edit_or_send(query, chunks[0], parse_mode="HTML", reply_markup=reply_markup)
    await safe_edit_or_send(query, chunks[0], parse_mode="HTML")
    for idx, chunk in enumerate(chunks[1:], 1):
        await query.message.reply_text(
            chunk,
            parse_mode="HTML",
            reply_markup=reply_markup if idx == len(chunks) - 1 else None,
        )

