def parse_key_value_args(raw: str) -> dict:
    data = {}
    current_key = None
    for token in raw.split():
        if "=" in token:
            key, value = token.split("=", 1)
            current_key = key.strip().lower()
            data[current_key] = value.strip()
        elif current_key:
            data[current_key] += " " + token.strip()
    return data

def int_from_text(text, keys, default=0):
    for key in keys:
        match = re.search(rf"(?:{re.escape(key)}|{re.escape(key)}=)\s*#?(\d+)", text, re.IGNORECASE)
        if match:
            return int(match.group(1))
    return default

def safe_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

def truthy_value(value, default=False):
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "on", "co", "có", "run", "execute", "chay", "chạy"}:
        return True
    if text in {"0", "false", "no", "off", "khong", "không"}:
        return False
    return default

