def truncate_text(text: str, limit: int = 3500) -> str:
    return text if len(text) <= limit else text[: limit - 20] + "\n...[đã rút gọn]"

def html_pre(text: str, limit: int = 3500) -> str:
    return html.escape(truncate_text(text, limit))

