    include_references = (data.get("references") or data.get("ref") or "1").lower() not in {"0", "false", "no", "off", "khong"}
    try:
        reference_limit = max(1, min(int(data.get("reference_limit") or data.get("limit") or 200), 1000))
    except ValueError:
        reference_limit = 200
