async def cmd_operator_contract(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if str(update.effective_user.id) != ADMIN_ID:
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        days = max(1, min(int(data.get("days") or data.get("ngay") or 30), 180))
    except ValueError:
        days = 30
    try:
        limit = max(3, min(int(data.get("limit") or 8), 20))
    except ValueError:
        limit = 8
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    contract = operator_control_contract_data(update.effective_user.id, days=days, platform=platform, limit=limit)
    state = contract.get("state") or {}
    next_step = contract.get("next") or {}
    lines = [
        "📜 <b>OPERATOR CONTROL CONTRACT</b>",
        f"• Platform: <code>{html.escape(platform)}</code> | Days: <b>{days}</b>",
        f"• Audit: <code>{html.escape(str(state.get('audit_level') or '-'))}</code> score=<b>{state.get('audit_score', 0)}</b>",
        f"• Next: <b>{html.escape(str(state.get('next_mode') or '-'))}</b> — {html.escape(str(state.get('next_title') or '-'))}",
        f"• Publisher: <code>{html.escape(str(state.get('publisher_overall') or '-'))}</code> | queue=<b>{state.get('open_queue', 0)}</b>",
        "",
        "<b>Quyền điều khiển:</b>",
    ]
    for item in contract.get("command_hierarchy") or []:
        lines.append(f"• {item.get('rank')}. <code>{html.escape(item.get('actor') or '-')}</code>: {html.escape(item.get('authority') or '-')}")
    lines.append("\n<b>Vòng đời chuẩn:</b>")
    for item in (contract.get("lifecycle") or [])[:7]:
        lines.append(
            f"• <b>{html.escape(item.get('phase') or '-')}</b> | owner=<code>{html.escape(item.get('owner') or '-')}</code>\n"
            f"  TG: <code>{html.escape(item.get('telegram') or '-')}</code>\n"
            f"  API: <code>{html.escape(item.get('api') or '-')}</code>"
        )
    lines.append("\n<b>Cấm vượt gate:</b>")
    for rule in (contract.get("non_negotiable_gates") or [])[:6]:
        lines.append(f"• {html.escape(rule)}")
    lines.append(
        "\n<b>Bước tiếp theo:</b>\n"
        f"• TG: <code>{html.escape(str(next_step.get('telegram') or '/operator_next_run'))}</code>\n"
        f"• API: <code>{html.escape(str((next_step.get('api') or {}).get('url') or '/api/operator/next-run'))}</code>\n"
        "API đầy đủ: <code>GET /api/operator/control-contract?days=30&amp;platform=tiktok</code>"
    )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_goal_audit(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if str(update.effective_user.id) != ADMIN_ID:
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        days = max(1, min(int(data.get("days") or data.get("ngay") or 30), 180))
    except ValueError:
        days = 30
    try:
        limit = max(3, min(int(data.get("limit") or 8), 30))
    except ValueError:
        limit = 8
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    audit = operator_goal_audit_data(update.effective_user.id, days=days, platform=platform, limit=limit)
    counts = audit.get("counts") or {}
    lines = [
        "🎯 <b>TOAN AAS GOAL AUDIT</b>",
        f"• Level: <code>{html.escape(audit.get('level') or '-')}</code> | Score: <b>{audit.get('score', 0)}%</b>",
        f"• Platform: <code>{html.escape(platform)}</code> | Days: <b>{days}</b>",
        f"• Jobs: <b>{counts.get('recent_jobs', 0)}</b> | Tasks: <b>{counts.get('total_tasks', 0)}</b> | Final assets: <b>{counts.get('final_assets', 0)}</b>",
        f"• Queue open: <b>{counts.get('open_publish_queue', 0)}</b> | Published: <b>{counts.get('published_queue', 0)}</b>",
        f"• Performance: <b>{counts.get('performance_events', 0)}</b> events | <b>{int(counts.get('performance_amount_vnd') or 0):,}đ</b>",
        "",
        "<b>Checklist mục tiêu:</b>",
    ]
    for item in (audit.get("requirements") or [])[:12]:
        marker = "✅" if item.get("ok") else ("⚠️" if item.get("soft") else "❌")
        lines.append(
            f"{marker} <code>{html.escape(item.get('phase') or '-')}</code> — "
            f"{html.escape(item.get('key') or '-')}: {html.escape(item.get('detail') or '-')}"
        )
    if audit.get("hard_blockers"):
        lines.append("\n<b>Hard blocker cần xử lý trước:</b>")
        for item in (audit.get("hard_blockers") or [])[:5]:
            lines.append(f"• {html.escape(item.get('key') or '-')}: <code>{html.escape(item.get('next') or '-')}</code>")
    if audit.get("soft_blockers"):
        lines.append("\n<b>Soft blocker cần test/live run:</b>")
        for item in (audit.get("soft_blockers") or [])[:5]:
            lines.append(f"• {html.escape(item.get('key') or '-')}: <code>{html.escape(item.get('next') or '-')}</code>")
    next_run = audit.get("next_run") or {}
    lines.append(
        "\n<b>Bước tiếp theo:</b>\n"
        f"• <code>{html.escape(audit.get('next_command') or next_run.get('telegram') or '/operator_next_run')}</code>\n"
        f"• API: <code>GET /api/operator/goal-audit?days={days}&amp;platform={html.escape(platform)}&amp;limit={limit}</code>"
    )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_head_brain(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if str(update.effective_user.id) != ADMIN_ID:
        return
    data = parse_key_value_args(" ".join(context.args))
    days = max(1, min(safe_int(data.get("days") or data.get("ngay"), 30), 180))
    limit = max(3, min(safe_int(data.get("limit"), 8), 30))
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    cockpit = operator_head_brain_cockpit_data(update.effective_user.id, days=days, platform=platform, limit=limit)
    admin_next = cockpit.get("admin_next") or {}
    claude_next = cockpit.get("claude_next") or {}
    live = cockpit.get("live_state") or {}
    publish = live.get("publish") or {}
    money = live.get("money") or {}
    lines = [
        "🧠 <b>HEAD BRAIN COCKPIT</b>",
        f"• Level: <code>{html.escape(cockpit.get('level') or '-')}</code> | Score: <b>{cockpit.get('score', 0)}%</b>",
        f"• Decision: <b>{html.escape(cockpit.get('decision') or '-')}</b>",
        f"• Mission: {html.escape(cockpit.get('mission') or '-')}",
        "",
        "<b>Admin làm ngay:</b>",
        f"• <code>{html.escape(admin_next.get('command') or '/operator_next_run')}</code>",
        f"• Lý do: {html.escape(admin_next.get('reason') or '-')}",
        "",
        "<b>Claude/n8n đọc và chạy:</b>",
        f"• Read: <code>{html.escape(claude_next.get('read') or '-')}</code>",
        f"• Start: <code>{html.escape(claude_next.get('start') or '-')}</code>",
        f"• Safe execute: <b>{'YES' if claude_next.get('safe_execute') else 'NO'}</b>",
        "",
        "<b>Pipeline lanes:</b>",
    ]
    for lane in cockpit.get("lanes") or []:
        icon = "✅" if lane.get("ok") else "⚠️"
        lines.append(
            f"{icon} <code>{html.escape(lane.get('phase') or '-')}</code> — {html.escape(lane.get('title') or '-')}\n"
            f"  next: <code>{html.escape(lane.get('command') or '-')}</code>"
        )
    lines.extend([
        "",
        "<b>Trạng thái sống:</b>",
        f"• Publish: <code>{html.escape(str(publish.get('overall') or '-'))}</code> | {html.escape(str(publish.get('summary') or {}))[:180]}",
        f"• Money: <code>{html.escape(str(money))[:220]}</code>",
        "",
        "<b>Lệnh lõi:</b>",
    ])
    commands = cockpit.get("operator_commands") or {}
    for key in ["start_batch", "claim_worker", "review", "approve", "publish", "track", "scale"]:
        if commands.get(key):
            lines.append(f"• {key}: <code>{html.escape(commands[key])}</code>")
    lines.append(
        "\nAPI: <code>GET /api/operator/head-brain?days=30&amp;platform=tiktok&amp;limit=8</code>\n"
        "Rule: không tự publish ngoài review/approve gate; sau đăng bắt buộc ghi performance."
    )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_head_run(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if str(update.effective_user.id) != ADMIN_ID:
        return
    data = parse_key_value_args(" ".join(context.args))
    days = max(1, min(safe_int(data.get("days") or data.get("ngay"), 1), 30))
    limit = max(3, min(safe_int(data.get("limit"), 8), 20))
    max_steps = max(1, min(safe_int(data.get("max") or data.get("max_steps") or data.get("steps"), 1), 5))
    platform = (data.get("platform") or data.get("nen") or "tiktok").lower()
    topic = data.get("topic") or data.get("niche") or data.get("chude") or ""
    execute = truthy_value(data.get("execute") or data.get("run"), False)
    safe_mode = truthy_value(data.get("safe") or data.get("safe_mode"), True)
    send_review = truthy_value(data.get("review") or data.get("send_review"), True)
    include_growth = truthy_value(data.get("include_growth") or data.get("growth"), True)
    execute_growth = execute and truthy_value(data.get("growth"), False)
    result = await operator_head_brain_run_data(
        update.effective_user.id,
        days=days,
        platform=platform,
        limit=limit,
        topic=topic,
        execute=execute,
        safe_mode=safe_mode,
        max_steps=max_steps,
        include_growth=include_growth,
        execute_growth=execute_growth,
        include_context=True,
        include_prompt=True,
    )
    before = result.get("before") or {}
    after = result.get("after") or {}
    cycle = result.get("cycle") or {}
    lines = [
        "▶️ <b>HEAD BRAIN RUN</b>",
        f"• Mode: <b>{html.escape(result.get('mode') or '-')}</b> | Safe: <b>{'YES' if result.get('safe_mode') else 'NO'}</b>",
        f"• Platform: <code>{html.escape(platform)}</code> | Steps: <b>{len(cycle.get('steps') or [])}</b>/<b>{max_steps}</b>",
        f"• Before: <code>{html.escape(before.get('level') or '-')}</code> / <code>{html.escape(before.get('decision') or '-')}</code>",
        f"• After: <code>{html.escape(after.get('level') or '-')}</code> / <code>{html.escape(after.get('decision') or '-')}</code>",
        f"• Executed: <b>{result.get('executed_count', 0)}</b> | Stop: <code>{html.escape(result.get('stop_reason') or '-')}</code>",
        "",
        "<b>Các bước:</b>",
    ]
    for step in (cycle.get("steps") or [])[:5]:
        action = step.get("machine_action") or step.get("action") or {}
        step_result = step.get("result") or {}
        lines.append(
            f"• #{step.get('cycle_step') or step.get('step') or '-'} "
            f"<code>{html.escape(step.get('lane') or (action.get('kind') or '-'))}</code> "
            f"executed=<b>{'YES' if step.get('executed') else 'NO'}</b>\n"
            f"  {html.escape(step.get('message') or step_result.get('message') or step.get('stop_reason') or action.get('reason') or '-')}"
        )
    if result.get("claimed_tasks"):
        lines.append("\n<b>Task đã claim:</b>")
        for task in result.get("claimed_tasks")[:5]:
            lines.append(f"• task #{task.get('task_id')} | job #{task.get('job_id')} | {html.escape(task.get('task_type') or '-')}")
    if result.get("created_jobs"):
        lines.append("\n<b>Job tạo mới:</b>")
        for job in result.get("created_jobs")[:5]:
            lines.append(f"• job #{job.get('job_id')} | <code>{html.escape(job.get('platform') or '-')}</code> | {html.escape(job.get('title') or job.get('topic') or '-')}")
    growth = result.get("growth_loop") or {}
    selected_growth = growth.get("selected_action") or {}
    if selected_growth:
        growth_result = growth.get("result") or {}
        lines.append("\n<b>Growth loop:</b>")
        lines.append(
            f"• Selected: <code>{html.escape(selected_growth.get('kind') or '-')}</code> | "
            f"execute=<b>{'YES' if growth.get('execute') else 'preview'}</b>\n"
            f"• Reason: {html.escape(selected_growth.get('reason') or '-')}\n"
            f"• Next: <code>{html.escape(selected_growth.get('telegram') or '-')}</code>\n"
            f"• Result: <code>{html.escape(growth_result.get('reason') or '-')}</code>"
        )
    handoff = result.get("worker_handoff") or {}
    video_orders = (handoff.get("video_work_orders") or {}).get("orders") or []
    if video_orders:
        first_order = video_orders[0]
        first_order_tg = first_order.get("telegram") or {}
        first_job_id = first_order.get("job_id")
        first_brief_cmd = first_order_tg.get("video_brief") or f"/video_brief job={first_job_id}"
        first_compose_cmd = first_order_tg.get("compose_video") or f"/compose_video job={first_job_id} voice=1"
        lines.append("\n<b>Giao việc cho Claude/n8n:</b>")
        lines.append(f"• Work-orders: <b>{len(video_orders)}</b> | <code>{html.escape((result.get('next') or {}).get('video_work_orders') or '/video_work_orders')}</code>")
        lines.append(f"• First brief: <code>{html.escape(first_brief_cmd)}</code>")
        lines.append(f"• First compose: <code>{html.escape(first_compose_cmd)}</code>")
    reviewable_jobs = operator_review_job_ids_from_result(update.effective_user.id, result, limit=3)
    if execute and send_review and reviewable_jobs:
        lines.append(
            "\n<b>Video đã render cần duyệt:</b> "
            + ", ".join(f"<code>#{jid}</code>" for jid in reviewable_jobs)
            + "\nBot sẽ gửi video + caption/link affiliate ngay sau tin này."
        )
    next_cmds = result.get("next") or {}
    lines.append(
        "\n<b>Lệnh tiếp:</b>\n"
        f"• Head: <code>{html.escape(next_cmds.get('head_brain') or '/head_brain')}</code>\n"
        f"• Worker: <code>{html.escape(next_cmds.get('worker') or '/worker_intake')}</code>\n"
        f"• Orders: <code>{html.escape(next_cmds.get('video_work_orders') or '/video_work_orders')}</code>\n"
        f"• Publish: <code>{html.escape(next_cmds.get('publish') or '/publish_cockpit')}</code>\n"
        f"• Growth: <code>{html.escape(next_cmds.get('growth_loop') or '/growth_loop')}</code>\n"
        "API: <code>POST /api/operator/head-run</code>"
    )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")
    if execute and send_review and reviewable_jobs:
        review_report = await send_operator_review_packets(
            context,
            update.effective_chat.id,
            update.effective_user.id,
            result,
            limit=3,
        )
        if review_report.get("errors"):
            await update.message.reply_text(
                "⚠️ Một số review packet gửi lỗi: "
                + html.escape(str(review_report.get("errors")[:3])),
                parse_mode="HTML",
            )

