async def cmd_performance_add(update: Update, context: ContextTypes.DEFAULT_TYPE):
    raw = " ".join(context.args).strip()
    if str(update.effective_user.id) != ADMIN_ID:
        return await cmd_performance_add_manual(update, context, raw)
    data = parse_key_value_args(raw)
    if data.get("post_id") or data.get("post"):
        return await cmd_performance_add_manual(update, context, raw)
    try:
        job_id = int(data.get("id") or data.get("job") or context.args[0])
    except (IndexError, TypeError, ValueError):
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/performance_add job=1 variant=2 type=view value=1000 amount=0 note=tiktok ngay 1</code>\n"
            "Type: <code>view, click, order, revenue, lead</code>",
            parse_mode="HTML"
        )
    event_type = (data.get("type") or data.get("event") or "view").lower()
    allowed = {"view", "click", "order", "revenue", "lead", "cost"}
    if event_type not in allowed:
        return await update.message.reply_text(f"⚠️ type hợp lệ: <code>{', '.join(sorted(allowed))}</code>", parse_mode="HTML")
    try:
        value = int(data.get("value") or data.get("count") or 0)
    except ValueError:
        value = 0
    try:
        amount = int(data.get("amount") or data.get("money") or data.get("vnd") or 0)
    except ValueError:
        amount = 0
    try:
        variant_id = int(data.get("variant") or data.get("variant_id") or 0)
    except ValueError:
        variant_id = 0
    source = data.get("source") or data.get("src") or ""
    note = format_tracking_note(source, data.get("note") or "") if source else (data.get("note") or "")
    ok, job = add_performance_event(update.effective_user.id, job_id, event_type, value, amount, note, variant_id)
    if not ok:
        return await update.message.reply_text("❌ Không tìm thấy production job hoặc creative variant.")
    if event_type in {"revenue", "order", "lead"} and amount > 0:
        update_production_job(job_id, update.effective_user.id, status="published")
    await update.message.reply_text(
        f"✅ <b>Đã ghi hiệu quả job #{job_id}</b>\n"
        f"• Type: <code>{html.escape(event_type)}</code>\n"
        f"• Variant: <code>{variant_id or 'không gắn'}</code>\n"
        f"• Value: <b>{value}</b>\n"
        f"• Amount: <b>{amount:,}đ</b>\n"
        f"• Note: {html.escape(note or '-')}",
        parse_mode="HTML"
    )

async def cmd_mark_published(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if str(update.effective_user.id) != ADMIN_ID:
        return
    data = parse_key_value_args(" ".join(context.args))
    try:
        job_id = int(data.get("id") or data.get("job") or context.args[0])
    except (IndexError, TypeError, ValueError):
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/mark_published job=1 url=https://... views=0 clicks=0 note=...</code>",
            parse_mode="HTML"
        )
    publish_url = data.get("url") or data.get("publish") or ""
    note = data.get("note") or "manual_publish"
    try:
        views = int(data.get("views") or data.get("view") or 0)
    except ValueError:
        views = 0
    try:
        clicks = int(data.get("clicks") or data.get("click") or 0)
    except ValueError:
        clicks = 0
    if not get_production_job(job_id, update.effective_user.id):
        return await update.message.reply_text("❌ Không tìm thấy production job.")
    update_production_job(
        job_id,
        update.effective_user.id,
        stage="done",
        status="published",
        note=note,
        publish_url=publish_url
    )
    source = data.get("source") or data.get("src") or note or "manual_publish"
    add_performance_event(update.effective_user.id, job_id, "publish", 1, 0, format_tracking_note(source, "publish"))
    if views > 0:
        add_performance_event(update.effective_user.id, job_id, "view", views, 0, format_tracking_note(source, "initial_views"))
    if clicks > 0:
        add_performance_event(update.effective_user.id, job_id, "click", clicks, 0, format_tracking_note(source, "initial_clicks"))
    await update.message.reply_text(
        f"✅ <b>Đã ghi nhận job #{job_id} đã đăng</b>\n"
        f"• Publish URL: <code>{html.escape(publish_url or 'chưa nhập')}</code>\n"
        f"• Views ban đầu: <b>{views}</b>\n"
        f"• Clicks ban đầu: <b>{clicks}</b>\n"
        f"• Note: {html.escape(note)}\n\n"
        f"Cập nhật doanh thu sau: <code>/performance_add job={job_id} type=revenue value=1 amount=...</code>",
        parse_mode="HTML"
    )

async def cmd_publish_done(update: Update, context: ContextTypes.DEFAULT_TYPE):
    raw = " ".join(context.args).strip()
    if str(update.effective_user.id) != ADMIN_ID:
        return await cmd_publish_done_manual(update, context, raw)
    data = parse_key_value_args(raw)
    try:
        queue_id = int(data.get("queue") or data.get("qid") or data.get("id") or 0)
    except ValueError:
        queue_id = 0
    try:
        job_id = int(data.get("job") or data.get("job_id") or (context.args[0] if context.args else 0) or 0)
    except (TypeError, ValueError):
        job_id = 0
    if not queue_id and not job_id:
        return await cmd_publish_done_manual(update, context, raw)
    result = complete_publish_tracking(
        update.effective_user.id,
        job_id=job_id,
        queue_id=queue_id,
        status=data.get("status") or "published",
        publish_url=data.get("url") or data.get("publish_url") or data.get("publish") or "",
        note=data.get("note") or "manual_publish_done",
        source=data.get("source") or data.get("src") or "manual_publish_done",
        views=safe_int(data.get("views") or data.get("view"), 0),
        clicks=safe_int(data.get("clicks") or data.get("click"), 0),
        leads=safe_int(data.get("leads") or data.get("lead"), 0),
        orders=safe_int(data.get("orders") or data.get("order") or data.get("don"), 0),
        revenue=safe_int(data.get("revenue") or data.get("amount") or data.get("money") or data.get("vnd"), 0),
        cost=safe_int(data.get("cost") or data.get("chiphi") or data.get("chi_phi"), 0),
        affiliate_id=safe_int(data.get("aff") or data.get("affiliate") or data.get("affiliate_id"), 0),
    )
    ok, reason, info = result
    if not ok:
        return await update.message.reply_text(f"❌ Không ghi được publish_done: <code>{html.escape(reason)}</code>", parse_mode="HTML")
    events = info.get("recorded_events") or []
    event_text = "\n".join(
        f"• {html.escape(e.get('type') or '-')}: value=<b>{int(e.get('value') or 0)}</b> amount=<b>{int(e.get('amount') or 0):,}đ</b>"
        for e in events
    ) or "• Chưa có metric mới."
    pp = info.get("post_publish") or {}
    recommendation = pp.get("recommendation") or "Chạy /tracking_report rồi /scale_plan khi đủ dữ liệu."
    await update.message.reply_text(
        f"✅ <b>PUBLISH DONE</b>\n\n"
        f"• Queue: <code>#{queue_id or '-'}</code> | Job: <code>#{info.get('job_id') or job_id}</code>\n"
        f"• Status: <b>{html.escape(info.get('status') or 'published')}</b>\n"
        f"• URL: <code>{html.escape(info.get('publish_url') or data.get('url') or 'chưa nhập')}</code>\n\n"
        f"<b>Đã ghi:</b>\n{event_text}\n\n"
        f"<b>AI đề xuất:</b> {html.escape(recommendation)}\n"
        f"• Xem funnel: <code>/tracking_report days=30</code>\n"
        f"• Quyết định scale: <code>/affiliate_decisions days=30</code>",
        parse_mode="HTML",
    )

