    for item in comment_items[:5]:
        lines.append(
            f"• #{item.get('order')}: <code>{html.escape(item.get('tracking_source') or '-')}</code> "
            f"{html.escape(item.get('product') or '-')}\n"
            f"<pre>{html_pre(item.get('text') or item.get('url') or '-', 360)}</pre>"
        )
