async def cmd_tuchoi(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    try:
        lookup_key = context.args[0]
        conn = db_connect()
        c = conn.cursor()
        pending = None
        if str(lookup_key).isdigit():
            c.execute(
                "SELECT id, user_id FROM pending_deposits WHERE id=? AND status='pending' LIMIT 1",
                (str(lookup_key),),
            )
            pending = c.fetchone()
        if not pending:
            c.execute(
                "SELECT id, user_id FROM pending_deposits WHERE user_id=? AND status='pending' ORDER BY submitted_at DESC LIMIT 1",
                (str(lookup_key),),
            )
            pending = c.fetchone()
        if not pending:
            conn.close()
            return await update.message.reply_text(
                "⚠️ Không có bill thủ công đang chờ cho ID/mã bill này.",
                parse_mode="HTML",
            )
        deposit_id = int(pending[0])
        target_id = str(pending[1])
        c.execute(
            "UPDATE pending_deposits SET status='rejected' WHERE id=? AND status='pending'",
            (deposit_id,)
        )
        rejected_count = c.rowcount
        record_audit(
            conn,
            ADMIN_ID,
            "admin",
            "bill.rejected",
            "pending_deposit",
            str(deposit_id),
            before={"status": "pending", "user_id": str(target_id)},
            after={"status": "rejected", "rows": int(rejected_count or 0), "user_id": str(target_id)},
            note="Admin rejected manual bill",
        )
        conn.commit()
        conn.close()
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"❌ <b>BILL BỊ TỪ CHỐI</b>\n\n"
                f"Admin không xác nhận được giao dịch.\n"
                f"Kiểm tra lại nội dung chuyển khoản hoặc liên hệ Admin."
            ),
            parse_mode="HTML"
        )
        await update.message.reply_text(f"✅ Đã từ chối bill #{deposit_id} và thông báo ID: {target_id}")
    except IndexError:
        await update.message.reply_text("⚠️ Cú pháp: /tuchoi <deposit_id|user_id>")

async def cmd_pending(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        "SELECT id, user_id, username, submitted_at, order_code, amount, xu FROM pending_deposits "
        "WHERE status='pending' ORDER BY submitted_at DESC LIMIT 10"
    )
    rows = c.fetchall()
    conn.close()
    if not rows:
        return await update.message.reply_text("📭 Không có bill nào đang chờ.")
    lines = ["📋 <b>BILL CHỜ DUYỆT (THỦ CÔNG):</b>\n"]
    for r in rows:
        expected = f" | {r[5]:,}đ → {r[6]} Xu | đơn {r[4]}" if r[5] and r[6] else ""
        lines.append(
            f"• #{r[0]} | {r[2]} | <code>{r[1]}</code>{expected} | {r[3]}\n"
            f"  ➔ <code>/duyet {r[0]} {r[6] or '&lt;Xu&gt;'}</code>\n"
            f"  ➔ <code>/tuchoi {r[0]}</code>"
        )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_stats(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT COUNT(*) FROM users")
    total_users = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM transactions WHERE created_at >= ?",
              ((datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d %H:%M:%S"),))
    tx_today = c.fetchone()[0]
    c.execute("SELECT SUM(cost) FROM transactions WHERE created_at >= ?",
              ((datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d %H:%M:%S"),))
    revenue_today = c.fetchone()[0] or 0
    c.execute("SELECT COUNT(*) FROM pending_deposits WHERE status='pending'")
    pending = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM payos_processed")
    payos_auto = c.fetchone()[0]
    conn.close()
    await update.message.reply_text(
        f"📊 <b>THỐNG KÊ HỆ THỐNG</b>\n\n"
        f"👥 Tổng user: <b>{total_users}</b>\n"
        f"⚡ Giao dịch hôm nay: <b>{tx_today}</b>\n"
        f"💰 Xu tiêu hôm nay: <b>{revenue_today}</b>\n"
        f"📋 Bill chờ duyệt (thủ công): <b>{pending}</b>\n"
        f"🤖 Nạp tự động PayOS QR Động: <b>{payos_auto}</b>",
        parse_mode="HTML"
    )

async def cmd_dashboard(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    today = datetime.now().strftime("%Y-%m-%d")
    month_prefix = datetime.now().strftime("%Y-%m")
    conn = db_connect()
    c = conn.cursor()
    c.execute("SELECT COUNT(*) FROM users")
    total_users = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM users WHERE join_date >= ?", (today,))
    new_today = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM users WHERE has_deposited=1")
    deposited_users = c.fetchone()[0]
    c.execute("SELECT COALESCE(SUM(credits),0) FROM users")
    circulating_credits = c.fetchone()[0] or 0
    c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0), COALESCE(SUM(xu),0) FROM payos_orders WHERE status=? AND DATE(paid_at)=?", (PAYOS_STATUS_PAID, today))
    paid_today_count, revenue_today_vnd, xu_sold_today = c.fetchone()
    c.execute("SELECT COALESCE(SUM(amount),0), COALESCE(SUM(xu),0) FROM payos_orders WHERE status=? AND paid_at LIKE ?", (PAYOS_STATUS_PAID, f"{month_prefix}%"))
    revenue_month_vnd, xu_sold_month = c.fetchone()
    c.execute("SELECT COALESCE(SUM(-delta),0) FROM credit_events WHERE delta < 0 AND created_at LIKE ?", (f"{month_prefix}%",))
    xu_spent_month = c.fetchone()[0] or 0
    c.execute("SELECT COUNT(*), COALESCE(SUM(delta),0) FROM credit_events WHERE event_type='referral_reward'")
    referral_rewards, referral_bonus_total = c.fetchone()
    c.execute("SELECT user_id, username, credits, total_spent, is_vip FROM users ORDER BY CAST(credits AS INTEGER) DESC LIMIT 8")
    top_users = c.fetchall()
    c.execute("SELECT order_code, user_id, amount, xu, status, created_at FROM payos_orders ORDER BY created_at DESC LIMIT 8")
    recent_orders = c.fetchall()
    c.execute("SELECT user_id, delta, balance_after, event_type, created_at FROM credit_events ORDER BY id DESC LIMIT 8")
    recent_credit = c.fetchall()
    c.execute("SELECT COUNT(*), COALESCE(SUM(amount),0) FROM payos_orders WHERE status=?", (PAYOS_STATUS_PAID,))
    paid_count, paid_amount = c.fetchone()
    c.execute("SELECT COUNT(*) FROM pending_deposits WHERE status='pending'")
    pending_count = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM leads")
    lead_count = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM feedback WHERE timestamp >= ?", ((datetime.now() - timedelta(days=7)).strftime("%Y-%m-%d %H:%M:%S"),))
    feedback_7d = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM audit_logs WHERE created_at >= ?", ((datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d %H:%M:%S"),))
    audit_24h = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM affiliate_links WHERE status='active'")
    affiliate_active = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM affiliate_links WHERE created_at LIKE ?", (f"{today}%",))
    affiliate_today = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM campaigns WHERE status='active'")
    active_campaigns = c.fetchone()[0]
    c.execute(
        "SELECT COUNT(*) FROM content_calendar WHERE post_date BETWEEN ? AND ?",
        (today, (datetime.now().date() + timedelta(days=6)).isoformat())
    )
    calendar_7d = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM video_script_jobs WHERE created_at LIKE ?", (f"{today}%",))
    video_scripts_today = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM published_posts WHERE created_at LIKE ?", (f"{today}%",))
    manual_posts_today = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM manual_performance_events WHERE created_at LIKE ?", (f"{today}%",))
    manual_perf_today = c.fetchone()[0]
    c.execute("SELECT COALESCE(SUM(revenue),0) FROM manual_performance_events WHERE created_at LIKE ?", (f"{today}%",))
    manual_revenue_today = c.fetchone()[0] or 0
    c.execute("SELECT COALESCE(SUM(revenue),0) FROM manual_performance_events WHERE created_at LIKE ?", (f"{month_prefix}%",))
    manual_revenue_month = c.fetchone()[0] or 0
    c.execute("SELECT COUNT(*) FROM growth_recommendations WHERE recommendation_type='ai_growth_coach' AND created_at LIKE ?", (f"{month_prefix}%",))
    growth_ai_month = c.fetchone()[0] or 0
    conn.close()

    lines = [
        f"📊 <b>TOAN AAS — BÁO CÁO HÔM NAY</b>",
        f"🗓 <code>{today}</code> | Uptime: <b>{int(time.time() - START_TIME) // 3600}h {(int(time.time() - START_TIME) % 3600) // 60}m</b>",
        "",
        f"👥 <b>Users:</b> tổng <b>{total_users}</b> | mới hôm nay <b>+{new_today}</b> | đã nạp <b>{deposited_users}</b>",
        f"💰 <b>Doanh thu hôm nay:</b> <b>{revenue_today_vnd:,}đ</b> ({paid_today_count} giao dịch)",
        f"💰 <b>Doanh thu tháng:</b> <b>{revenue_month_vnd:,}đ</b> / tổng PayOS <b>{paid_amount:,}đ</b>",
        f"🪙 <b>Xu:</b> lưu hành <b>{circulating_credits:,}</b> | bán tháng <b>{xu_sold_month:,}</b> | dùng tháng <b>{xu_spent_month:,}</b>",
        f"🎁 <b>Referral:</b> thưởng <b>{referral_rewards}</b> lượt / <b>{referral_bonus_total or 0} Xu</b>",
        f"🎬 <b>Video/Affiliate:</b> script hôm nay <b>{video_scripts_today}</b> | campaign active <b>{active_campaigns}</b> | link active <b>{affiliate_active}</b> (+{affiliate_today} hôm nay) | lịch 7 ngày <b>{calendar_7d}</b>",
        f"📈 <b>Publish tracking:</b> bài hôm nay <b>{manual_posts_today}</b> | nhập số liệu <b>{manual_perf_today}</b> | revenue tay hôm nay <b>{manual_revenue_today:,.0f}đ</b> | tháng <b>{manual_revenue_month:,.0f}đ</b>",
        f"🧠 <b>AI Growth:</b> report AI tháng này <b>{growth_ai_month}</b>",
        f"📋 <b>Cần chú ý:</b> bill chờ <b>{pending_count}</b> | lead <b>{lead_count}</b> | góp ý 7 ngày <b>{feedback_7d}</b> | audit 24h <b>{audit_24h}</b>",
        "",
        "<b>Lệnh nhanh:</b> /pending | /backup_db | /health | /naptien",
        "",
        "<b>Top user theo số dư:</b>",
    ]
    for user_id, username, credits, total_spent, is_vip in top_users:
        vip = " VIP" if is_vip else ""
        lines.append(f"• {username or 'Unknown'} <code>{user_id}</code>: {credits} Xu, chi {total_spent}{vip}")

    lines.append("\n<b>Đơn PayOS gần nhất:</b>")
    for order_code, user_id, amount, xu, status, created_at in recent_orders:
        lines.append(f"• <code>{order_code}</code> | {user_id} | {amount:,}đ → {xu} Xu | {status}")

    lines.append("\n<b>Biến động xu gần nhất:</b>")
    for user_id, delta, balance_after, event_type, created_at in recent_credit:
        lines.append(f"• {created_at} | {user_id} | {delta:+} Xu | còn {balance_after} | {event_type}")

    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_setvip(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    try:
        target_id = context.args[0]
        flag = int(context.args[1])
        conn = db_connect()
        c = conn.cursor()
        c.execute("SELECT is_vip FROM users WHERE user_id=?", (str(target_id),))
        before_row = c.fetchone()
        before_vip = before_row[0] if before_row else None
        c.execute("UPDATE users SET is_vip=? WHERE user_id=?", (flag, str(target_id)))
        record_audit(
            conn,
            ADMIN_ID,
            "admin",
            "user.vip_updated",
            "user",
            str(target_id),
            before={"is_vip": before_vip},
            after={"is_vip": flag},
            note="Admin updated VIP flag",
        )
        conn.commit()
        conn.close()
        label = "VIP ✅" if flag == 1 else "Tiêu Chuẩn"
        await update.message.reply_text(f"✅ ID {target_id} → Hạng: {label}")
        await context.bot.send_message(
            chat_id=target_id,
            text=f"🎖️ Tài khoản của bạn đã được nâng lên hạng <b>{'VIP 💎' if flag else 'Tiêu Chuẩn'}</b>.",
            parse_mode="HTML"
        )
    except Exception:
        await update.message.reply_text("⚠️ Cú pháp: /setvip <ID> <1|0>")

async def cmd_backup_db(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    if flag_on("emergency_lock") and not is_owner_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Emergency mode: chỉ owner được chạy /backup_db.")
    db_path = str(DB_FILE or "")
    db_name = os.path.basename(db_path) or "toandaas_system.db"
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_filename = f"toan_aas_db_backup_{timestamp}.db"

    if not db_path or not os.path.exists(db_path):
        safe_path = db_path or db_file_health_label()
        record_audit_event(
            ADMIN_ID,
            "admin",
            "backup.failed",
            "database",
            db_name,
            after={"reason": "db_file_not_found", "db_file": db_file_health_label()},
            note="/backup_db DB file not found",
        )
        return await update.message.reply_text(
            "❌ <b>Không tìm thấy DB file để backup</b>\n\n"
            f"• Path: <code>{html.escape(safe_path)}</code>\n"
            "• Size: <code>unknown</code>\n"
            "• Gợi ý: kiểm tra biến <code>DB_FILE</code> hoặc Railway volume.",
            parse_mode="HTML",
        )

    try:
        conn = db_connect()
        try:
            conn.execute("PRAGMA wal_checkpoint(FULL)")
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        logger.warning(f"DB checkpoint before backup failed: {e}")

    size = os.path.getsize(db_path)
    if size > BACKUP_MAX_BYTES:
        safe_path = db_path or db_file_health_label()
        record_audit_event(
            ADMIN_ID,
            "admin",
            "backup.failed",
            "database",
            db_name,
            after={"reason": "file_too_large", "size": size, "limit": BACKUP_MAX_BYTES},
            note="/backup_db file too large for Telegram",
        )
        return await update.message.reply_text(
            "⚠️ <b>DB backup vượt giới hạn Telegram</b>\n\n"
            f"• Path: <code>{html.escape(safe_path)}</code>\n"
            f"• Size: <b>{size:,}</b> bytes\n"
            f"• Limit: <b>{BACKUP_MAX_BYTES:,}</b> bytes\n\n"
            "Hãy backup trực tiếp trên server/volume hoặc giảm dung lượng DB trước khi gửi qua Telegram.",
            parse_mode="HTML",
        )

    try:
        with open(db_path, "rb") as f:
            await context.bot.send_document(
                chat_id=ADMIN_ID,
                document=f,
                filename=backup_filename,
                caption=(
                    "🧩 <b>TOAN AAS DB Backup</b>\n\n"
                    f"• Time: <code>{timestamp}</code>\n"
                    f"• DB: <code>{html.escape(db_name)}</code>\n"
                    f"• Size: <b>{size:,}</b> bytes"
                ),
                parse_mode="HTML",
            )
        record_audit_event(
            ADMIN_ID,
            "admin",
            "backup.created",
            "database",
            db_name,
            after={"db_file": db_file_health_label(), "size": size, "filename": backup_filename},
            note="/backup_db sent to admin",
        )
    except Exception as e:
        logger.error(f"DB backup send error: {e}")
        safe_error = str(e)[:300]
        safe_path = db_path or db_file_health_label()
        record_audit_event(
            ADMIN_ID,
            "admin",
            "backup.failed",
            "database",
            db_name,
            after={"reason": "send_error", "error": str(e)[:300]},
            note="/backup_db send failed",
        )
        await update.message.reply_text(
            "❌ <b>Không gửi được backup DB qua Telegram</b>\n\n"
            f"• Path: <code>{html.escape(safe_path)}</code>\n"
            f"• Size: <b>{size:,}</b> bytes\n"
            f"• Error: <code>{html.escape(safe_error)}</code>",
            parse_mode="HTML",
        )

