async def handle_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message or not update.message.text:
        return
    text = update.message.text.strip()
    uid  = update.effective_user.id

    if await handle_trend_video_flow_pending_text(update, context):
        return

    if await handle_public_image_prompt_pending_text(update, context):
        return

    if await handle_public_video_prompt_pending_text(update, context):
        return

    if await handle_creative_motion_pending_text(update, context):
        return

    if await handle_cinematic_ad_pending_text(update, context):
        return

    if await handle_quick_media_pending_text(update, context):
        return

    normalized_music_command = normalize_music_inline_command_text(text)
    if normalized_music_command:
        handled = await dispatch_music_inline_command(update, context, normalized_music_command)
        if handled:
            return

    if text.startswith("/"):
        return await handle_unknown_or_unmatched_command(update, context)

    audio_url = extract_first_http_url(text)
    if audio_url and is_audio_link_url(audio_url):
        return await reply_audio_link_received(update, audio_url)

    if is_media_preview_url_text(text):
        return await reply_media_preview_url_hint(update)

    if is_probable_media_tags_text(text):
        return await reply_media_tags_hint(update)

    if text in {"🏠 TOAN AAS MENU", "🛸 MENU DỊCH VỤ TOAN AAS"}:
        return await cmd_start(update, context)

    modes = ensure_user_modes(uid)
    translate_target = modes.get("translate_mode_target") or ""
    if translate_target:
        return await handle_auto_translate_message(update, context, text, translate_target)

    detected_video_url = extract_supported_video_url(text)
    if detected_video_url:
        route = {"action": "download", "data": detected_video_url}
    else:
        if not gemini_client and not openai_client:
            return await update.message.reply_text("❌ Hệ thống AI chưa sẵn sàng (thiếu GEMINI_API_KEY và OPENAI_API_KEY).")
        try:
            route_raw = AgentGemini.chat(
                "Phân loại: 'voice' (đọc văn bản), 'download' (URL video), 'general' (còn lại). Trả về JSON.",
                text, uid, is_json=True
            )
            route = json.loads(route_raw)
        except Exception:
            route = {"action": "general", "data": text}

    act  = route.get("action", "general")
    data = route.get("data", text)
    size_calc = len(data) if act != "download" else 0
    action_key = act if act in ("voice", "download") else "chat"

    # ── LOGIC CHAT / TOOL CREDIT CHECK ───────────────────────────────────────
    is_admin = is_admin_user(uid)
    credits, total_spent, is_vip = get_user(uid)

    if action_key == "chat":
        mode_name = modes.get("chat_mode") or CHAT_TIER_NORMAL
        mode_name = normalize_chat_tier(mode_name or CHAT_TIER_NORMAL)
        base_cost = chat_mode_cost(mode_name)
        charge = effective_chat_charge(uid, mode_name, base_cost, is_admin=is_admin, is_legacy_vip=bool(is_vip))
        cost = int(charge["cost"])
        discount = 0.0
        warn = ""
        if cost > 0 and credits < cost:
            return await update.message.reply_text(chat_insufficient_credits_text(mode_name, cost, credits))
    else:
        # voice / download — voice được chọn provider trước; download trừ Xu trực tiếp.
        if action_key == "voice":
            free_voice_charge = apply_member_service_discount(uid, VOICE_FREE_COST, "spend_voice_free")
            min_voice_cost = 0 if is_admin else int(free_voice_charge.get("final_cost") or 0)
            if min_voice_cost and credits < min_voice_cost:
                return await reply_insufficient_credits(update, credits, min_voice_cost)
            cost, discount = 0, 0.0
        else:
            can_afford, cost, discount = deduct_dynamic_credit(uid, action_key, size_calc)
            if not can_afford:
                credits_now, _, _ = get_user(uid)
                return await reply_insufficient_credits(update, credits_now, cost)
        warn = ""

    if act == "voice":
        raw_cost_v = calculate_dynamic_cost("voice", size_calc)
        refund_charged_credit(uid, cost, "refund", "", "Hoàn phí phân loại voice trước khi khách chọn gói", True)
        fish_charge = apply_member_service_discount(uid, raw_cost_v, "spend_voice_paid")
        fish_cost = 0 if is_admin else int(fish_charge.get("final_cost") or 0)
        free_voice_charge = apply_member_service_discount(uid, VOICE_FREE_COST, "spend_voice_free")
        voice_free_cost = 0 if is_admin else int(free_voice_charge.get("final_cost") or 0)
        USER_PENDING[uid] = {
            "type": "voice",
            "data": data,
            "cost": fish_cost,
            "chat_id": update.effective_chat.id,
            "file_bytes": None,
            "premium_charged": False,
        }
        kb = provider_keyboard("voice", uid, fish_cost)
        if is_trial_account(uid):
            voice_desc = (
                f"🎙️ <b>Chọn gói đọc giọng nói:</b>\n\n"
                f"🔊 <b>Gói Tiết Kiệm</b> — Giọng chuẩn, trừ <b>{voice_free_cost} Xu</b>\n\n"
                f"<i>💡 Nạp tiền để mở khoá Gói Cao Cấp — giọng nhân bản siêu thực!</i>"
            )
        else:
            voice_desc = (
                f"🎙️ <b>Chọn gói đọc giọng nói:</b>\n\n"
                f"🎙️ <b>Gói Cao Cấp</b> — Giọng chất lượng cao, trừ <b>{fish_cost} Xu</b>\n"
                f"🔊 <b>Gói Tiết Kiệm</b> — Giọng chuẩn, trừ <b>{voice_free_cost} Xu</b>\n\n"
                f"<i>Nếu gói cao cấp lỗi/quota, hệ thống tự chuyển gói dự phòng và hoàn phần chênh lệch.</i>"
            )
        await update.message.reply_text(voice_desc, parse_mode="HTML", reply_markup=kb)
    elif act == "download":
        await AgentDownloader.download(data, context, update.effective_chat.id, cost, uid)
    else:
        await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")
        mode_name = normalize_chat_tier((modes.get("chat_mode") or CHAT_TIER_NORMAL))
        mode_instruction = chat_mode_instruction(mode_name)
        username = update.effective_user.username or update.effective_user.first_name or ""
        record_usage_event(
            uid,
            username=username,
            event_type="tool_use",
            tool_name="ai_chat",
            command="text_chat",
            status=mode_name,
        )
        result = await call_ai_chat_with_fallback(mode_instruction, text, uid, max_tokens=1800 if mode_name == CHAT_TIER_DEEP else 1200)
        if not result.get("ok"):
            detail = ai_failure_detail(result.get("statuses") or {}, result.get("errors") or {})
            record_usage_event(
                uid,
                username=username,
                event_type="tool_fail",
                tool_name="ai_chat",
                command="text_chat",
                status="provider_fail",
                provider="ai_router",
                detail=detail,
            )
            save_tool_test_result("ai_chat", "FAIL", detail, uid)
            return await update.message.reply_text(result.get("message") or ai_failure_user_text(result.get("statuses") or {}, result.get("errors") or {}))

        if cost > 0 and not spend_fixed_credit_info(uid, cost, f"spend_ai_chat_{mode_name}", f"AI chat {mode_name}", apply_member_discount_flag=False).get("ok"):
            credits_now, _, _ = get_user(uid)
            return await update.message.reply_text(chat_insufficient_credits_text(mode_name, cost, credits_now))

        provider = result.get("provider") or "ai_router"
        reply = result.get("text") or ""
        credits_after, _, _ = get_user(uid)
        if cost > 0:
            cost_line = f"\n\n<i>{chat_charge_line(cost, mode_name)}</i>"
            warn = (
                f"\n\n💼 <i>Số dư còn lại: <b>{credits_after} Xu</b> | /naptien để nạp thêm</i>"
                if credits_after < 200 else
                f"\n\n💼 <i>Còn: {credits_after} Xu</i>"
            )
        else:
            cost_line = f"\n\n<i>{chat_charge_line(cost, mode_name, cost == 0, charge.get('reason') or '')}</i>"
        record_usage_event(
            uid,
            username=username,
            event_type="tool_success",
            tool_name="ai_chat",
            command="text_chat",
            status=mode_name,
            provider=provider,
            xu_delta=-int(cost or 0),
            detail=f"tier={charge['tier']}; base={charge['base_cost']}; cost={charge['cost']}; benefit={charge.get('reason') or '-'}",
        )
        save_tool_test_result("ai_chat", "PASS", f"provider={provider}; mode={mode_name}; base={charge['base_cost']}; cost={cost}; tier={charge['tier']}", uid)
        await update.message.reply_text(
            f"🤖 {html.escape(reply)}{cost_line}{warn}{active_mode_hint(uid)}",
            parse_mode="HTML"
        )

