# ─── WEBHOOK PAYOS (DYNAMIC UPDATED) ─────────────────────────────────────────
def verify_payos_signature(data: dict, received_sig: str) -> bool:
    if not PAYOS_CHECKSUM_KEY:
        return False
    sorted_keys = sorted(data.keys())
    raw_str = "&".join(f"{k}={data[k]}" for k in sorted_keys)
    computed = hmac.new(
        PAYOS_CHECKSUM_KEY.encode("utf-8"),
        raw_str.encode("utf-8"),
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(computed, received_sig)

@fastapi_app.post("/webhook/payos")
async def webhook_payos(request: Request):
    """
    PayOS gọi Webhook tự động sau khi giao dịch QR động thành công.
    Tự đối chiếu orderCode nội bộ để cộng Xu mà khách không cần điền nội dung.
    """
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON")

    if flag_on("emergency_lock") or flag_on("payment_freeze"):
        record_anomaly(
            "payos_webhook_blocked_by_safe_mode",
            "medium",
            "PayOS webhook received while emergency/payment freeze is active",
            user_id="payos",
            username="payos",
            auto_lock=False,
        )
        return JSONResponse({"code": "00", "desc": "payment_frozen"})

    sig  = body.get("signature", "")
    data = body.get("data", {})

    if not PAYOS_CHECKSUM_KEY:
        logger.warning("PayOS webhook rejected: PAYOS_CHECKSUM_KEY is not configured")
        raise HTTPException(status_code=500, detail="PayOS checksum key not configured")

    if not verify_payos_signature(data, sig):
        logger.warning("PayOS webhook: chữ ký xác thực không hợp lệ!")
        raise HTTPException(status_code=400, detail="Invalid signature")

    if not (body.get("success") or data.get("status") == "PAID"):
        return JSONResponse({"code": "00", "desc": "ignored"})

    order_code = str(data.get("orderCode", data.get("order_code", "")))
    try:
        amount_vnd = int(data.get("amount", 0))
    except (TypeError, ValueError):
        logger.warning(f"PayOS webhook: amount không hợp lệ | order={order_code} | data={data}")
        return JSONResponse({"code": "00", "desc": "invalid_amount"})

    processed, desc, info = process_payos_paid_order(order_code, amount_vnd)
    if not processed:
        logger.warning(f"PayOS webhook ignored: {desc} | order={order_code} | amount={amount_vnd} | info={info}")
        return JSONResponse({"code": "00", "desc": desc})

    if info.get("order_type") == "plan_purchase":
        target_id = info["target_id"]
        logger.info(f"✅ PayOS plan purchase success plan={info.get('plan_id')} user={target_id} | Đơn: {order_code}")
        if tg_app:
            try:
                await tg_app.bot.send_message(
                    chat_id=target_id,
                    text=plan_success_message(info),
                    parse_mode="HTML",
                )
                await tg_app.bot.send_message(
                    chat_id=ADMIN_ID,
                    text=(
                        "📦 <b>AUTO PLAN PAYOS SUCCESS</b>\n\n"
                        f"🆔 User: <code>{html.escape(str(target_id))}</code>\n"
                        f"📦 Gói: <b>{html.escape(info.get('plan_name') or '')}</b>\n"
                        f"💰 Số tiền: <b>{amount_vnd:,}đ</b>\n"
                        f"📋 Order Code: <code>{html.escape(str(order_code))}</code>\n"
                        "Không tính vào tổng nạp nâng hạng; không chạy launch bonus."
                    ),
                    parse_mode="HTML",
                )
            except Exception as e:
                logger.error(f"Plan notify error: {e}")
        return JSONResponse({"code": "00", "desc": "plan_success"})

    target_id = info["target_id"]
    xu = info["xu"]
    launch_bonus = int(info.get("launch_bonus", 0) or 0)
    promo_bonus = int(info.get("promo_bonus", 0) or 0)
    promo_code = info.get("promo_code") or ""
    referral_bonus = info.get("referral_bonus", 0)
    referral_result = info.get("referral_result") or {}
    credits_now, _, _ = get_user(target_id)
    launch_line = f"🎁 Launch Bonus: <b>+{launch_bonus} Xu</b>\n" if launch_bonus else ""
    promo_line = (
        f"🎁 <code>{html.escape(promo_code)}</code>: <b>+{promo_bonus} Xu</b>\n"
        if promo_bonus else ""
    )
    total_line = f"🧾 Tổng cộng đơn này: <b>+{int(xu) + launch_bonus + promo_bonus} Xu</b>\n"
    logger.info(f"✅ PayOS dynamic QR nạp thành công {int(xu) + launch_bonus + promo_bonus} Xu cho {target_id} | Đơn: {order_code}")

    if tg_app:
        try:
            await tg_app.bot.send_message(
                chat_id=target_id,
                text=(
                    f"🎉 <b>NẠP TỰ ĐỘNG THÀNH CÔNG!</b>\n\n"
                    f"✅ PayOS xác nhận cổng QR Động trực tuyến!\n"
                    f"💰 Số tiền giao dịch: <b>{amount_vnd:,}đ</b>\n"
                    f"🪙 Xu gốc: <b>+{xu} Xu</b>\n"
                    f"{launch_line}"
                    f"{promo_line}"
                    f"{total_line}"
                    f"💼 Số dư tài khoản hiện tại: <b>{credits_now} Xu</b>\n\n"
                    f"Cảm ơn bạn đã tin dùng dịch vụ TOAN AAS! 🙏"
                ),
                parse_mode="HTML"
            )
            tier_message = format_tier_up_message(info.get("tier_up_result") or {})
            if tier_message:
                await tg_app.bot.send_message(chat_id=target_id, text=tier_message, parse_mode="HTML")
            if int(referral_result.get("reward_xu") or 0) > 0:
                referrer_id = str(referral_result.get("referrer_user_id") or "")
                ref_credits, _, _ = get_user(referrer_id)
                await tg_app.bot.send_message(
                    chat_id=referrer_id,
                    text=(
                        "🎉 <b>Bạn vừa nhận thưởng giới thiệu TOAN AAS</b>\n\n"
                        "• Người được mời đã nạp Xu lần đầu thành công.\n"
                        f"• Cấp của bạn: <b>{html.escape(referral_result.get('tier_badge') or referral_result.get('tier_label') or '')}</b>\n"
                        f"• Thưởng giới thiệu: +<b>{int(referral_result.get('reward_xu') or 0)} Xu dịch vụ</b>\n"
                        f"• Số dư mới: <b>{ref_credits} Xu</b>"
                    ),
                    parse_mode="HTML",
                )
            await tg_app.bot.send_message(
                chat_id=ADMIN_ID,
                text=(
                    f"💸 <b>AUTO NẠP PAYOS (QR ĐỘNG SUCCESS)</b>\n\n"
                    f"🆔 Khách hàng: <code>{target_id}</code>\n"
                    f"💰 {amount_vnd:,}đ → base +{xu} Xu\n"
                    f"🎁 Launch bonus: <b>{launch_bonus} Xu</b>\n"
                    f"🎁 Promo bonus: <b>{promo_bonus} Xu</b>\n"
                    f"📋 Order Code: <code>{order_code}</code>\n"
                    f"🎁 Referral bonus: <b>{referral_bonus} Xu</b>"
                ),
                parse_mode="HTML"
            )
        except Exception as e:
            logger.error(f"Notify error: {e}")

    return JSONResponse({"code": "00", "desc": "success"})

